export const POETS = [{"id": 1, "name": "陶渊明", "zi": "元亮", "hao": "五柳先生", "dynasty": "魏晋", "years": "约365-427", "title": "田园诗祖", "intro": "东晋诗人。曾任彭泽县令，八十余日即辞官归隐，此后躬耕田园二十余年。开创田园诗派，\"采菊东篱下\"成为中国人心中隐逸生活的代名词。", "story": "义熙元年冬，彭泽县衙来了新县令。恰逢郡里督邮来视察，属吏提醒他束带迎接。陶渊明叹了口气：\"吾不能为五斗米折腰，拳拳事乡里小人邪！\"当天解下印绶，回家写了那篇著名的《归去来兮辞》。\n此后二十余年，他真的种地、酿酒、写诗。地里种秫谷专供酿酒，朋友颜延之留下二万钱，他全数送到酒家，日后陆续去取酒喝。\n穷到什么地步？《乞食》里写自己饿得出门讨饭，主人端出酒菜，他不知如何答谢，索性写诗相赠。可就是这个讨饭的人，替此后一千多年的中国文人守住了一片\"心远地自偏\"的精神田园。", "storyTitle": "不为五斗米折腰", "journey": "[{\"place\": \"浔阳柴桑\", \"modern\": \"江西九江西南\", \"lon\": 115.89, \"lat\": 29.62, \"period\": \"365—393 · 少年耕读\", \"event\": \"出身没落仕宦之家，少怀「猛志逸四海」；几度出仕，皆因亲老家贫、口腹自役。\", \"poems\": []}, {\"place\": \"江陵\", \"modern\": \"湖北荆州\", \"lon\": 112.19, \"lat\": 30.33, \"period\": \"398—401 · 幕府生涯\", \"event\": \"入桓玄幕府，看尽门阀倾轧、宦海浮沉，归意渐生。\", \"poems\": []}, {\"place\": \"彭泽\", \"modern\": \"江西彭泽\", \"lon\": 116.55, \"lat\": 29.9, \"period\": \"405 · 八十余日\", \"event\": \"为彭泽令，郡遣督邮至，吏白应束带见之；叹曰「吾不能为五斗米折腰，拳拳事乡里小人邪」，即日解印绶去职，赋《归去来兮辞》。\", \"poems\": []}, {\"place\": \"柴桑 · 归隐\", \"modern\": \"江西九江\", \"lon\": 115.92, \"lat\": 29.58, \"period\": \"405—427 · 采菊东篱\", \"event\": \"躬耕南山，把酒东篱，与庐山高僧往还，隐居终老。结庐人境，心远地偏，悠然见山。\", \"poems\": [1, 2]}]"}, {"id": 2, "name": "李白", "zi": "太白", "hao": "青莲居士", "dynasty": "唐", "years": "701-762", "title": "诗仙", "intro": "唐代伟大的浪漫主义诗人，诗风豪放飘逸、想象瑰奇。一生漫游天下，剑术、诗文、酒量皆名动一时。存诗近千首。", "story": "天宝元年，李白奉诏入京，玄宗\"降辇步迎，以七宝床赐食，御手调羹\"。可他很快发现，皇帝要的只是一个点缀升平的词臣，不是经世济民的谋士。\n于是他纵酒狂歌。传说醉中奉诏草诏，竟伸脚让高力士脱靴，让贵妃捧砚。谤谤由此而起，不到两年，玄宗\"赐金放还\"——体面地请走了他。\n离开长安那年，他在灞桥写下\"行路难\"；可转身又说\"长风破浪会有时\"。这就是李白：仕途从未顺遂，笔下从未低头。杜甫形容他\"笔落惊风雨，诗成泣鬼神\"，一千多年后，我们抬头看月亮，仍会想起他的床前霜。", "storyTitle": "仰天大笑出门去", "journey": "[{\"place\": \"绵州 · 青莲乡\", \"modern\": \"四川江油\", \"lon\": 104.75, \"lat\": 31.77, \"period\": \"701—724 · 蜀中\", \"event\": \"五岁诵六甲，十岁观百家；十五好剑术，二十五「仗剑去国，辞亲远游」。\", \"poems\": []}, {\"place\": \"扬州\", \"modern\": \"江苏扬州\", \"lon\": 119.42, \"lat\": 32.39, \"period\": \"726 · 二十六岁\", \"event\": \"漫游吴会，秋病卧扬州旅舍，客夜霜白，举头见月而成《静夜思》。\", \"poems\": [3]}, {\"place\": \"安陆\", \"modern\": \"湖北安陆\", \"lon\": 113.69, \"lat\": 31.26, \"period\": \"727—736\", \"event\": \"娶故相许圉师孙女，「酒隐安陆，蹉跎十年」。\", \"poems\": []}, {\"place\": \"长安\", \"modern\": \"陕西西安\", \"lon\": 108.94, \"lat\": 34.27, \"period\": \"742—744 · 翰林供奉\", \"event\": \"奉诏入京，供奉翰林；醉草诏书、力士脱靴，终为权贵所谗，赐金放还。花间一壶酒，对影成三人。\", \"poems\": [5]}, {\"place\": \"宣城\", \"modern\": \"安徽宣城\", \"lon\": 118.76, \"lat\": 30.95, \"period\": \"753—761 · 往来宣城\", \"event\": \"晚年屡游宣城，相看两不厌，只有敬亭山。\", \"poems\": []}, {\"place\": \"庐山\", \"modern\": \"江西庐山\", \"lon\": 115.98, \"lat\": 29.56, \"period\": \"756 · 屏风叠\", \"event\": \"初游庐山有「飞流直下三千尺」；是岁隐屏风叠，永王璘三聘入幕，由此罹祸。\", \"poems\": [4]}, {\"place\": \"白帝城\", \"modern\": \"重庆奉节\", \"lon\": 109.58, \"lat\": 31.04, \"period\": \"759 · 流放遇赦\", \"event\": \"坐永王案长流夜郎，溯江而上，行至白帝城遇赦——朝辞彩云间，千里江陵一日还。\", \"poems\": [6]}, {\"place\": \"当涂\", \"modern\": \"安徽当涂\", \"lon\": 118.5, \"lat\": 31.57, \"period\": \"762\", \"event\": \"投族叔当涂令李阳冰，枕上授简；病殁，传说醉中入水捉月骑鲸而去。\", \"poems\": []}]"}, {"id": 3, "name": "王维", "zi": "摩诘", "hao": "摩诘居士", "dynasty": "唐", "years": "约701-761", "title": "诗佛", "intro": "唐代山水田园诗代表，兼通音律、书画。苏轼评其\"诗中有画，画中有诗\"。晚年半官半隐于辋川，写下一系列空灵澄澈的山水绝唱。", "story": "王维的人生在四十岁那年劈成两半。前半生是少年得意：二十一岁进士及第，一曲《郁轮袍》名动公卿，状元及第，仕途坦荡。\n安史之乱中，他被叛军俘获，被迫任伪职。乱平后，凡受伪职者论罪，他因写过哀痛的《凝碧池》诗、且弟王缙请削己职为兄赎罪，方得免究。\n从此他\"晚年唯好静，万事不关心\"，半官半隐于辋川别业，与裴迪泛舟唱和，写《鹿柴》，写《山居秋暝》。水墨从此替代了颜色，\"空山\"替代了庙堂。他在诗里活成了自己的桃花源。", "storyTitle": "诗中有画，画中有诗", "journey": "[{\"place\": \"蒲州\", \"modern\": \"山西永济\", \"lon\": 110.28, \"lat\": 34.85, \"period\": \"701—715\", \"event\": \"祖籍太原祁县，父迁蒲州；少年聪颖，通音律、善书画。\", \"poems\": []}, {\"place\": \"长安\", \"modern\": \"陕西西安\", \"lon\": 108.94, \"lat\": 34.27, \"period\": \"715—737 · 两京游历\", \"event\": \"十七岁独在异乡，重阳忆蒲州兄弟；二十一进士夺魁，为太乐丞，仕途几起几落。\", \"poems\": [9, 10]}, {\"place\": \"凉州\", \"modern\": \"甘肃武威\", \"lon\": 102.64, \"lat\": 37.93, \"period\": \"737 · 出塞\", \"event\": \"以监察御史出塞宣慰河西，大漠孤烟直，长河落日圆，诗境为之一阔。\", \"poems\": []}, {\"place\": \"辋川\", \"modern\": \"陕西蓝田\", \"lon\": 108.92, \"lat\": 34.09, \"period\": \"741—761 · 半官半隐\", \"event\": \"得宋之问蓝田别墅，与裴迪泛舟唱和，弹琴赋诗；安史乱后笃志奉佛，晚官尚书右丞，空山新雨、竹喧莲动皆成绝唱。\", \"poems\": [7, 8]}]"}, {"id": 4, "name": "杜甫", "zi": "子美", "hao": "少陵野老", "dynasty": "唐", "years": "712-770", "title": "诗圣", "intro": "唐代现实主义诗人。历经安史之乱，诗风沉郁顿挫，深刻记录了时代苦难，其诗被后世称为\"诗史\"。与李白并称\"李杜\"。", "story": "杜甫的后半生，几乎就是一部安史之乱的编年史。\n长安十年求官，他写\"朝扣富儿门，暮随肥马尘\"。乱起，他被困在沦陷的长安，写下\"国破山河在，城春草木深\"。逃至凤翔见肃宗，得授左拾遗，又因营救房琯被贬。\n弃官入蜀，成都浣花溪畔的草堂是他难得的安稳岁月，\"两个黄鹂鸣翠柳\"就写于此时。好友严武去世，他失去依靠，携家漂泊夔州、湖湘。\n大历五年冬，五十九岁的杜甫病逝于湘江一条小舟上。临终前，他惦记的仍是\"战血流依旧，军声动至今\"。他一生没有过上几天好日子，却始终替苍生写诗。", "storyTitle": "诗史：用一生记录一个时代", "journey": "[{\"place\": \"洛阳 · 巩县\", \"modern\": \"河南巩义\", \"lon\": 113.02, \"lat\": 34.75, \"period\": \"712—735\", \"event\": \"生于巩县瑶湾，七龄思即壮，开口咏凤凰。\", \"poems\": []}, {\"place\": \"长安\", \"modern\": \"陕西西安\", \"lon\": 108.94, \"lat\": 34.27, \"period\": \"746—755 · 困守十年\", \"event\": \"应诏就试，朝扣富儿门，暮随肥马尘；安史乱起身陷长安，国破山河在，感时花溅泪。\", \"poems\": [11]}, {\"place\": \"秦州\", \"modern\": \"甘肃天水\", \"lon\": 105.72, \"lat\": 34.58, \"period\": \"759 · 弃官西行\", \"event\": \"弃官携家流寓秦州，露从今夜白，月是故乡明。\", \"poems\": [13]}, {\"place\": \"成都\", \"modern\": \"四川成都\", \"lon\": 104.07, \"lat\": 30.67, \"period\": \"760—765 · 草堂\", \"event\": \"得故人严武相助，浣花溪畔筑草堂，暂得安顿；好雨知时节，随风潜入夜。\", \"poems\": [12]}, {\"place\": \"夔州\", \"modern\": \"重庆奉节\", \"lon\": 109.46, \"lat\": 31.02, \"period\": \"766—768\", \"event\": \"寓夔州两年，登白帝高台，无边落木萧萧下，不尽长江滚滚来。\", \"poems\": [14]}, {\"place\": \"岳阳\", \"modern\": \"湖南岳阳\", \"lon\": 113.09, \"lat\": 29.36, \"period\": \"768—770\", \"event\": \"漂泊湖湘，亲朋无一字，老病有孤舟；卒于潭岳间湘江舟中。\", \"poems\": []}]"}, {"id": 5, "name": "白居易", "zi": "乐天", "hao": "香山居士", "dynasty": "唐", "years": "772-846", "title": "诗魔", "intro": "中唐诗人，倡导新乐府运动，主张\"文章合为时而著，歌诗合为事而作\"。《长恨歌》《琵琶行》为千古绝唱。诗风浅切平易，流传极广。", "story": "白居易写诗有个执念：让不识字的老太太也能听懂。据说每写完一首，先念给老婆婆听，\"问曰：解否？\"解则录之，不解则改。这便是\"老妪能解\"的典故。\n他确实做到了。《长恨歌》问世后传诵天下，歌女会背便自抬身价：\"我诵得白学士《长恨歌》，岂同他妓哉！\"连皇帝都感慨：童子解吟长恨曲，胡儿能唱琵琶篇。\n元和十年被贬江州司马，浔阳江头夜遇琵琶女，写\"同是天涯沦落人，相逢何必曾相识\"。晚年居洛阳香山，自号香山居士，与刘禹锡诗酒唱和，活成了唐代诗人里少有的长寿与通达。", "storyTitle": "老妪能解", "journey": "[{\"place\": \"新郑\", \"modern\": \"河南新郑\", \"lon\": 113.74, \"lat\": 34.4, \"period\": \"772—780\", \"event\": \"生于新郑东郭宅，兵乱早年随家迁避。\", \"poems\": []}, {\"place\": \"符离\", \"modern\": \"安徽宿州\", \"lon\": 117.32, \"lat\": 33.66, \"period\": \"782—799\", \"event\": \"避地符离，苦节读书——口舌成疮，手肘成胝。\", \"poems\": []}, {\"place\": \"长安\", \"modern\": \"陕西西安\", \"lon\": 108.94, \"lat\": 34.27, \"period\": \"787 · 行卷\", \"event\": \"十六岁以《赋得古原草送别》投谒顾况；况戏曰「长安米贵，居大不易」，及读「野火烧不尽」，叹曰「有句如此，居天下有甚难」。\", \"poems\": [15]}, {\"place\": \"江州\", \"modern\": \"江西九江\", \"lon\": 115.99, \"lat\": 29.71, \"period\": \"815—818 · 贬谪\", \"event\": \"武元衡案贬江州司马，浔阳江头夜送客，忽闻水上琵琶声——江州司马青衫湿。\", \"poems\": []}, {\"place\": \"杭州\", \"modern\": \"浙江杭州\", \"lon\": 120.16, \"lat\": 30.25, \"period\": \"822—824 · 刺杭州\", \"event\": \"赴杭道上吟「半江瑟瑟半江红」；守杭浚六井、筑堤蓄湖，最爱湖东行不足，绿杨阴里白沙堤。\", \"poems\": [16, 17]}, {\"place\": \"洛阳\", \"modern\": \"河南洛阳\", \"lon\": 112.45, \"lat\": 34.62, \"period\": \"829—846\", \"event\": \"晚居履道里，自号香山居士，与刘禹锡诗酒唱和，卒葬龙门香山。\", \"poems\": []}]"}, {"id": 6, "name": "苏轼", "zi": "子瞻", "hao": "东坡居士", "dynasty": "宋", "years": "1037-1101", "title": "坡仙", "intro": "北宋文学家、书画家，豪放词开创者。诗、词、文、书、画皆臻一流，\"唐宋八大家\"之一。一生三起三落，愈贬愈旷达。", "story": "元丰二年，御史摘录苏轼诗文弹劾他讥讽朝政，他被押赴御史台狱一百三十天，几死于狱中——史称\"乌台诗案\"。出狱后贬为黄州团练副使，不得签书公事。\n俸禄断绝，他在城东坡地开荒种麦，自号\"东坡居士\"。就是在黄州，他写了《念奴娇·赤壁怀古》和前后《赤壁赋》，也写了被贬的豁达：\"竹杖芒鞋轻胜马，谁怕？一蓑烟雨任平生。\"\n此后他一贬再贬：惠州，\"日啖荔枝三百颗\"；儋州，垂老投荒，他却办学堂、教书育人。建中靖国元年遇赦北归，途中病逝常州。临终前，友人说此行即便无生还可能也勿哭，他答：无生还可能，也无须哭。一生大起大落，他始终把苦难过成了诗。", "storyTitle": "一蓑烟雨任平生", "journey": "[{\"place\": \"眉山\", \"modern\": \"四川眉山\", \"lon\": 103.85, \"lat\": 30.05, \"period\": \"1037—1056\", \"event\": \"眉州眉山人；程夫人授《范滂传》，慨然有澄清天下之志。\", \"poems\": []}, {\"place\": \"汴京\", \"modern\": \"河南开封\", \"lon\": 114.31, \"lat\": 34.8, \"period\": \"1057—1071\", \"event\": \"嘉祐二年进士，欧阳修见其书曰「吾当避此人出一头地」；与新党不合，自请外任。\", \"poems\": []}, {\"place\": \"杭州\", \"modern\": \"浙江杭州\", \"lon\": 120.16, \"lat\": 30.25, \"period\": \"1071—1074 通判 · 1089—1091 再知\", \"event\": \"初为杭州通判，「欲把西湖比西子，淡妆浓抹总相宜」；十八年后再知杭州，疏浚西湖、筑苏堤，三潭印月自此始。\", \"poems\": [19], \"lx\": -25, \"ly\": 30}, {\"place\": \"密州\", \"modern\": \"山东诸城\", \"lon\": 119.41, \"lat\": 35.99, \"period\": \"1074—1076 · 知州\", \"event\": \"知密州，西北望，射天狼；丙辰中秋欢饮达旦，怀子由而作水调歌头，明月几时有。\", \"poems\": [18]}, {\"place\": \"徐州\", \"modern\": \"江苏徐州\", \"lon\": 117.18, \"lat\": 34.26, \"period\": \"1077—1079\", \"event\": \"知徐州，黄河决口汇于城下，庐于城上，率军民抗洪七十余日。\", \"poems\": []}, {\"place\": \"湖州\", \"modern\": \"浙江湖州\", \"lon\": 120.09, \"lat\": 30.87, \"period\": \"1079 · 乌台诗案\", \"event\": \"知湖州三月，以诗文讪谤朝政下御史台狱，系狱百三十日，几死。\", \"poems\": [], \"ly\": 22}, {\"place\": \"黄州\", \"modern\": \"湖北黄冈\", \"lon\": 114.87, \"lat\": 30.45, \"period\": \"1080—1084 · 谪居\", \"event\": \"贬黄州团练副使，躬耕城东坡地，自号东坡居士；两赋一词，从此天下称苏东坡。\", \"poems\": []}, {\"place\": \"庐山\", \"modern\": \"江西庐山\", \"lon\": 115.98, \"lat\": 29.56, \"period\": \"1084 · 途经\", \"event\": \"量移汝州，道经庐山，横看成岭侧成峰，题诗西林寺壁。\", \"poems\": [20]}, {\"place\": \"惠州\", \"modern\": \"广东惠州\", \"lon\": 114.42, \"lat\": 23.11, \"period\": \"1094—1097\", \"event\": \"绍圣再贬惠州，日啖荔枝三百颗，不辞长作岭南人。\", \"poems\": []}, {\"place\": \"儋州\", \"modern\": \"海南儋州\", \"lon\": 109.58, \"lat\": 19.52, \"period\": \"1097—1100 · 天涯\", \"event\": \"责授琼州别驾、昌化军安置，渡海讲学明道；海南破天荒出进士，自公始。\", \"poems\": []}, {\"place\": \"常州\", \"modern\": \"江苏常州\", \"lon\": 119.95, \"lat\": 31.78, \"period\": \"1101\", \"event\": \"遇赦自海南北归，七月二十八日卒于常州；葬汝州郏城县，号小峨眉。\", \"poems\": []}]"}, {"id": 7, "name": "李清照", "zi": "", "hao": "易安居士", "dynasty": "宋", "years": "1084-约1155", "title": "千古第一才女", "intro": "宋代婉约词代表。前期词清丽明快，南渡后因国破家亡、丈夫病逝而转为沉郁凄怆。提出词\"别是一家\"之说，有《漱玉词》传世。", "story": "李清照与赵明诚的婚姻，是文学史上著名的美谈。夫妻共治金石、校书填词，饭后烹茶，指堆积书史，言某事在某书某卷第几页，以中否赌胜负——\"中即举杯大笑，至茶倾覆怀中\"。赌书泼茶，成了后世羡慕了千年的闺中雅事。\n靖康之变，金石书画在流亡中散失殆尽；建炎三年，赵明诚病逝建康。她携残册追随朝廷流寓江南，晚境孤苦，改嫁遇人不淑，宁受牢狱之灾也要讼离。\n早年她写\"兴尽晚回舟\"，晚年只剩\"寻寻觅觅，冷冷清清\"。一个人的词风，量出了一整个时代的伤口。", "storyTitle": "赌书消得泼茶香", "journey": "[{\"place\": \"济南 · 明水\", \"modern\": \"山东济南\", \"lon\": 117.12, \"lat\": 36.65, \"period\": \"1084—1101\", \"event\": \"生于齐州章丘明水，父李格非为苏门后四学士；少女时代溪亭日暮，沉醉不知归路。\", \"poems\": [21]}, {\"place\": \"汴京\", \"modern\": \"河南开封\", \"lon\": 114.31, \"lat\": 34.8, \"period\": \"1101—1127\", \"event\": \"与太学生赵明诚成婚，赌书泼茶，共撰《金石录》；书画词章，名动京师。\", \"poems\": []}, {\"place\": \"青州\", \"modern\": \"山东青州\", \"lon\": 118.48, \"lat\": 36.69, \"period\": \"1107—1127 · 归来堂\", \"event\": \"屏居青州乡里十年，易安室归来堂，节衣缩食以聚书，极文墨之乐。\", \"poems\": []}, {\"place\": \"江宁\", \"modern\": \"江苏南京\", \"lon\": 118.8, \"lat\": 32.06, \"period\": \"1128—1129\", \"event\": \"靖康之变，仓皇南渡；明诚知建康府，感怀京洛旧事，寻寻觅觅已自北地始。\", \"poems\": []}, {\"place\": \"金华\", \"modern\": \"浙江金华\", \"lon\": 119.65, \"lat\": 29.08, \"period\": \"1134\", \"event\": \"避乱金华，闻双溪春尚好——只恐双溪舴艋舟，载不动许多愁。\", \"poems\": []}, {\"place\": \"临安\", \"modern\": \"浙江杭州\", \"lon\": 120.16, \"lat\": 30.25, \"period\": \"1132—1155\", \"event\": \"流寓临安，物是人非事事休；晚境凄凉，改嫁离异、金石散尽，卒年不可考。\", \"poems\": [22]}]"}, {"id": 8, "name": "辛弃疾", "zi": "幼安", "hao": "稼轩", "dynasty": "宋", "years": "1140-1207", "title": "词中之龙", "intro": "南宋豪放词代表，与苏轼并称\"苏辛\"。生于金占区，二十一岁聚众起义，曾率五十骑夜袭金营生擒叛将。一生力主北伐而不获用，把壮志都写进了词。", "story": "辛弃疾本是武将。二十一岁在金占区聚众两千起义，归附耿京；叛徒义端窃印逃跑，他单骑追斩；后来耿京被叛徒张安国所害，他率五十骑直闯五万人的金营，生擒张安国，缚于马上，渡江献俘——那年他二十三岁。\n南归后他却再也回不了前线。朝廷忌惮其\"归正人\"身份，四十年间三度起用、屡遭弹劾，闲居带湖、瓢泉近二十年。他把金戈铁马都写进词里：\"醉里挑灯看剑，梦回吹角连营。\"\n开禧三年秋，传说病重中的辛弃疾大呼\"杀贼\"数声而逝。他终究没能马踏胡尘，却以六百余首词，成了宋词里的最后一个骑士。", "storyTitle": "醉里挑灯看剑", "journey": "[{\"place\": \"济南 · 历城\", \"modern\": \"山东济南\", \"lon\": 117.12, \"lat\": 36.65, \"period\": \"1140—1161\", \"event\": \"生于金占区，祖父辛赞携以登高望远，指画山河；二十二岁聚众二千起义，率五十骑闯五万人金营，生擒叛将张安国。\", \"poems\": []}, {\"place\": \"临安\", \"modern\": \"浙江杭州\", \"lon\": 120.16, \"lat\": 30.25, \"period\": \"1162 · 献俘南归\", \"event\": \"押张安国献俘行在，脱身南归；「归正人」三字，自此伴其一生。\", \"poems\": []}, {\"place\": \"建康\", \"modern\": \"江苏南京\", \"lon\": 118.8, \"lat\": 32.06, \"period\": \"1168—1175\", \"event\": \"通判建康、参赞军务，楚天千里清秋，登赏心亭，把吴钩看了，栏杆拍遍。\", \"poems\": []}, {\"place\": \"带湖 · 上饶\", \"modern\": \"江西上饶\", \"lon\": 117.97, \"lat\": 28.45, \"period\": \"1182—1192 · 闲居\", \"event\": \"落职闲居带湖新居，醉里挑灯看剑，梦回吹角连营；夜行黄沙道中，听取蛙声一片。\", \"poems\": [23, 24]}, {\"place\": \"瓢泉 · 铅山\", \"modern\": \"江西铅山\", \"lon\": 117.71, \"lat\": 28.32, \"period\": \"1196—1207\", \"event\": \"再迁瓢泉，起用复罢者再；开禧北伐之际朝廷欲用，病笃辞免，九月十日忧愤而卒，临终大呼「杀贼」数声。\", \"poems\": []}]"}, {"id": 9, "name": "曹操", "zi": "孟德", "hao": "", "dynasty": "魏晋", "years": "155—220", "title": "建安风骨", "intro": "汉末杰出的政治家、军事家、诗人，建安文学的开创者。「外定武功，内兴文学」，与曹丕、曹植并称三曹，慷慨悲凉，气韵沉雄。", "story": "他是乱世里真正的多面手：挟天子以令诸侯，屯田足食，扫平北方；铜雀台上横槊赋诗，把政治家的胸襟写成了诗。他对文学只以「相王之尊」提倡雅爱，却凭一己之力抬高了一个时代的声音。\n鲁迅说他「至少是一个英雄」。建安风骨的「风骨」二字，一半是他杀伐决断的棱角，一半是他诗里那声「白骨露于野，千里无鸡鸣」的悲悯。", "storyTitle": "横槊赋诗", "journey": "[\n {\"place\":\"洛阳\",\"modern\":\"河南洛阳\",\"lon\":112.45,\"lat\":34.62,\"period\":\"155—189 · 少年起家\",\"event\":\"生于沛国谯县，二十岁举孝廉入洛阳为郎，五色棒悬门，夜巡不避豪贵。\",\"poems\":[]},\n {\"place\":\"陈留 · 己吾\",\"modern\":\"河南开封\",\"lon\":114.40,\"lat\":34.65,\"period\":\"189 · 散家财起兵\",\"event\":\"董卓乱政，变易姓名间行东归，陈留起兵讨卓；行军所见「白骨露于野」，遂有蒿里之悲。\",\"poems\":[28]},\n {\"place\":\"官渡\",\"modern\":\"河南中牟\",\"lon\":113.90,\"lat\":34.72,\"period\":\"200 · 决战\",\"event\":\"以弱胜强大破袁绍，为统一北方奠定基业。\",\"poems\":[]},\n {\"place\":\"邺城\",\"modern\":\"河北临漳\",\"lon\":114.61,\"lat\":36.33,\"period\":\"204—220 · 王都\",\"event\":\"定邺为都，建铜雀台，曹氏父子与建安诸子宴饮赋诗，开一代文风。\",\"poems\":[]},\n {\"place\":\"碣石\",\"modern\":\"河北昌黎\",\"lon\":119.16,\"lat\":39.71,\"period\":\"207 · 北征乌桓\",\"event\":\"白狼山破乌桓，凯旋经碣石，东临大海——日月之行，若出其中；星汉灿烂，若出其里。\",\"poems\":[25,26]},\n {\"place\":\"赤壁\",\"modern\":\"湖北赤壁\",\"lon\":113.63,\"lat\":29.88,\"period\":\"208 · 横槊赋诗\",\"event\":\"饮马长江，横槊赋诗，「对酒当歌，人生几何」；兵败赤壁，天下遂成三分。建安二十五年还军洛阳，病逝，遗令「天下尚未安定，未得遵古」葬毕即除服。\",\"poems\":[27]}\n]"}, {"id": 10, "name": "孟浩然", "zi": "", "hao": "孟山人", "dynasty": "唐", "years": "689—740", "title": "诗隐", "intro": "盛唐山水田园诗派第一人，襄阳人。一生布衣，终身不仕，却在隐与仕之间徘徊了一辈子。诗清淡自然，语淡味终不薄。", "story": "四十岁那年他赴长安应举，据说在王维处偶遇玄宗，诵到「不才明主弃」，玄宗不悦：「卿不求仕，而朕未尝弃卿，奈何诬我！」从此断了仕途。\n他回到襄阳的涧南园与鹿门山，把失意过成了千古风流。李白说「吾爱孟夫子，风流天下闻」，杜甫也说「清诗句句尽堪传」——终身白衣，却让满朝朱紫低头。", "storyTitle": "不才明主弃", "journey": "[\n {\"place\":\"襄阳 · 涧南园\",\"modern\":\"湖北襄阳\",\"lon\":112.12,\"lat\":32.01,\"period\":\"689—727 · 隐居\",\"event\":\"家世业儒，隐居鹿门山与涧南园，春眠闻鸟，把酒话桑麻，田园诗成于此。\",\"poems\":[29,30]},\n {\"place\":\"长安\",\"modern\":\"陕西西安\",\"lon\":108.94,\"lat\":34.27,\"period\":\"727—729 · 应举不第\",\"event\":\"四十岁赴京应进士举不第，据传太乐署诵诗误触玄宗，「不才明主弃」一句断了仕途。\",\"poems\":[]},\n {\"place\":\"建德江\",\"modern\":\"浙江建德\",\"lon\":119.28,\"lat\":29.60,\"period\":\"730—733 · 吴越漫游\",\"event\":\"自洛阳东游吴越，日暮移舟烟渚，客愁新起，对江清月近人。\",\"poems\":[31]},\n {\"place\":\"洞庭湖\",\"modern\":\"湖南岳阳\",\"lon\":113.09,\"lat\":29.36,\"period\":\"733 · 干谒\",\"event\":\"八月洞庭水涨，上诗张九龄冀见援引——气蒸云梦泽，波撼岳阳城；终无所遇。\",\"poems\":[32]},\n {\"place\":\"襄阳 · 归老\",\"modern\":\"湖北襄阳\",\"lon\":112.15,\"lat\":32.04,\"period\":\"733—740 · 归隐终老\",\"event\":\"背疽发作，王昌龄游襄阳来会，纵情宴谑以致疾发而逝。李白过襄阳，惟见「孟夫子」风流何处。\",\"poems\":[]}\n ]"}, {"id": 11, "name": "王昌龄", "zi": "少伯", "hao": "", "dynasty": "唐", "years": "698—757", "title": "七绝圣手", "intro": "盛唐边塞诗人，七言绝句与李白并称双璧。《出塞》被誉为唐人七绝压卷之作。仕途坎坷，两度被贬，终罹乱遇难。", "story": "他早年曾赴西北边塞，亲眼看过大漠孤城，所以笔下的关山月总有金石声。后人评他的七绝「深情幽怨，意旨微茫，尤入神品」。\n可诗名太盛，命却太薄：一贬岭南，再贬龙标，李白远在江南还为他写下「我寄愁心与明月」。安史乱起，他返乡途经亳州，竟被嫉妒才名的刺史闾丘晓杀害。后来张镐处决闾丘晓，晓求饶家有老母，张镐只答了一句：「王昌龄之亲，欲与谁养？」", "storyTitle": "一片冰心", "journey": "[\n {\"place\":\"长安\",\"modern\":\"陕西西安\",\"lon\":108.94,\"lat\":34.27,\"period\":\"698—724 · 早年\",\"event\":\"京兆长安人，早年躬耕灞上，曾西北出塞、东南漫游，诗名渐起。\",\"poems\":[]},\n {\"place\":\"凉州\",\"modern\":\"甘肃武威\",\"lon\":102.64,\"lat\":37.93,\"period\":\"约724—727 · 出塞\",\"event\":\"游河西边塞，亲历大漠孤城，秦时明月汉时关、黄沙百战穿金甲，皆此地所见。\",\"poems\":[33,35]},\n {\"place\":\"江宁\",\"modern\":\"江苏南京\",\"lon\":118.80,\"lat\":32.06,\"period\":\"约740—747 · 江宁丞\",\"event\":\"中进士后仕途蹉跌，出任江宁丞，人呼「王江宁」；江南采莲，闻歌始觉有人来。\",\"poems\":[36]},\n {\"place\":\"润州\",\"modern\":\"江苏镇江\",\"lon\":119.45,\"lat\":32.21,\"period\":\"747 · 芙蓉楼送别\",\"event\":\"自江宁赴润州，于芙蓉楼饯别辛渐：洛阳亲友如相问，一片冰心在玉壶。\",\"poems\":[34]},\n {\"place\":\"龙标\",\"modern\":\"湖南洪江\",\"lon\":110.09,\"lat\":27.21,\"period\":\"748—757 · 贬所\",\"event\":\"以「不护细行」再贬龙标尉，李白寄愁心与明月，随风直到夜郎西。安史乱起北还，途经亳州为闾丘晓所杀。\",\"poems\":[]}\n ]"}, {"id": 12, "name": "李商隐", "zi": "义山", "hao": "玉溪生", "dynasty": "唐", "years": "约813—858", "title": "诗坛情圣", "intro": "晚唐最缠绵也最晦涩的诗人，与杜牧并称「小李杜」。一生陷于牛李党争夹缝，沉沦下僚。诗深情绵邈，用典精工，《无题》诸篇写尽爱情的隐微曲折。", "story": "他的一生像他自己的诗：开成二年令狐绹延誉得中进士，次年却娶了「李党」王茂元之女，从此被「牛党」视作背恩之人，一生辗转于各处幕府，漂泊至死。\n妻子王氏早逝后，他在梓州幕府写下「此情可待成追忆」。四十五岁郁郁而终。后人爱他的诗，也叹他的命：把最深的深情，都藏进了无人能解的典故里。", "storyTitle": "锦瑟无端", "journey": "[\n {\"place\":\"怀州 · 河内\",\"modern\":\"河南沁阳\",\"lon\":113.27,\"lat\":35.09,\"period\":\"约813—833 · 幼年\",\"event\":\"生于怀州河内，十岁丧父，家境困厄，佣书贩舂以奉母。\",\"poems\":[]},\n {\"place\":\"长安\",\"modern\":\"陕西西安\",\"lon\":108.94,\"lat\":34.27,\"period\":\"837—846 · 进士与党争\",\"event\":\"令狐绹延誉得中进士，次年入泾原王茂元幕并娶其女，牛党目为背恩；夕阳无限好，只是近黄昏，登乐游原皆在此间。\",\"poems\":[39,40]},\n {\"place\":\"桂林\",\"modern\":\"广西桂林\",\"lon\":110.29,\"lat\":25.27,\"period\":\"847—848 · 桂管幕府\",\"event\":\"随郑亚赴桂管观察使幕，瘴江南去，乡思愈切。\",\"poems\":[]},\n {\"place\":\"梓州\",\"modern\":\"四川三台\",\"lon\":105.09,\"lat\":31.11,\"period\":\"851—855 · 东川幕府\",\"event\":\"妻王氏病逝，应柳仲郢之聘入东川幕府；巴山夜雨、锦瑟无端，晚岁深情皆成于此。\",\"poems\":[37,38]},\n {\"place\":\"荥阳\",\"modern\":\"河南荥阳\",\"lon\":113.44,\"lat\":34.79,\"period\":\"858 · 归葬\",\"event\":\"罢幕北归，郁郁而终，年约四十六，葬于荥阳祖茔。\",\"poems\":[]}\n ]"}, {"id": 13, "name": "杜牧", "zi": "牧之", "hao": "樊川居士", "dynasty": "唐", "years": "803—852", "title": "小杜", "intro": "晚唐诗人，宰相杜佑之孙。注《孙子兵法》而论兵，怀经世之志而不遇。诗俊爽峭健，七绝尤佳，与李商隐并称「小李杜」。", "story": "二十三岁写《阿房宫赋》名动京师，自诩知兵。他一生最大的舞台却是扬州：牛僧孺幕中掌书记，昼理公务、夜游歌楼，留下「十年一觉扬州梦，赢得青楼薄幸名」。\n他自己也知这只是逃避——「平生五色线，愿补舜衣裳」。牛李党争的夹缝里，那个想补天的贵公子，最终只留下一路清风明月的绝句，和《阿房宫赋》里「后人哀之而不鉴之」的千钧警语。", "storyTitle": "扬州一梦", "journey": "[\n {\"place\":\"长安\",\"modern\":\"陕西西安\",\"lon\":108.94,\"lat\":34.27,\"period\":\"803—828 · 京兆贵公子\",\"event\":\"宰相杜佑之孙，二十三岁作《阿房宫赋》名动天下，自注《孙子》而知兵。\",\"poems\":[]},\n {\"place\":\"洪州\",\"modern\":\"江西南昌\",\"lon\":115.89,\"lat\":28.68,\"period\":\"828—833 · 江西幕府\",\"event\":\"入江西观察使沈传师幕，少年幕僚，意气纵横。\",\"poems\":[]},\n {\"place\":\"扬州\",\"modern\":\"江苏扬州\",\"lon\":119.42,\"lat\":32.39,\"period\":\"833—835 · 淮南幕府\",\"event\":\"牛僧孺幕掌书记，昼理公务夜游歌楼；十年一觉扬州梦，赢得青楼薄幸名。夜泊秦淮，犹闻后庭遗曲。\",\"poems\":[43]},\n {\"place\":\"黄州\",\"modern\":\"湖北黄冈\",\"lon\":114.87,\"lat\":30.45,\"period\":\"842—844 · 黄州刺史\",\"event\":\"出为黄州刺史，江边磨洗折戟——东风不与周郎便，铜雀春深锁二乔。\",\"poems\":[44]},\n {\"place\":\"池州\",\"modern\":\"安徽池州\",\"lon\":107.49,\"lat\":30.66,\"period\":\"844—846 · 池州刺史\",\"event\":\"转守池州，秋山石径、清明杏花村，皆此时笔底风物。\",\"poems\":[41,42]},\n {\"place\":\"湖州\",\"modern\":\"浙江湖州\",\"lon\":120.09,\"lat\":30.87,\"period\":\"850 · 湖州刺史\",\"event\":\"求守湖州得偿夙愿；次年内召长安为中书舍人，寻病卒，年五十。\",\"poems\":[]}\n ]"}, {"id": 14, "name": "柳永", "zi": "耆卿", "hao": "白衣卿相", "dynasty": "宋", "years": "约984—约1053", "title": "慢词圣手", "intro": "北宋第一位专力写词的人，大力创作慢词，扩大了词的容量与题材。「凡有井水饮处，即能歌柳词」。仕途潦倒，一生流连坊曲，以毕生心血填词。", "story": "他考了四次进士都落第，一气写下「忍把浮名，换了浅斟低唱」。仁宗放榜时记得这句，朱笔一批：「且去浅斟低唱，何要浮名？」从此他自号「奉旨填词柳三变」，索性把功名换成了人间烟火。\n他给乐工歌妓写词，写市井的离别与相思，写到「凡有井水饮处，即能歌柳词」。晚年改名柳永才中了进士，做过小小屯田员外郎，卒于润州。据说死后家无余财，是歌妓们集资把他葬的——香花纸钱，年年清明，「吊柳七」。", "storyTitle": "奉旨填词", "journey": "[\n {\"place\":\"崇安\",\"modern\":\"福建武夷山\",\"lon\":118.03,\"lat\":27.76,\"period\":\"约984—1004 · 少年\",\"event\":\"生于崇安白袍巷，工词善音律，自号「奉旨填词柳三变」之前，先有白袍少年郎。\",\"poems\":[]},\n {\"place\":\"杭州\",\"modern\":\"浙江杭州\",\"lon\":120.16,\"lat\":30.25,\"period\":\"约1004—1005 · 干谒\",\"event\":\"谒两浙转运使孙何，一阕《望海潮》写尽钱塘繁华——三秋桂子，十里荷花，相传金主亮闻歌遂起投鞭渡江之志。\",\"poems\":[46]},\n {\"place\":\"汴京\",\"modern\":\"河南开封\",\"lon\":114.31,\"lat\":34.80,\"period\":\"1009—1034 · 屡试不第\",\"event\":\"四应进士皆黜落，仁宗批「且去浅斟低唱」；遂浪迹坊曲，为歌妓作词，执手相看泪眼，晓风残月柳七词。\",\"poems\":[45,47]},\n {\"place\":\"润州\",\"modern\":\"江苏镇江\",\"lon\":119.45,\"lat\":32.21,\"period\":\"1046—约1053 · 晚岁\",\"event\":\"晚年方进士及第，官至屯田员外郎，世称柳屯田；暮雨洒江天时倚阑凝愁，卒于润州，相传歌妓集资而葬。\",\"poems\":[48]}\n]"}, {"id": 15, "name": "欧阳修", "zi": "永叔", "hao": "醉翁、六一居士", "dynasty": "宋", "years": "1007—1072", "title": "一代文宗", "intro": "北宋诗文革新运动领袖，唐宋八大家之一。奖掖后进不遗余力，三苏、曾巩、王安石皆出其门。亦工词，深婉清丽。", "story": "四岁丧父，家贫，母亲郑氏以芦荻画地教字。他考进士时连中三元，却被评为「风采太过」抑为第二，从此一生锋芒不掩：庆历新政他仗义执言，被贬滁州，写下《醉翁亭记》——「醉翁之意不在酒」。\n他最大的功业却是识人：嘉祐二年他主持贡举，一榜取中苏轼、苏辙、曾巩、程颢、张载——千年科举最耀眼的一榜。他说「老夫当避路，放他出一头地」，说完，真的避路了。", "storyTitle": "醉翁之意", "journey": "[\n {\"place\":\"绵州\",\"modern\":\"四川绵阳\",\"lon\":104.75,\"lat\":31.47,\"period\":\"1007 · 生于任所\",\"event\":\"父任绵州推官，生于此；四岁丧父，随母归吉州，画荻教子。\",\"poems\":[]},\n {\"place\":\"洛阳\",\"modern\":\"河南洛阳\",\"lon\":112.45,\"lat\":34.62,\"period\":\"1031—1034 · 西京幕府\",\"event\":\"为西京留守推官，与梅尧臣、尹洙游，倡为古文，钱惟演幕中风流最盛。\",\"poems\":[]},\n {\"place\":\"汴京\",\"modern\":\"河南开封\",\"lon\":114.31,\"lat\":34.80,\"period\":\"1034—1036 · 馆阁谏垣\",\"event\":\"入馆阁、知谏院，直言极谏；元夕灯市，月上柳梢头。\",\"poems\":[49,51]},\n {\"place\":\"夷陵\",\"modern\":\"湖北宜昌\",\"lon\":111.29,\"lat\":30.69,\"period\":\"1036—1038 · 贬峡州\",\"event\":\"为范仲淹鸣不平，贬峡州夷陵县令；二月山城未见花，残雪压枝犹有橘。\",\"poems\":[52]},\n {\"place\":\"滁州\",\"modern\":\"安徽滁州\",\"lon\":118.32,\"lat\":32.30,\"period\":\"1045—1048 · 醉翁\",\"event\":\"庆历新政败，坐朋党贬滁州；醉翁之意不在酒，在乎山水之间也。\",\"poems\":[]},\n {\"place\":\"颍州\",\"modern\":\"安徽阜阳\",\"lon\":115.81,\"lat\":32.90,\"period\":\"1071—1072 · 归老\",\"event\":\"致仕居颍州西湖，轻舟短棹，绿水逶迤，惊起沙禽掠岸飞；同年卒，谥文忠。\",\"poems\":[50]}\n]"}, {"id": 16, "name": "王安石", "zi": "介甫", "hao": "半山", "dynasty": "宋", "years": "1021—1086", "title": "王荆公", "intro": "北宋政治家、文学家，「唐宋八大家」之一。主持熙宁变法，以「天变不足畏，祖宗不足法，人言不足恤」之勇气行新法。诗峭拔简劲，晚年起于炉火纯青。", "story": "他是那个时代最固执也最干净的人。做了两任宰相，罢相后退居江宁半山园，骑一头驴。政敌司马光评价：「人言安石奸邪，则毁之太过；但不晓事，又执拗耳。」\n变法失败千年，功罪聚讼不休，但他的私德连对手也无话可说：不好声色，不爱官职，不殖货利。失败了的是新法，不曾失败的是那句「天变不足畏，祖宗不足法，人言不足恤」——九百年后，仍掷地有声。", "storyTitle": "拗相公", "journey": "[\n {\"place\":\"临川\",\"modern\":\"江西抚州\",\"lon\":116.36,\"lat\":27.98,\"period\":\"1021—1039 · 少年\",\"event\":\"生于临川，随父宦游各地，过目不忘；曾巩称其文「善诵读，不为愚」。\",\"poems\":[]},\n {\"place\":\"鄞县\",\"modern\":\"浙江宁波\",\"lon\":121.56,\"lat\":29.87,\"period\":\"1047—1049 · 鄞县令\",\"event\":\"知鄞县，起堤堰、决陂塘、贷谷于民——青苗法之雏形已在小县试验。\",\"poems\":[]},\n {\"place\":\"杭州\",\"modern\":\"浙江杭州\",\"lon\":120.16,\"lat\":30.25,\"period\":\"1050 · 途经\",\"event\":\"自鄞返临川，道经越州登飞来峰：不畏浮云遮望眼，自缘身在最高层。\",\"poems\":[55]},\n {\"place\":\"汴京\",\"modern\":\"河南开封\",\"lon\":114.31,\"lat\":34.80,\"period\":\"1058—1076 · 变法\",\"event\":\"上仁宗万言书不报；神宗立，拜参知政事，行新法八年，两度拜相两度罢——爆竹声中一岁除，总把新桃换旧符。\",\"poems\":[56]},\n {\"place\":\"瓜洲\",\"modern\":\"江苏扬州邗江\",\"lon\":119.42,\"lat\":32.34,\"period\":\"1075 · 复相途中\",\"event\":\"再拜相自江宁赴汴，夜泊瓜洲：春风又绿江南岸，明月何时照我还。\",\"poems\":[53]},\n {\"place\":\"江宁\",\"modern\":\"江苏南京\",\"lon\":118.80,\"lat\":32.06,\"period\":\"1076—1086 · 半山园\",\"event\":\"罢相退居江宁，营半山园，骑驴游山，写「墙角数枝梅」；元祐元年卒，谥文，后追贬又追复舒王。\",\"poems\":[54]}\n ]"}, {"id": 17, "name": "陆游", "zi": "务观", "hao": "放翁", "dynasty": "宋", "years": "1125—1210", "title": "亘古男儿", "intro": "南宋爱国诗人，存诗九千三百余首，为存诗最多的诗人。一生志在恢复中原，临终犹作《示儿》。诗雄浑豪放与清新圆润兼擅。", "story": "他与唐琬的沈园之遇是南宋最痛的爱情：一阕《钗头凤》题壁，「错、错、错」，从此「伤心桥下春波绿，曾是惊鸿照影来」。\n他的主线却是北伐：四十八岁从军南郑，铁衣上渡渭水，「铁马秋风大散关」是他一生最亮的八个月。此后六十年，从「胡未灭，鬓先秋」写到临终的《示儿》——死去之前，他还惦记着让儿子家祭时别忘了告诉他王师收复中原的消息。梁启超叹：「亘古男儿一放翁。」", "storyTitle": "铁马冰河", "journey": "[\n {\"place\":\"山阴\",\"modern\":\"浙江绍兴\",\"lon\":120.58,\"lat\":30.01,\"period\":\"1125—1163 · 家乡与沈园\",\"event\":\"生于淮上舟中，靖康之乱随家南归山阴；二十岁与唐琬结褵，被迫离异，沈园重逢题《钗头凤》于壁。\",\"poems\":[60]},\n {\"place\":\"临安\",\"modern\":\"浙江杭州\",\"lon\":120.16,\"lat\":30.25,\"period\":\"1153—1154 · 锁厅试\",\"event\":\"赴临安应锁厅试，取为第一，因名列秦桧孙前而遭黜落，遂归里力学。\",\"poems\":[]},\n {\"place\":\"镇江\",\"modern\":\"江苏镇江\",\"lon\":119.42,\"lat\":32.20,\"period\":\"1163—1164 · 通判\",\"event\":\"任镇江通判，力赞张浚北伐，亲至前线观兵；隆兴和议成，壮志暂挫。\",\"poems\":[]},\n {\"place\":\"南郑\",\"modern\":\"陕西汉中\",\"lon\":107.03,\"lat\":33.07,\"period\":\"1172 · 从军南郑\",\"event\":\"入王炎幕府赞理军务，铁衣白马戍大散关，射虎、雪夜欢宴——一生最亮的八个月；幕府撤，泪洒南郑。\",\"poems\":[]},\n {\"place\":\"成都\",\"modern\":\"四川成都\",\"lon\":104.07,\"lat\":30.67,\"period\":\"1173—1178 · 蜀中八年\",\"event\":\"历蜀州、嘉州、成都诸职，参范成大幕，以「放翁」自号，花时遍游锦城。\",\"poems\":[]},\n {\"place\":\"山阴 · 三山\",\"modern\":\"浙江绍兴\",\"lon\":120.62,\"lat\":30.05,\"period\":\"1179—1210 · 老家\",\"event\":\"归隐三山，游山西村、卧听风雨，梦回铁马冰河；八十五岁临终作《示儿》，不忘告乃翁。\",\"poems\":[57,58,59]}\n]"}, {"id": 18, "name": "诗经", "zi": "", "hao": "", "dynasty": "先秦", "years": "西周—春秋", "title": "诗三百", "intro": "我国第一部诗歌总集，收西周至春秋诗歌三百零五篇，分风、雅、颂三部分。「饥者歌其食，劳者歌其事」，是中国诗歌的源头。", "story": "孔子说：「诗三百，一言以蔽之，曰思无邪。」两千年里，它既是经书，也是歌本——恋爱要引「窈窕淑女」，思乡要引「杨柳依依」。\n「风」是各地的歌谣，「雅」是庙堂的正声，「颂」是祭祀的乐章。赋、比、兴三种手法，从这里出发，长成了整部中国诗史。", "storyTitle": "风雅颂", "journey": ""}, {"id": 19, "name": "屈原", "zi": "平", "hao": "", "dynasty": "先秦", "years": "约前340—前278", "title": "楚辞之祖", "intro": "楚国贵族，中国第一位留下姓名的伟大诗人。开创「楚辞」一体，《离骚》《九歌》《天问》皆为绝唱。忧国投江，端午由是而来。", "story": "他「博闻强志，明于治乱，娴于辞令」，本可安享相位，却因主张联齐抗秦被谗放逐，眼睁睁看着祖国一步步走向沦亡。\n前278年，秦将白起破郢都。流放湘沅的屈原于五月五日抱石投汨罗江。他留下的不只是《离骚》，还有一个词——「路漫漫其修远兮，吾将上下而求索」。", "storyTitle": "屈子行吟", "journey": "[\n {\"place\":\"郢都\",\"modern\":\"湖北荆州\",\"lon\":112.19,\"lat\":30.33,\"period\":\"约前353—前317 · 左徒\",\"event\":\"出身楚之同姓贵族，博闻强志，明于治乱；入则与王图议国事，出则接遇宾客。\",\"poems\":[]},\n {\"place\":\"汉北\",\"modern\":\"湖北襄阳北\",\"lon\":112.12,\"lat\":32.01,\"period\":\"约前317—前301 · 见疏\",\"event\":\"上官大夫谗之，王怒而疏屈平；退居汉北，忧愁幽思而作《离骚》。\",\"poems\":[]},\n {\"place\":\"沅湘\",\"modern\":\"湖南常德\",\"lon\":111.69,\"lat\":29.03,\"period\":\"前296—前278 · 流放\",\"event\":\"顷襄王听谗，迁之江南；渡湘水，入沅澧，仿民间祭歌作《九歌》——国殇祭楚阵亡将士，悲壮千古。\",\"poems\":[64]},\n {\"place\":\"汨罗江\",\"modern\":\"湖南汨罗\",\"lon\":113.08,\"lat\":28.81,\"period\":\"前278 · 怀石自沉\",\"event\":\"闻秦将白起破郢，长叹「举世皆浊我独清」；五月五日怀石自沉汨罗，楚人哀之，岁岁竞渡以吊。\",\"poems\":[]}\n ]"}, {"id": 20, "name": "刘邦", "zi": "季", "hao": "", "dynasty": "两汉", "years": "前256—前195", "title": "汉高祖", "intro": "汉朝开国皇帝。出身布衣，提三尺剑定天下。不以文称，而《大风歌》三句，雄视千古。", "story": "前196年，他平定英布叛乱后回师故乡沛县，置酒沛宫，悉召父老子弟纵酒。酒酣，击筑而歌，慷慨伤怀，起舞，泣数行下。\n三句歌，一百三十四年的帝国由此开篇：「安得猛士兮守四方」——打天下的人，唱的却是守天下的忧虑。", "storyTitle": "大风起兮", "journey": ""}, {"id": 21, "name": "项羽", "zi": "", "hao": "西楚霸王", "dynasty": "秦末", "years": "前232—前202", "title": "拔山盖世", "intro": "楚国名将项燕之孙，巨鹿之战破釜沉舟，灭秦主力。与刘邦争天下，垓下兵败，自刎乌江。", "story": "垓下被围，夜闻四面楚歌，他知道大势已去。帐中饮酒，对美人虞姬、坐骑骓马慷慨悲歌，歌数阕，美人和之。项王泣数行下。\n他二十四岁起兵，三年亡秦，三十一岁自刎——不肯过江东。李清照后来写：「至今思项羽，不肯过江东。」", "storyTitle": "霸王别姬", "journey": ""}, {"id": 22, "name": "汉乐府", "zi": "", "hao": "", "dynasty": "两汉", "years": "两汉", "title": "感于哀乐", "intro": "汉代管理音乐的官署，后成为诗体名。乐府诗「感于哀乐，缘事而发」，多采自民间，是继诗经、楚辞之后的又一座高峰。", "story": "汉武帝设立乐府，派人到各地采诗配乐——相当于国家民谣采集计划。百姓的婚丧嫁娶、征战离乱，都进了这些歌。\n乐府多「感于哀乐，缘事而发」：不雕琢，不摆架子，开口就是活生生的人生。五言诗体在这里成熟，此后的建安风骨、唐诗都吃它的奶。", "storyTitle": "采诗入乐", "journey": ""}, {"id": 23, "name": "古诗十九首", "zi": "", "hao": "", "dynasty": "两汉", "years": "东汉", "title": "五言之冠冕", "intro": "东汉末年十九首无名氏五言诗，南朝萧统收入《文选》并题此名。刘勰誉为「五言之冠冕」，钟嵘称「惊心动魄，可谓几乎一字千金」。", "story": "作者失传，诗却写尽了人类共同的心事：游子、思妇、生离、死别、人生短促、及时行愿。\n「生年不满百，常怀千岁忧」——没有英雄气，只有真气。钟嵘说它「一字千金」：因为每个字后面都站着一个人。", "storyTitle": "一字千金", "journey": ""}, {"id": 24, "name": "曹植", "zi": "子建", "hao": "陈思王", "dynasty": "魏晋", "years": "192—232", "title": "才高八斗", "intro": "曹操之子，建安文学代表人物。谢灵运言：「天下才有一石，曹子建独占八斗。」", "story": "他是曹操最疼的儿子，十岁余便能诵读诗论辞赋数十万言，铜雀台上援笔立成。也曾意气风发，想「戮力上国，流惠下民」。\n曹丕称帝后，这位曾经的竞争对手之弟，一路被贬徙监视，「汲汲无欢」。传说七步成诗保全性命——煮豆燃萁的兄弟，成了权力绞杀亲情的千古标本。四十一岁郁郁而终。", "storyTitle": "七步成诗", "journey": ""}, {"id": 25, "name": "北朝民歌", "zi": "", "hao": "", "dynasty": "南北朝", "years": "南北朝", "title": "慷慨悲歌", "intro": "北朝时期北方各民族的民间歌谣，现存约六十余首。语言质朴刚健，与南朝民歌的婉媚恰成对照。《木兰诗》为其冠冕。", "story": "五胡乱华后的北方，马背民族的歌谣粗粝而滚烫：写战争的残酷，也写女英雄的传奇。\n《木兰诗》与《孔雀东南飞》合称「乐府双璧」——一个替父从军，一个殉情赴死，中国叙事诗的两座巅峰。", "storyTitle": "乐府双璧", "journey": ""}, {"id": 26, "name": "王之涣", "zi": "", "hao": "", "dynasty": "唐", "years": "688—742", "title": "旗亭画壁", "intro": "盛唐边塞诗人，性豪侠，常击剑悲歌。存诗仅六首，却有两首千古绝唱。", "story": "关于他最动人的记载是「旗亭画壁」：与王昌龄、高适雪天聚于酒楼，遇梨园伶人唱曲，三人私下约定以被唱诗多寡定诗名高下。伶人连唱数首皆非己作，最美的压轴双鬟却开口便是「黄河远上白云间」。\n存诗六首，首首可传。《登鹳雀楼》二十字，写尽盛唐的上升气象。", "storyTitle": "旗亭画壁", "journey": ""}, {"id": 27, "name": "贺知章", "zi": "季真", "hao": "四明狂客、秘书外监", "dynasty": "唐", "years": "约659—约744", "title": "诗狂", "intro": "唐代诗人、书法家，性旷达，自号「四明狂客」。与李白忘年交，称其「谪仙人」。", "story": "他是盛唐诗坛的老前辈：三十六岁进士及第，在长安官场混了五十年，八十六岁告老还乡。喝酒、纵诞、不拘礼法，杜甫把他列进「饮中八仙」——「知章骑马似乘船，眼花落井水底眠」。\n最传奇的是初见李白，读罢《蜀道难》惊呼「谪仙人」，当场解下金龟换酒共醉。回乡后写下「儿童相见不相识」，一年后安然离世。", "storyTitle": "金龟换酒", "journey": ""}, {"id": 28, "name": "张九龄", "zi": "子寿", "hao": "曲江", "dynasty": "唐", "years": "678—740", "title": "曲江风度", "intro": "开元盛世最后一位名相，岭南第一人。文学为一代宗师，张说称其后出词人之冠。", "story": "他出自岭南寒门，一路官至宰相，以雅直闻名。开元后期预见安禄山必反，请杀之，玄宗不听。\n罢相后写《望月怀远》，「海上生明月，天涯共此时」——宰相的手笔，连相思都写得这样堂堂正正。玄宗后来看人必问：「风度得如九龄否？」", "storyTitle": "曲江风度", "journey": ""}, {"id": 29, "name": "张继", "zi": "懿孙", "hao": "", "dynasty": "唐", "years": "约715—约779", "title": "枫桥钟声", "intro": "唐代诗人，天宝进士。一首《枫桥夜泊》传诵千古，寒山寺因之名扬海外。", "story": "安史之乱，他避乱南下，泊舟苏州城外。那一夜：月落、乌啼、霜满天，江枫、渔火、不眠人。\n二十八个字，写尽一个乱世流离者的失眠。钟声响起，他成了寒山寺永远的代言人——一生功业平淡，只靠一夜成名，且名了一千二百年。", "storyTitle": "夜半钟声", "journey": ""}, {"id": 30, "name": "张志和", "zi": "子同", "hao": "烟波钓徒、玄真子", "dynasty": "唐", "years": "约730—约810", "title": "烟波钓徒", "intro": "唐代诗人。十六岁明经及第，献策深受肃宗赏识，后因事贬官，从此绝意仕途，隐居江湖，自称「烟波钓徒」。", "story": "他本是神童出身，官运也不错，一场贬谪却让他彻底转身：不做官了，泛舟江湖，以渔隐终老。\n颜真卿任湖州刺史时，他与陆羽等饮酒唱和，《渔歌子》就写于此时。后来这幅词意画传到日本，嵯峨天皇读了都要模仿作和歌——一叶扁舟，载动了东亚的审美。", "storyTitle": "烟波钓徒", "journey": ""}, {"id": 31, "name": "高适", "zi": "达夫", "hao": "渤海县侯", "dynasty": "唐", "years": "704—765", "title": "诗人之达者", "intro": "盛唐边塞诗派领袖，与岑参并称「高岑」。《旧唐书》称：「有唐已来，诗人之达者，唯适而已。」", "story": "他半生潦倒，五十岁前一度在梁宋一带「渔樵孟诸野」，靠人接济为生。谁也没想到，这个落魄中年人后来封侯拜将，成为唐代诗人功业之最。\n天宝十一载冬，他在睢阳送别琴师董庭兰，大雪纷飞里写下「莫愁前路无知己」——自己尚且穷愁，却把豪迈赠予朋友。安史乱后，他讨永王、救睢阳，剑与笔都没落下。", "storyTitle": "诗人之达者", "journey": ""}, {"id": 32, "name": "岑参", "zi": "", "hao": "岑嘉州", "dynasty": "唐", "years": "约715—770", "title": "岑嘉州", "intro": "盛唐边塞诗人，两度出塞，居幕六年。诗想象奇伟，写尽西域风雪，「忽如一夜春风来」为咏雪千古第一句。", "story": "他家世显赫而家道中落，三十岁中进士，此后两度远赴安西、北庭从军。别人写边塞靠想象，他是在天山、轮台真刀真雪里活的。\n他写雪像梨花，写火云满山凝未开，写「走马西来欲到天」——盛唐的胃口，装得下万里西陲。晚年嘉州刺史任满罢归，客死成都旅舍。", "storyTitle": "千年第一雪", "journey": ""}, {"id": 33, "name": "孟郊", "zi": "东野", "hao": "", "dynasty": "唐", "years": "751—814", "title": "诗囚", "intro": "中唐诗人，与贾岛并称「郊寒岛瘦」，元好问称其为「诗囚」。四十六岁进士及第，一生穷困，诗风瘦硬苦吟。", "story": "他考了两次进士都落第，四十六岁才中，狂喜写下「春风得意马蹄疾，一日看尽长安花」。此后做过小小的溧阳尉，终老贫寒。\n五十岁那年把母亲接来同住，回想一生漂泊、母亲缝衣的灯下，写下《游子吟》——三十个字，成了天下母亲共同的碑文。苏轼评：「诗从肺腑出，出辄愁肺腑。」", "storyTitle": "寸草春晖", "journey": ""}, {"id": 34, "name": "韩愈", "zi": "退之", "hao": "昌黎先生", "dynasty": "唐", "years": "768—824", "title": "百代文宗", "intro": "唐代文学家、思想家，古文运动领袖，唐宋八大家之首。苏轼赞：「文起八代之衰，道济天下之溺。」", "story": "他三岁而孤，由兄嫂抚养，四次应考方中进士，三次吏部博学宏词皆不中——求学之路比谁都坎坷。\n他敢谏迎佛骨，差点被处死，贬潮州八千里，「雪拥蓝关马不前」。在潮州八月，驱鳄兴学，山水为之改姓。他领导古文运动，把骈俪的文体扳回到「文以载道」的正路上，此后一千年文章的格局由他奠定。", "storyTitle": "文起八代", "journey": ""}, {"id": 35, "name": "贾岛", "zi": "浪仙", "hao": "碣石山人", "dynasty": "唐", "years": "779—843", "title": "诗奴", "intro": "中唐诗人，早年为僧，法号无本。以苦吟著称，「两句三年得，一吟双泪流」。与孟郊并称「郊寒岛瘦」。", "story": "他做过和尚，还俗应举屡败。骑驴闯过韩愈仪仗——正在驴上斟酌「僧敲月下门」用「推」还是「敲」，冲撞了京兆尹车驾，韩愈反而与他共论诗法，「推敲」一词由此而来。\n他自述「两句三年得，一吟双泪流」，把写诗当成修行。这种把命押在字上的痴劲，为他赢得一个称号：诗奴——诗的奴隶，也是诗的圣徒。", "storyTitle": "推敲", "journey": ""}, {"id": 36, "name": "韦应物", "zi": "", "hao": "韦苏州", "dynasty": "唐", "years": "约737—约791", "title": "韦苏州", "intro": "中唐山水田园诗人，早年任玄宗侍卫，豪横不羁；安史乱后发奋读书，终成大家。历任滁州、江州、苏州刺史，世称「韦苏州」。", "story": "他十五岁做玄宗贴身侍卫，少年横行乡里，自己说「少事武皇帝，无赖恃恩私。身作里中横，家藏亡命儿」。\n安史之乱打断一切，他折节读书，从恶少变成清雅诗人。滁州西涧一首，无人之境写出了中国诗最恬淡的一角。晚年罢苏州刺史，贫不能归，寄居苏州永定寺。", "storyTitle": "浪子诗人", "journey": ""}, {"id": 37, "name": "刘禹锡", "zi": "梦得", "hao": "", "dynasty": "唐", "years": "772—842", "title": "诗豪", "intro": "中唐诗人、哲学家，与柳宗元并称「刘柳」，与白居易并称「刘白」。白居易称其为「诗豪」。二十三年贬谪生涯，愈挫愈昂。", "story": "他因参与永贞革新被贬，一贬二十三年。别人贬谪写哀怨，他写「晴空一鹤排云上」；回到长安题诗讽贵，再贬；再回，再题——「前度刘郎今又来」，骨头硬了一辈子。\n白居易为他抱不平「亦知合被才名折」，他答以「沉舟侧畔千帆过，病树前头万木春」。哲人的达观与诗人的倔强在他身上合一，人称「诗豪」，当之无愧。", "storyTitle": "前度刘郎", "journey": ""}, {"id": 38, "name": "元稹", "zi": "微之", "hao": "", "dynasty": "唐", "years": "779—831", "title": "元才子", "intro": "中唐诗人，与白居易共同倡导新乐府运动，世称「元白」。诗浅切动人，宫中呼为「元才子」。", "story": "他与白居易的友谊是文学史上的传奇：唱和千首，「生死契阔者三十年」。他贬江陵、通州，白居易贬江州、忠州，两人诗筒传讯，道路相传。\n「曾经沧海难为水」传为悼亡妻韦丛之作——韦丛二十岁下嫁落魄的他，七年而逝。此后他仕途显达，官至宰相，然对发妻的这一句，千年无人超越。", "storyTitle": "曾经沧海", "journey": ""}, {"id": 39, "name": "崔护", "zi": "", "hao": "", "dynasty": "唐", "years": "772—831", "title": "桃花诗人", "intro": "唐代诗人，官至岭南节度使。存诗六首，《题都城南庄》一首即成经典。", "story": "他清明独游长安城南，口渴叩门求饮，遇一女子倚桃而立，眉目盈盈。次年清明再访，门墙如故，人已不在，遂题诗于扉：「人面不知何处去，桃花依旧笑春风。」\n一段无疾而终的邂逅，成就了一个成语「人面桃花」。据说那女子读诗后绝食而复产团圆——那是传奇小说的续写；诗本身说的，是每个人都错过的那一次。", "storyTitle": "人面桃花", "journey": ""}, {"id": 40, "name": "李绅", "zi": "公垂", "hao": "", "dynasty": "唐", "years": "772—846", "title": "悯农诗人", "intro": "中唐诗人，新乐府运动参与者，与元白交好。官至宰相，然晚年豪奢，为史家所讥。", "story": "他二十七岁中进士，青年时目睹农人烈日下劳作，写下《悯农》二首——「四海无闲田，农夫犹饿死」的批判力，在唐诗中罕见。\n后世更愿记住写诗的那个李绅，而不是做宰相的那个李绅：晚年他一餐耗费数百金，刘禹锡「司空见惯浑闲事」的典故正出其家宴。人性复杂如此，诗却始终替他干净着。", "storyTitle": "盘中餐", "journey": ""}, {"id": 41, "name": "王翰", "zi": "子羽", "hao": "", "dynasty": "唐", "years": "687—726", "title": "边塞豪士", "intro": "盛唐边塞诗人，出身豪族，恃才不羁。《凉州词》被王世贞推为唐人七绝压卷之作。", "story": "他家资豪富，家蓄歌妓，纵酒游猎如少年李白。枥多名马，家有伎乐，发言立意，自比王侯。\n一把好牌被他打成贬官：日以蒲酒牛从未人，遭人弹劾，一路贬到道州司马，死于途中。留下的《凉州词》却是不朽——把沙场的悲凉写成了盛宴，「古来征战几人回」是玩笑，也是实话。", "storyTitle": "葡萄美酒", "journey": ""}, {"id": 42, "name": "李煜", "zi": "重光", "hao": "钟隐、莲峰居士", "dynasty": "五代", "years": "937—978", "title": "千古词帝", "intro": "南唐末代国君，精书画音律，工词。亡国后词风一变，血泪之作「眼界始大，感慨遂深」，被誉为「千古词帝」。", "story": "他生来是艺术家的料，却做了亡国之君：即位时南唐已是宋朝的属国，他称臣纳贡、笃信佛法，把苟安当岁月静好。\n975年金陵城破，他肉袒出降，北上汴京，封「违命侯」。从皇帝到囚徒，词从宫廷艳曲变成血泪绝唱。978年七夕，他的生日，因「故国不堪回首」之句触怒宋太宗，被赐牵机药毒死——那一天正是他四十二岁生日。", "storyTitle": "违命侯", "journey": "[\n {\"place\":\"金陵\",\"modern\":\"江苏南京\",\"lon\":118.80,\"lat\":32.06,\"period\":\"937—975 · 江南国主\",\"event\":\"二十五岁继位为南唐国主，称臣于宋，笃信佛法，宫殿设道场；词多宫廷宴乐，画堂烟雨。\",\"poems\":[]},\n {\"place\":\"汴京\",\"modern\":\"河南开封\",\"lon\":114.31,\"lat\":34.80,\"period\":\"975—978 · 违命侯\",\"event\":\"金陵城破肉袒出降，封违命侯；从国主到囚徒，词风一变而为血泪——帘外雨潺潺，梦里不知身是客。978年七夕生日，以牵机药赐死。\",\"poems\":[95,96,97]}\n]"}, {"id": 43, "name": "范仲淹", "zi": "希文", "hao": "", "dynasty": "宋", "years": "989—1052", "title": "先忧后乐", "intro": "北宋政治家、文学家。戍边御西夏，主持庆历新政。一句「先天下之忧而忧」，成为中国士大夫的精神坐标。", "story": "他两岁丧父，随母改嫁，寄人篱下，读书划粥断齑。为官敢言，三次被贬，梅尧臣作文劝他少说话，他回以「宁鸣而死，不默而生」。\n戍守西北时西夏不敢犯境，民歌「军中有一范，西贼闻之惊破胆」。写《岳阳楼记》时他并未到过岳阳——滕子京求文，他把一生信念放了进去。", "storyTitle": "先忧后乐", "journey": ""}, {"id": 44, "name": "晏殊", "zi": "同叔", "hao": "", "dynasty": "宋", "years": "991—1055", "title": "太平宰相", "intro": "北宋词人、政治家。五岁能文，十四岁以神童召试赐进士。词风闲雅清婉，开创北宋婉约词风，提携范仲淹、欧阳修、晏几道等。", "story": "他是神童出身的太平宰相：殿试时看到试题说自己十日前做过，请换题——真宗爱其诚实，御笔亲擢。\n一生富贵优游，却写「无可奈何花落去」这种带着淡淡惆怅的句子——太平里的时间焦虑，比贫困里的更真实。他当宰相最大的政绩是办学与识人：范仲淹、韩琦、富弼、欧阳修皆出其门。", "storyTitle": "无可奈何", "journey": ""}, {"id": 45, "name": "晏几道", "zi": "叔原", "hao": "小山", "dynasty": "宋", "years": "1038—1110", "title": "古之伤心人", "intro": "晏殊第七子，世称「小晏」。词风深婉真挚，冯煦评为「古之伤心人」。不借父荫攀附，一生任小官。", "story": "父亲是宰相，他却在父亲死后家道中落，又不肯依傍权贵——苏轼想通过黄庭坚见他，他答：「今日政事堂中半吾家旧客，亦未暇见也。」\n他只写自己：歌女、酒、梦和回忆。「落花人独立，微雨燕双飞」十个字，写尽孤独的形状。贫到搬家都靠朋友接济，词却字字千金。", "storyTitle": "落花人独立", "journey": ""}, {"id": 46, "name": "秦观", "zi": "少游", "hao": "淮海居士", "dynasty": "宋", "years": "1049—1100", "title": "山抹微云君", "intro": "北宋词人，「苏门四学士」之一，婉约派一代词宗。词情韵兼胜，被尊为「婉约之宗」。", "story": "他考进士两次落第，直到三十七岁才中。因师从苏轼，新旧党争里两头受气，一贬再贬，从杭州到郴州到横州雷州，越贬越远。\n苏轼戏称他「山抹微云君」，此词一出，天下传唱。他死于北归途中，苏轼闻之，两日食不下咽。「两情若是久长时」——写尽离别的他，自己的重逢却永远没有等到。", "storyTitle": "山抹微云", "journey": ""}, {"id": 47, "name": "李之仪", "zi": "端叔", "hao": "姑溪居士", "dynasty": "宋", "years": "1048—1117", "title": "姑溪居士", "intro": "北宋词人，苏轼门下幕僚。词以小令见长，《卜算子》一首家喻户晓。", "story": "他是苏轼幕中旧人，因受牵连被贬太平州。妻子胡淑修贤而知书，随他共历贬谪。\n晚年谪居太平州姑溪，写下「我住长江头，君住长江尾」——用一条江写尽异地相思，语言竟像民歌一样干净。后人常拿它与汉乐府《上邪》对读：一个发毒誓，一个喝江水，都是爱到不讲道理。", "storyTitle": "共饮长江", "journey": ""}, {"id": 48, "name": "朱熹", "zi": "元晦", "hao": "晦庵、晦翁", "dynasty": "宋", "years": "1130—1200", "title": "理学宗师", "intro": "南宋理学家、教育家，程朱理学集大成者。一生讲学不辍，注《四书》，其学此后七百年为科举正宗。", "story": "他是孔子之后中国最有影响力的学者：十九岁中进士，一生大部分时间在讲学与著述。《四书章句集注》成为元明清三代读书人的标准教科书。\n他诗写得好却不以诗名——「问渠那得清如许」，把读书的道理写成了池塘活水。晚年「庆元党禁」中学说被斥为伪学，门人流散，他仍日日讲学不休。死后九年，朝廷为他平反，配享孔庙。", "storyTitle": "源头活水", "journey": ""}, {"id": 49, "name": "杨万里", "zi": "廷秀", "hao": "诚斋", "dynasty": "宋", "years": "1127—1206", "title": "诚斋", "intro": "南宋诗人，与陆游、尤袤、范成大并称「南宋四大家」。自创活泼清新、幽默谐趣的「诚斋体」，存诗四千二百余首。", "story": "他为官清廉，退休时「诗卷钞留千首在，囊金只有一钱余」。晚年因痛骂权臣韩侂胄，家居十五年不出仕，韩要拉拢他，他说「官可弃，记不可作也」。\n他的诗眼是活的：泉眼会「惜」细流，小荷才露尖尖角，蜻蜓已立上头——万物在他笔下都有性灵，人称「诚斋体」，活法二字是他自己的诗学纲领。", "storyTitle": "诚斋活法", "journey": ""}, {"id": 50, "name": "叶绍翁", "zi": "", "hao": "靖逸", "dynasty": "宋", "years": "南宋", "title": "江湖诗人", "intro": "南宋中期诗人，属江湖诗派。长于七绝，《游园不值》一首脍炙人口。", "story": "他生平记载极少，只知姓叶名绍翁，字嗣宗，号靖逸，做过小小的朝官，隐居钱塘西湖之滨。\n一次访友不遇，本该是扫兴事，他却在柴门外站住了——一枝红杏出墙来。乘兴而来，扫兴而归，却带回了中国诗歌里最蓬勃的一枝春色。", "storyTitle": "一枝红杏", "journey": ""}, {"id": 51, "name": "赵师秀", "zi": "紫芝", "hao": "灵秀、天乐", "dynasty": "宋", "years": "1170—1219", "title": "永嘉四灵", "intro": "南宋诗人，「永嘉四灵」之冠。作诗以清苦为工，最擅五律。", "story": "他与徐照、徐玑、翁卷并称「永嘉四灵」，四人字号都带「灵」字，诗风也如出一辙：收拾唐人晚年的清瘦笔意，写小景小心思。\n「有约不来过夜半，闲敲棋子落灯花」——约的人没来，他把自己的无聊写成了千古名画。等待的焦灼被一枚棋子化解，宋人的克制与风雅，全在这一敲里。", "storyTitle": "闲敲棋子", "journey": ""}, {"id": 52, "name": "林升", "zi": "", "hao": "梦屏", "dynasty": "宋", "years": "南宋", "title": "题壁诗人", "intro": "南宋诗人，生平不详，《题临安邸》是其题写在临安一家旅舍墙壁上的诗。", "story": "历史几乎没有留下他的信息，只留下那一面墙。\n南宋偏安临安，权贵醉生梦死。他在旅舍壁上愤然题下「暖风熏得游人醉，直把杭州作汴州」——一面旅舍的白墙，从此成了钉在历史上的耻辱柱。题壁无名，胜过多少署名。", "storyTitle": "直把杭州作汴州", "journey": ""}, {"id": 53, "name": "岳飞", "zi": "鹏举", "hao": "", "dynasty": "宋", "years": "1103—1142", "title": "精忠报国", "intro": "南宋抗金名将、军事家，缔造岳家军，「冻死不拆屋，饿死不掳掠」。被秦桧以「莫须有」罪名冤杀，后追谥武穆、封鄂王。", "story": "他背上刺有「尽忠报国」四字，一生北伐，郾城大捷破金军铁浮屠，兵锋直指朱仙镇，距故都汴京只有四十五里。\n一天之内连收十二道金字牌班师诏——「十年之力，废于一旦」。1142年除夕前夜，以「莫须有」的罪名被害于大理寺风波亭，年仅三十九。狱案卷宗上，他写下八个字：「天日昭昭，天日昭昭。」", "storyTitle": "精忠报国", "journey": "[\n {\"place\":\"汤阴\",\"modern\":\"河南汤阴\",\"lon\":114.35,\"lat\":35.92,\"period\":\"1103—1122 · 少年\",\"event\":\"农家出身，师从周同学射，天生神力，不满二十岁能挽弓三百斤；背上刺「尽忠报国」四字。\",\"poems\":[]},\n {\"place\":\"临安\",\"modern\":\"浙江杭州\",\"lon\":120.16,\"lat\":30.25,\"period\":\"1131—1139 · 行在\",\"event\":\"南宋定都临安，岳飞屡次上书北伐；高宗手书「精忠岳飞」制旗赐之，官至枢密副使。\",\"poems\":[110]},\n {\"place\":\"郾城\",\"modern\":\"河南漯河\",\"lon\":114.01,\"lat\":33.59,\"period\":\"1140 · 北伐大捷\",\"event\":\"郾城之战大破金军铁浮屠、拐子马，进军朱仙镇，距汴京四十五里——直捣黄龙，与诸君痛饮耳！\",\"poems\":[]},\n {\"place\":\"风波亭\",\"modern\":\"浙江杭州\",\"lon\":120.17,\"lat\":30.26,\"period\":\"1141—1142 · 冤狱\",\"event\":\"一日十二道金字牌班师；入狱，以「莫须有」三字赐死于大理寺风波亭，年仅三十九。狱中书：天日昭昭，天日昭昭。\",\"poems\":[]}\n ]"}, {"id": 54, "name": "文天祥", "zi": "宋瑞", "hao": "文山", "dynasty": "宋", "years": "1236—1283", "title": "状元宰相", "intro": "南宋末政治家、诗人，二十岁中状元。元军南下，毁家纾难勤王；兵败被俘，囚大都三年，从容就义。", "story": "元军压境，他散尽家财招募义军勤王，朋友劝他「是何异于驱群羊而搏猛虎」，他答：「但求一死，以愧天下之不忠者。」\n出使元营被扣，镇江脱险，再度领兵，兵败五坡岭被俘。元廷囚他三年，许以宰相之位劝降，连宋恭帝都被搬出来，他只回「天祥受宋恩，为宰相，安事二姓」。1283年从容就义，衣带中留绝笔：「孔曰成仁，孟曰取义，惟其义尽，所以仁至。」", "storyTitle": "留取丹心", "journey": "[\n {\"place\":\"庐陵\",\"modern\":\"江西吉安\",\"lon\":114.98,\"lat\":27.11,\"period\":\"1236—1256 · 少年\",\"event\":\"生于庐陵富田村，见学宫欧阳修、杨邦乂画像，誓曰「没不俎豆其间，非夫也」；二十岁中状元。\",\"poems\":[]},\n {\"place\":\"临安\",\"modern\":\"浙江杭州\",\"lon\":120.16,\"lat\":30.25,\"period\":\"1256—1275 · 宦海\",\"event\":\"状元及第，因丧父归乡三年；直言忤权臣董宋臣、贾似道，数度被斥罢。\",\"poems\":[]},\n {\"place\":\"镇江\",\"modern\":\"江苏镇江\",\"lon\":119.42,\"lat\":32.20,\"period\":\"1276 · 脱险\",\"event\":\"以右丞相入元营谈判，面斥伯颜被扣；镇江夜遁，九死一生泛海南下，再举义旗。\",\"poems\":[]},\n {\"place\":\"零丁洋\",\"modern\":\"广东珠江口\",\"lon\":113.70,\"lat\":22.40,\"period\":\"1278—1279 · 被俘\",\"event\":\"五坡岭兵败被俘，元将张弘范逼其招降张世杰，书《过零丁洋》以对：人生自古谁无死，留取丹心照汗青。\",\"poems\":[111]},\n {\"place\":\"大都\",\"modern\":\"北京\",\"lon\":116.40,\"lat\":39.90,\"period\":\"1279—1283 · 就义\",\"event\":\"囚于兵马司土牢三年，作《正气歌》；元廷以宰相之位诱降不动，1283年1月从容就义，年四十七。\",\"poems\":[]}\n ]"}, {"id": 55, "name": "马致远", "zi": "", "hao": "东篱", "dynasty": "元", "years": "约1250—1321后", "title": "秋思之祖", "intro": "元代戏曲家、散曲家，「元曲四大家」之一，青年时曾热衷功名，后隐居田园。一曲《天净沙·秋思》被周德清誉为「秋思之祖」。", "story": "他年轻时也热衷功名，向太子献诗自荐未果，五十岁才做了个从五品的江浙省务官，不久看破，退出官场，隐居田园，号「东篱」。\n二十八个字、九个名词，无一动词连贯，一幅天涯羁旅图却活了起来。周德清评：「元人乐府，当以此曲为首。」杂剧《汉宫秋》同样是元曲第一流的杰作。", "storyTitle": "断肠人在天涯", "journey": ""}, {"id": 56, "name": "王冕", "zi": "元章", "hao": "煮石山农、梅花屋主", "dynasty": "元", "years": "1287—1359", "title": "梅花屋主", "intro": "元末画家、诗人。出身农家，牧牛读书，自学成材。一生不仕，隐居九里山，以卖画为生，尤善墨梅。", "story": "他幼年放牛，偷听学塾读书，暮归忘其牛——牛踩了田也不知道。父亲怒，母亲护：「儿痴如此，曷不听其所为？」从此住进寺庙，坐佛膝上，映长明灯读书。\n屡试不第后焚绝仕念，买舟下东吴，游历大江南北，最后隐居九里山，种豆种梅，自号梅花屋主。朱元璋曾授他谘议参军，他当晚就「病」死了——一树墨梅，只留清气。", "storyTitle": "梅花屋主", "journey": ""}, {"id": 57, "name": "于谦", "zi": "廷益", "hao": "节庵", "dynasty": "明", "years": "1398—1457", "title": "救时宰相", "intro": "明代名臣，永乐进士。土木堡之变后力排南迁之议，拥立景帝，组织北京保卫战挽狂澜。夺门之变后以「谋逆」罪冤死，谥忠肃。", "story": "土木堡之变，英宗被俘，京师震恐，有人主张南迁。他厉声说：「言南迁者，可斩也！」拥立景帝，整饬兵备，列阵九门之外，硬生生保住了北京。\n他一生清白：任地方大员进京述职不带一物，作诗自明「清风两袖朝天去」。夺门之变后，徐有贞一句「不杀于谦，此举为无名」，他便成了新皇权的祭品。抄家的官员发现，这位一品大员「家无余财」，只有正屋锁着的——是皇帝赐的蟒袍剑器。", "storyTitle": "北京保卫战", "journey": ""}, {"id": 58, "name": "唐寅", "zi": "伯虎", "hao": "六如居士、桃花庵主", "dynasty": "明", "years": "1470—1524", "title": "六如居士", "intro": "明代画家、诗人，「吴中四才子」之一。二十九岁中应天府解元，会试因科场案牵连入狱，从此绝意仕途，卖画为生。", "story": "他是那个时代最聪明的人之一：十六岁中秀才第一名，二十九岁应天府乡试又是第一（解元）。次年进京会试，被同行的富家子牵进泄题案，革除功名，黜充吏役。\n从此他半生潦倒，筑桃花庵卖画度日。宁王重金聘他，他察觉其反意，装疯裸奔于市才得脱身。「别人笑我太疯癫，我笑他人看不穿」——天才被制度碾碎后，把自己活成了一个传说。", "storyTitle": "桃花庵里", "journey": ""}, {"id": 59, "name": "纳兰性德", "zi": "容若", "hao": "楞伽山人", "dynasty": "清", "years": "1655—1685", "title": "清词第一人", "intro": "清代大学士明珠长子，康熙朝一等侍卫。词风清丽哀婉，直追李煜，王国维评为「北宋以来，一人而已」。三十一岁病逝。", "story": "他出身钟鸣鼎食之家，父亲是权相明珠，自己文武双全，十八岁中举，二十二岁殿试赐进士出身，做御前一等侍卫——命好到令人嫉妒。\n可他偏偏是「古之伤心人」：爱妻卢氏婚后三年病逝，从此「悼亡之吟不少，知己之恨尤深」。他结交的多是落魄汉人布衣，「于道义也甚笃」。1685年五月，与友人一醉后感慨，一病七日而逝。人间富贵，他全都拥有；词里写的，全是得不到的东西。", "storyTitle": "人生若只如初见", "journey": ""}, {"id": 60, "name": "龚自珍", "zi": "璱人", "hao": "定盦", "dynasty": "清", "years": "1792—1841", "title": "三百年来第一流", "intro": "清代思想家、诗人，近代改良主义先驱。主张「更法改图」，文纵横奥衍，诗瑰丽奇肆。柳亚子誉为「三百年来第一流」。", "story": "他出身书香官宦世家，却屡试不第，三十八岁才中进士，殿试三甲，「不得入翰林」。他一生大声疾呼变革：「九州生气恃风雷，万马齐喑究可哀。」\n1839年他辞官南归，途中写下三百一十五首绝句，即《己亥杂诗》——一部用诗写的自传与国是论。「落红不是无情物」，既是自伤，也是预言：四十年后，戊戌变法的君子们几乎人手一册他的文集。", "storyTitle": "万马齐喑", "journey": ""}, {"id": 61, "name": "袁枚", "zi": "子才", "hao": "随园主人、随园老人", "dynasty": "清", "years": "1716—1798", "title": "随园主人", "intro": "清代诗人、散文家、美食家。乾隆四年进士，历任溧水、江宁等县知县，三十三岁辞官，筑随园，优游山林诗酒近五十年。", "story": "他是清代最会生活的人：二十四岁中进士，三十三岁辞官，用三百金买下江宁小仓山一座荒园，修成随园——不做官的日子，写诗、收女弟子、研究食谱，《随园食单》至今是美食经典。\n他论诗主张「性灵」：诗要写真性情，不仿古，不掉书袋。一首《苔》写卑微者的盛放——「白日不到处，青春恰自来」，两百年后被谱成歌，唱给了每一个普通人。", "storyTitle": "性灵之说", "journey": ""}, {"id": 62, "name": "郑燮", "zi": "克柔", "hao": "板桥", "dynasty": "清", "years": "1693—1766", "title": "扬州八怪", "intro": "清代书画家、文学家，「扬州八怪」代表人物。诗书画三绝，尤擅画竹。做过十二年七品县令，为民请赈而罢官。", "story": "他四十四岁才中进士，五十岁起做范县、潍县县令。潍县大饥，他擅开官仓赈贷，僚属劝他先报朝廷，他说：「此何时？俟辗转申报，民无孑遗矣。」因此得罪豪绅去官。\n去官后卖画扬州，「大幅六两，小幅四两」，明码标价，洒脱之极。他画的竹，「千磨万击还坚劲」——那也是他自己的骨头。一枝一叶总关情，说的是竹，更是民。", "storyTitle": "一枝一叶总关情"}];
export const POEMS = [{"id": 1, "title": "饮酒", "subtitle": "其五", "poetId": 1, "dynasty": "魏晋", "genre": "五言古诗", "paragraphs": "结庐在人境，而无车马喧。\n问君何能尔？心远地自偏。\n采菊东篱下，悠然见南山。\n山气日夕佳，飞鸟相与还。\n此中有真意，欲辨已忘言。", "annotation": "结庐：建造屋舍。尔：如此、这样。日夕：傍晚。相与还：结伴归巢。", "translation": "把屋舍建在人来人往之地，却听不见车马的喧闹。问我为什么能这样？心离尘世远了，住处自然就偏静了。东篱下采菊，不经意间抬头，南山恰好映入眼帘。暮色中山气缭绕，飞鸟结伴归巢。这里头有生活的真意，想分辨清楚，却已忘了怎么说。", "appreciation": "全诗没有一个\"隐\"字，却句句是隐居的况味。\"心远地自偏\"是全篇诗眼——避世不在身，而在心。\"采菊东篱下，悠然见南山\"中一个\"见\"字（非\"望\"字），写尽物我两忘的偶然与天成，被王国维推为\"无我之境\"的典范。", "mood": "田园", "famousLine": "采菊东篱下，悠然见南山", "poetName": "陶渊明"}, {"id": 2, "title": "归园田居", "subtitle": "其三", "poetId": 1, "dynasty": "魏晋", "genre": "五言古诗", "paragraphs": "种豆南山下，草盛豆苗稀。\n晨兴理荒秽，带月荷锄归。\n道狭草木长，夕露沾我衣。\n衣沾不足惜，但使愿无违。", "annotation": "晨兴：早起。荒秽：杂草。荷：扛着。愿无违：不违背归隐的心愿。", "translation": "在南山下种豆，草长得比豆苗还茂盛。清早起来清除杂草，傍晚顶着月光扛锄头回家。狭窄的小路上草木丛生，晚露打湿了我的衣裳。衣裳湿了不值得可惜，只要不违背我的心愿就好。", "appreciation": "种豆偏偏\"豆苗稀\"，可见诗人实在不擅农事——但他毫不在意。全诗最动人的是\"带月荷锄归\"：一天的劳作在月光里收束成一幅剪影，辛苦被诗意轻轻托住。结句\"但使愿无违\"交代了一切代价的取舍：身体之苦，换精神自由，值。", "mood": "田园", "famousLine": "带月荷锄归", "poetName": "陶渊明"}, {"id": 3, "title": "静夜思", "subtitle": "", "poetId": 2, "dynasty": "唐", "genre": "五言绝句", "paragraphs": "床前明月光，疑是地上霜。\n举头望明月，低头思故乡。", "annotation": "疑：好像。霜：月光清冷洁白，故以霜为喻。", "translation": "床前洒满明亮的月光，好像地上铺了一层秋霜。抬头望着天上的明月，低下头来，思念起远方的故乡。", "appreciation": "二十个字，无一奇字险句，却成了中国人会说的第一首诗。妙处在两个动作：举头，是望月；低头，是望心。月光是媒介，把天涯游子和千里故乡照在同一个圆里。不写愁而愁自现，不写乡而乡自远。", "mood": "思乡", "famousLine": "低头思故乡", "poetName": "李白"}, {"id": 4, "title": "望庐山瀑布", "subtitle": "", "poetId": 2, "dynasty": "唐", "genre": "七言绝句", "paragraphs": "日照香炉生紫烟，遥看瀑布挂前川。\n飞流直下三千尺，疑是银河落九天。", "annotation": "香炉：庐山香炉峰。川：此指瀑布如白练挂于山前。九天：天之极高处。", "translation": "阳光照在香炉峰上，升起紫色的云烟。远远望去，瀑布像一条白练悬挂在山前。水流飞泻而下三千尺，让人疑心是银河从九重天倾落人间。", "appreciation": "一个\"生\"字写出烟云的流动，一个\"挂\"字写出瀑布的静止之姿，而\"疑是银河落九天\"则是只有李白才敢想的比喻——把人间的山川直接接到天上。夸饰到极处反而逼真，这就是\"诗仙\"的想象特权。", "mood": "山水", "famousLine": "飞流直下三千尺，疑是银河落九天", "poetName": "李白"}, {"id": 5, "title": "月下独酌", "subtitle": "其一", "poetId": 2, "dynasty": "唐", "genre": "五言古诗", "paragraphs": "花间一壶酒，独酌无相亲。\n举杯邀明月，对影成三人。\n月既不解饮，影徒随我身。\n暂伴月将影，行乐须及春。\n我歌月徘徊，我舞影零乱。\n醒时同交欢，醉后各分散。\n永结无情游，相期邈云汉。", "annotation": "无相亲：没有亲近之人。不解饮：不懂得饮酒之趣。无情游：与无情之物（月与影）的交游。邈云汉：远在天河。", "translation": "花丛间摆一壶酒，自斟自饮没有亲友。举起酒杯邀请明月，加上自己的影子，恰好凑成三个人。月亮不懂得饮酒，影子也只徒然跟随我身。姑且伴着月与影，趁这春光及时行乐。我歌唱时月亮徘徊不去，我起舞时影子摇曳零乱。清醒时一同欢聚，醉后便各自飘散。愿与它们结下忘却世情的交游，相约在遥远的天河再会。", "appreciation": "孤独被李白写成了排场：明明独酌，偏要\"邀月对影成三人\"，把冷清闹成热闹。可\"月不解饮，影徒随身\"，热闹到极处恰恰是孤独到极处。结尾却陡然升华——与无情之物结永恒之游，孤独至此，已是境界。", "mood": "月夜", "famousLine": "举杯邀明月，对影成三人", "poetName": "李白"}, {"id": 6, "title": "早发白帝城", "subtitle": "", "poetId": 2, "dynasty": "唐", "genre": "七言绝句", "paragraphs": "朝辞白帝彩云间，千里江陵一日还。\n两岸猿声啼不住，轻舟已过万重山。", "annotation": "白帝：白帝城，地势极高，晨霞映照故云\"彩云间\"。江陵：今湖北荆州。住：停歇。", "translation": "清晨告别高入彩云的白帝城，千里之遥的江陵，一天就到了。两岸猿声还在耳边不停地啼叫，轻快的小船已驶过万重山峦。", "appreciation": "这首诗写于流放夜郎途中遇赦返回之时。五十九岁的李白突然重获自由，喜从天降，于是千里水路成了\"一日还\"，万重山成了身后轻烟。猿声未停而轻舟已过——速度感里全是心跳。没有一字言喜，而狂喜扑面而来。", "mood": "豪放", "famousLine": "轻舟已过万重山", "poetName": "李白"}, {"id": 7, "title": "山居秋暝", "subtitle": "", "poetId": 3, "dynasty": "唐", "genre": "五言律诗", "paragraphs": "空山新雨后，天气晚来秋。\n明月松间照，清泉石上流。\n竹喧归浣女，莲动下渔舟。\n随意春芳歇，王孙自可留。", "annotation": "暝：日暮。浣女：洗衣的女子。春芳歇：春天的芳华凋谢。王孙：贵族子弟，此为诗人自指，反用《楚辞》\"王孙兮归来\"之意。", "translation": "空旷的山中刚下过一场新雨，傍晚的天气带来初秋的凉意。明月透过松林洒下清辉，清泉在山石上淙淙流淌。竹林里传来喧笑，是浣衣女子归来；莲叶摇动，是渔舟顺流而下。任凭春天的芳菲消歇吧，这秋色里，王孙自可长留。", "appreciation": "颔联\"明月松间照，清泉石上流\"，一静一动，光影与声响俱在，是不着一色的水墨。颈联先闻竹喧、后见人归，先觉莲动、方知舟来——倒装的写法让画面有了听觉的先导。山居如此，人间朝廷的纷扰，自然是\"随意春芳歇\"了。", "mood": "山水", "famousLine": "明月松间照，清泉石上流", "poetName": "王维"}, {"id": 8, "title": "鹿柴", "subtitle": "", "poetId": 3, "dynasty": "唐", "genre": "五言绝句", "paragraphs": "空山不见人，但闻人语响。\n返景入深林，复照青苔上。", "annotation": "鹿柴：辋川别业中的一处地名。但：只。返景：夕阳返照的光。", "translation": "空旷的山中看不见人影，只偶尔听得有人说话的声音。夕阳的余晖穿过深林，又照在那片青苔上。", "appreciation": "二十个字全是\"空\"的辩证法：看不见人，却有人语；人语愈清晰，山愈空寂。光影入林照苔——光愈亮，林愈深。王维以声写寂、以光写暗，四句诗是一堂禅意的\"以有衬无\"，也是他晚年心境的写照。", "mood": "山水", "famousLine": "空山不见人，但闻人语响", "poetName": "王维"}, {"id": 9, "title": "送元二使安西", "subtitle": "", "poetId": 3, "dynasty": "唐", "genre": "七言绝句", "paragraphs": "渭城朝雨浥轻尘，客舍青青柳色新。\n劝君更尽一杯酒，西出阳关无故人。", "annotation": "渭城：秦时咸阳城，在长安西北。浥：湿润。更尽：再喝完。阳关：在今甘肃敦煌西南，出关即离中原。", "translation": "渭城清晨的细雨打湿了路上轻尘，客舍旁的柳枝被洗得青翠一新。劝你再干了这杯酒吧，向西出了阳关，就再没有我这样的老朋友了。", "appreciation": "送别诗写到极致，往往只是一个小动作。\"更尽一杯酒\"——不是不忍别，是想再拖延一刻。前两句的朝雨、青柳，把离别的空气洗得清清爽爽；后两句一出，千年来所有送行的酒桌上，都有了这同一句话。", "mood": "送别", "famousLine": "劝君更尽一杯酒，西出阳关无故人", "poetName": "王维"}, {"id": 10, "title": "九月九日忆山东兄弟", "subtitle": "", "poetId": 3, "dynasty": "唐", "genre": "七言绝句", "paragraphs": "独在异乡为异客，每逢佳节倍思亲。\n遥知兄弟登高处，遍插茱萸少一人。", "annotation": "山东：指华山以东的家乡蒲州。茱萸：香气浓烈的植物，重阳节佩之以辟邪。", "translation": "独自客居异乡，每到佳节就加倍思念亲人。遥想兄弟们今日登高远望，身上都插着茱萸，唯独少了我一人。", "appreciation": "写此诗时王维年仅十七。\"每逢佳节倍思亲\"之所以千古不移，在于它道破了思亲的\"倍数效应\"：平日尚可压抑，节日的热闹一来，孤独立刻翻倍。更妙的是后两句不说自己如何想兄弟，反写兄弟登高时发现\"少一人\"——把思念写成了一场双向的缺位。", "mood": "思乡", "famousLine": "每逢佳节倍思亲", "poetName": "王维"}, {"id": 11, "title": "春望", "subtitle": "", "poetId": 4, "dynasty": "唐", "genre": "五言律诗", "paragraphs": "国破山河在，城春草木深。\n感时花溅泪，恨别鸟惊心。\n烽火连三月，家书抵万金。\n白头搔更短，浑欲不胜簪。", "annotation": "国：国都长安。浑：简直。不胜簪：插不住簪子。", "translation": "国都沦陷，山河依旧，长安城春天来了，到处草木深深。感伤时局，见花开反而落泪；怅恨离别，闻鸟鸣反而惊心。战火连绵已过了三个月，家书难得，一封抵得上万金。愁白的头发越搔越短，简直要插不住簪子了。", "appreciation": "\"国破山河在\"五字抵得上千言：物是人非，山河无言。花本是乐景，鸟本是常声，此刻却\"溅泪\"\"惊心\"——不是景变了，是心碎了。\"家书抵万金\"从此成为中国人写\"音讯\"的最高价码。全诗沉郁顿挫，字字都是时代的裂痕。", "mood": "家国", "famousLine": "国破山河在，城春草木深", "poetName": "杜甫"}, {"id": 12, "title": "春夜喜雨", "subtitle": "", "poetId": 4, "dynasty": "唐", "genre": "五言律诗", "paragraphs": "好雨知时节，当春乃发生。\n随风潜入夜，润物细无声。\n野径云俱黑，江船火独明。\n晓看红湿处，花重锦官城。", "annotation": "乃：就、便。潜：悄悄地。红湿处：被雨打湿的红花。花重：花因带雨而沉重。锦官城：成都。", "translation": "好雨懂得时令，正值春天便降落。随着春风在夜里悄悄落下，无声地滋润着万物。田野小径上乌云漆黑，只有江船上的灯火独自明亮。等天亮去看那红花带雨之处，成都城里的花，开得沉甸甸一片。", "appreciation": "题目一个\"喜\"字统摄全篇，但通篇没有一个\"喜\"字。\"潜入夜\"\"细无声\"——把雨写成了谦谦君子，做好事而不惊动人。这既是春雨，也是杜甫心中理想政治的样子。末句悬想明日繁花，喜意这才破纸而出。", "mood": "田园", "famousLine": "随风潜入夜，润物细无声", "poetName": "杜甫"}, {"id": 13, "title": "月夜忆舍弟", "subtitle": "", "poetId": 4, "dynasty": "唐", "genre": "五言律诗", "paragraphs": "戍鼓断人行，边秋一雁声。\n露从今夜白，月是故乡明。\n有弟皆分散，无家问死生。\n寄书长不达，况乃未休兵。", "annotation": "戍鼓：戍楼上的更鼓。断人行：宵禁，路上断绝行人。舍弟：对人称自己的弟弟。况乃：何况是。", "translation": "戍楼更鼓响过，路上不见行人，边地的秋空中，传来孤雁的哀鸣。从今夜就进了白露节气，月亮还是故乡的最明。兄弟们各自离散，家已不存，生死无处打听。寄出去的书信总是送不到，何况战乱还没有平息。", "appreciation": "\"月是故乡明\"是典型的\"无理而妙\"：天下的月本无二致，偏心的人才有故乡的月。这句诗的高明在于坦白——思念本来就不讲道理。后半首转入生死茫茫的追问，个人的怀人背后，是整个战乱时代的骨肉离散。", "mood": "月夜", "famousLine": "露从今夜白，月是故乡明", "poetName": "杜甫"}, {"id": 14, "title": "登高", "subtitle": "", "poetId": 4, "dynasty": "唐", "genre": "七言律诗", "paragraphs": "风急天高猿啸哀，渚清沙白鸟飞回。\n无边落木萧萧下，不尽长江滚滚来。\n万里悲秋常作客，百年多病独登台。\n艰难苦恨繁霜鬓，潦倒新停浊酒杯。", "annotation": "渚：水中小洲。落木：落叶。百年：一生，此指晚年。新停：最近戒酒。", "translation": "风急天高，猿声悲哀；小洲清冷，白沙之上鸟儿盘旋。无边的落叶萧萧而下，望不尽的长江滚滚奔来。悲对秋色，感慨万里漂泊常年为客；一生多病，今日独自登上高台。时世艰难，愁白了双鬓；穷困潦倒，偏偏又戒了消愁的酒。", "appreciation": "被历代评家推为\"古今七律第一\"。前四句写景，\"无边\"\"不尽\"把秋意与江水都推向时间的无穷；后四句写身世，万里、悲秋、作客、多病、独登——数层愁绪叠在一处，读来一气贯注。末句连借酒浇愁都不可得，悲至此，已无处可排遣。", "mood": "悲秋", "famousLine": "无边落木萧萧下，不尽长江滚滚来", "poetName": "杜甫"}, {"id": 15, "title": "赋得古原草送别", "subtitle": "", "poetId": 5, "dynasty": "唐", "genre": "五言律诗", "paragraphs": "离离原上草，一岁一枯荣。\n野火烧不尽，春风吹又生。\n远芳侵古道，晴翠接荒城。\n又送王孙去，萋萋满别情。", "annotation": "离离：茂盛的样子。远芳：蔓延到远方的芳草。王孙：此指远行的友人。萋萋：草茂盛的样子。", "translation": "原野上长满茂盛的青草，年年岁岁枯了又荣。野火烧不尽它，春风一吹又重新生长。芳草远伸，渐渐侵占了古道；阳光下的翠绿，连接着荒城。又要送友人远行了，这茂密的萋萋芳草，满满都是离别之情。", "appreciation": "据说此诗是白居易十六岁的应考习作，顾况先以其名打趣\"长安米贵，居大不易\"，读到\"野火烧不尽\"二句，当即改口：\"有句如此，居天下有甚难！\"\n\"野火—春风\"两句写尽生命的韧性，也是全诗从送别之愁里挣出来的一股劲：草会枯，但烧不尽；人会别，但情如春草，更行更远还生。", "mood": "送别", "famousLine": "野火烧不尽，春风吹又生", "poetName": "白居易"}, {"id": 16, "title": "钱塘湖春行", "subtitle": "", "poetId": 5, "dynasty": "唐", "genre": "七言律诗", "paragraphs": "孤山寺北贾亭西，水面初平云脚低。\n几处早莺争暖树，谁家新燕啄春泥。\n乱花渐欲迷人眼，浅草才能没马蹄。\n最爱湖东行不足，绿杨阴里白沙堤。", "annotation": "水面初平：湖水与堤岸齐平，指春水初涨。云脚低：云气低垂，与水面相连。暖树：向阳的树。行不足：游不够。", "translation": "从孤山寺北到贾亭西面，春水初涨与岸齐平，云气低垂与湖水相连。几只早出的黄莺争着飞向向阳的树枝，不知是谁家的新燕正衔泥筑巢。纷繁的春花渐渐要迷住人的眼睛，浅浅的春草刚刚能够没过马蹄。最爱湖东的景致，总也游不够，那绿杨荫里的白沙堤。", "appreciation": "一首\"早春\"的工笔画：莺是\"早莺\"、燕是\"新燕\"、花\"渐欲\"、草\"才能\"——处处扣住一个\"初\"字，万物都处于将盛未盛的节点，满纸是生的躁动。尾句\"行不足\"三字收束，游人不肯走，春色也就永远走不完。", "mood": "山水", "famousLine": "乱花渐欲迷人眼，浅草才能没马蹄", "poetName": "白居易"}, {"id": 17, "title": "暮江吟", "subtitle": "", "poetId": 5, "dynasty": "唐", "genre": "七言绝句", "paragraphs": "一道残阳铺水中，半江瑟瑟半江红。\n可怜九月初三夜，露似真珠月似弓。", "annotation": "瑟瑟：碧绿色，指未被残阳照到的江面。可怜：可爱。", "translation": "一道残阳的余晖平铺在江面上，半江是碧绿，半江是艳红。最可爱的是这九月初三的夜晚，露珠圆润如珍珠，新月弯弯如弯弓。", "appreciation": "两句写尽夕照的物理：残阳贴着水面\"铺\"来，受光半江红、背光半江碧，颜色学般精准，又是何等天真的欢喜。后两句把九月初三这个平常日子过成了节日——露与月，一珠一弓，皆是小小圆满。白居易的可爱，在于他永远肯为寻常黄昏驻足。", "mood": "月夜", "famousLine": "露似真珠月似弓", "poetName": "白居易"}, {"id": 18, "title": "水调歌头", "subtitle": "明月几时有", "poetId": 6, "dynasty": "宋", "genre": "词", "paragraphs": "明月几时有？把酒问青天。不知天上宫阙，今夕是何年。\n我欲乘风归去，又恐琼楼玉宇，高处不胜寒。起舞弄清影，何似在人间。\n\n转朱阁，低绮户，照无眠。不应有恨，何事长向别时圆？\n人有悲欢离合，月有阴晴圆缺，此事古难全。但愿人长久，千里共婵娟。", "annotation": "宫阙：月中宫殿。琼楼玉宇：月中仙宫。婵娟：指明月。绮户：雕花的门窗。", "translation": "明月从什么时候开始有的？我端着酒杯询问青天。不知天上的宫殿，今晚是哪一年。想乘着清风回到天上去，又怕月宫里玉砌的高楼，受不了那份高寒。起身舞弄月下的清影，哪里比得上留在人间。\n月光转过朱红的楼阁，低低地照进雕花的窗户，照着无眠的人。月亮不该有什么怨恨吧，为何总在人们离别时才圆？人有悲欢离合，月有阴晴圆缺，这种事自古难以两全。只希望彼此都能平安长久，隔着千里，共赏这一轮明月。", "appreciation": "丙辰中秋，苏轼在密州想念七年未见的弟弟苏辙，写下此词。上半阕问天：去还是不去？——\"高处不胜寒\"，最终选择留在人间，这是他对仕途的全部态度。下半阕问月：为何偏在离别时圆？——随即自己答了：此事古难全。\n词从豪问到哲思再到祝愿，完成了一次自我安慰，也安慰了此后千年所有中秋不能团圆的人。", "mood": "月夜", "famousLine": "但愿人长久，千里共婵娟", "poetName": "苏轼"}, {"id": 19, "title": "饮湖上初晴后雨", "subtitle": "其二", "poetId": 6, "dynasty": "宋", "genre": "七言绝句", "paragraphs": "水光潋滟晴方好，山色空蒙雨亦奇。\n若把西湖比西子，淡妆浓抹总相宜。", "annotation": "潋滟：水波荡漾闪光的样子。空蒙：迷茫缥缈。西子：即西施。", "translation": "晴天，西湖水光潋滟，正是明媚动人；雨天，山色空蒙缥缈，也别有一番奇妙。如果把西湖比作美女西施，无论淡妆还是浓抹，都同样恰到好处。", "appreciation": "写西湖的诗千千万，从此全被这两句封顶。妙在\"亦奇\"的平等观：晴有晴的好，雨有雨的奇，不偏爱、不避雨——这本就是苏轼的人生态度。以西子喻湖，\"淡妆浓抹总相宜\"，从此西湖又多了一个名字：西子湖。", "mood": "山水", "famousLine": "欲把西湖比西子，淡妆浓抹总相宜", "poetName": "苏轼"}, {"id": 20, "title": "题西林壁", "subtitle": "", "poetId": 6, "dynasty": "宋", "genre": "七言绝句", "paragraphs": "横看成岭侧成峰，远近高低各不同。\n不识庐山真面目，只缘身在此山中。", "annotation": "横看：从正面看。缘：因为。", "translation": "横着看是连绵山岭，侧着看是高耸山峰，远近高低，姿态各不相同。认不清庐山真正的面目，只因为我自己就置身在这座山中。", "appreciation": "元丰七年，苏轼由黄州改迁汝州，特地上庐山。这是首题壁诗，也是首哲理诗：全诗无一句写景的雕琢，却道破了一个认知困境——身在局中，难识全局。\"不识庐山真面目\"从此成为汉语里对\"当局者迷\"最好的表达。", "mood": "哲理", "famousLine": "不识庐山真面目，只缘身在此山中", "poetName": "苏轼"}, {"id": 21, "title": "如梦令", "subtitle": "常记溪亭日暮", "poetId": 7, "dynasty": "宋", "genre": "词", "paragraphs": "常记溪亭日暮，沉醉不知归路。\n兴尽晚回舟，误入藕花深处。\n争渡，争渡，惊起一滩鸥鹭。", "annotation": "常记：曾记得。藕花：荷花。争渡：奋力划船。鸥鹭：鸥鸟与白鹭。", "translation": "常记得那次溪亭日暮，喝得沉醉，找不到回家的路。游兴满足了，天黑才划船回返，却误入荷花深处。划呀，划呀，惊起了满滩栖息的鸥鹭。", "appreciation": "这是李清照少女时代的作品，是她的\"青春纪念册\"。三十三个字，有酒意、有迷路、有慌乱、有水鸟扑棱棱飞起——全是动态的。少女的天真烂漫与自然的花香鸟趣浑然一体，谁能想到，这双摇桨的手，晚年会写出\"寻寻觅觅\"。", "mood": "闲适", "famousLine": "兴尽晚回舟，误入藕花深处", "poetName": "李清照"}, {"id": 22, "title": "声声慢", "subtitle": "寻寻觅觅", "poetId": 7, "dynasty": "宋", "genre": "词", "paragraphs": "寻寻觅觅，冷冷清清，凄凄惨惨戚戚。\n乍暖还寒时候，最难将息。\n三杯两盏淡酒，怎敌他、晚来风急！\n雁过也，正伤心，却是旧时相识。\n\n满地黄花堆积，憔悴损，如今有谁堪摘？\n守着窗儿，独自怎生得黑！\n梧桐更兼细雨，到黄昏、点点滴滴。\n这次第，怎一个愁字了得！", "annotation": "乍暖还寒：天气忽暖忽冷。将息：调养休息。黄花：菊花。怎生：怎么。次第：光景、情形。", "translation": "整日寻觅，却只寻得一片冷清，徒留凄惨忧戚。忽暖忽寒的时节，最难保养安息。喝下三杯两盏淡酒，怎么抵挡傍晚的急风！大雁飞过，正教人伤心，它们却是当年与我有旧的大雁。满地菊花堆积，已然憔悴枯损，如今还有谁堪与我同摘？守着窗子，独自怎挨到天黑！梧桐上又落细雨，到黄昏，点点滴滴。这般光景，一个\"愁\"字，怎么概括得了！", "appreciation": "开篇十四个叠字，由外到内、由浅入深，把无所依傍的心境一寸寸写尽，千古无人敢再试。雁\"旧时相识\"——旧时雁是传信的，如今信寄给谁？酒是\"淡\"的，天是挨不到黑的，最后收束在一个\"愁\"字又立刻宣布这个字不够用。\n国破、家亡、夫死、物散，一个\"愁\"字确实太轻了。", "mood": "怀人", "famousLine": "寻寻觅觅，冷冷清清，凄凄惨惨戚戚", "poetName": "李清照"}, {"id": 23, "title": "西江月", "subtitle": "夜行黄沙道中", "poetId": 8, "dynasty": "宋", "genre": "词", "paragraphs": "明月别枝惊鹊，清风半夜鸣蝉。\n稻花香里说丰年，听取蛙声一片。\n\n七八个星天外，两三点雨山前。\n旧时茅店社林边，路转溪桥忽见。", "annotation": "别枝：斜枝。社林：土地庙旁的树林。见：同\"现\"。", "translation": "明亮的月光惊起了枝头的乌鹊，半夜清风里传来阵阵蝉鸣。稻花香里，一片蛙声，像在诉说丰年。七八颗星挂在天边，两三点雨落在山前。旧时的茅店还在土地庙树林旁，转过溪桥，它忽然出现在眼前。", "appreciation": "闲居带湖的辛弃疾，难得有这样松弛的夜晚。最妙的是结尾的\"忽见\"：前一刻还念着\"旧时茅店\"在何处，转过溪桥它就出现了——夜行的心跳，被一句平淡的\"忽见\"轻轻接住。武将的词，也有这样温柔的路感。", "mood": "田园", "famousLine": "稻花香里说丰年，听取蛙声一片", "poetName": "辛弃疾"}, {"id": 24, "title": "破阵子", "subtitle": "为陈同甫赋壮词以寄之", "poetId": 8, "dynasty": "宋", "genre": "词", "paragraphs": "醉里挑灯看剑，梦回吹角连营。\n八百里分麾下炙，五十弦翻塞外声，沙场秋点兵。\n\n马作的卢飞快，弓如霹雳弦惊。\n了却君王天下事，赢得生前身后名。可怜白发生！", "annotation": "陈同甫：陈亮，辛弃疾的挚友，同主北伐。八百里：指牛。麾下：部下。五十弦：泛指军乐器。作的卢：战马像的卢马那样。", "translation": "醉里挑亮灯火端详宝剑，梦中回到号角连天的军营。把烤牛肉分给部下，琴瑟奏起悲壮的塞外军歌，秋天的沙场上正在检阅军队。战马奔驰如的卢马般飞快，弓弦响处如惊雷霹雳。本想替君王完成收复天下的大业，赢得生前死后的美名。可惜——满头白发已经丛生！", "appreciation": "从醉里、梦里到沙场点兵，一路疾风骤雨，全是二十三岁夜袭金营的那个辛弃疾。到\"了却君王天下事\"，气壮山河——然后\"可怜白发生\"五个字，一盆冷水兜头浇下。前面九句是梦，最后一句才是现实。这五个字的落差，就是他的一生。", "mood": "壮志", "famousLine": "醉里挑灯看剑，梦回吹角连营", "poetName": "辛弃疾"}, {"id": 25, "title": "观沧海", "subtitle": "", "poetId": 9, "dynasty": "魏晋", "genre": "四言乐府", "paragraphs": "东临碣石，以观沧海。\n水何澹澹，山岛竦峙。\n树木丛生，百草丰茂。\n秋风萧瑟，洪波涌起。\n日月之行，若出其中；\n星汉灿烂，若出其里。\n幸甚至哉，歌以咏志。", "annotation": "碣石：山名，在今河北昌黎。澹澹：水波荡漾的样子。竦峙：高高耸立。星汉：银河。", "translation": "东行登上碣石山，来观赏那苍茫的大海。海水多么宽阔浩荡，山岛高高挺立。岛上树木丛生，百草繁茂。秋风吹过，树木飒飒作响，海中翻涌起巨大的波涛。日月的运行，好像从这浩瀚的海洋中出发；银河星光灿烂，也好像出自这浩瀚的海洋。真是幸运极了，用这首诗歌来抒发心志。", "appreciation": "写沧海，也是在写自己。北征乌桓凯旋，五十三岁的曹操站在碣石山上，把吞吐日月星汉的气象装进了大海——这不是写景的视角，是征服者的视角。通篇无一字言志，而宇宙胸襟尽出，结句「歌以咏志」反而是多余的了。", "mood": "豪放", "famousLine": "星汉灿烂，若出其里", "poetName": "曹操"}, {"id": 26, "title": "龟虽寿", "subtitle": "", "poetId": 9, "dynasty": "魏晋", "genre": "四言乐府", "paragraphs": "神龟虽寿，犹有竟时。\n腾蛇乘雾，终为土灰。\n老骥伏枥，志在千里；\n烈士暮年，壮心不已。\n盈缩之期，不但在天；\n养怡之福，可得永年。\n幸甚至哉，歌以咏志。", "annotation": "竟：终结，终了。腾蛇：传说中乘雾飞行的神蛇。烈士：有远大抱负的人。盈缩：指寿命长短。养怡：保养身心。", "translation": "神龟虽然长寿，但终究有终结之时；腾蛇即使能乘雾飞天，死后也会化为土灰。年老的千里马虽然伏在马槽旁，雄心壮志仍是驰骋千里；有远大抱负的人士到了晚年，奋发思进的雄心不会止息。人的寿命长短，不只是由上天决定；只要保养身心，也可以延年益寿。真是幸运极了，用这首诗歌来表达自己的志向。", "appreciation": "时年五十三，「已矣哉」的年纪，他却写出了文学史上最昂扬的一首老之歌。先以神龟腾蛇说人终有一死，笔锋一转，正是这有限之身里，「老骥伏枥」四字迸出千钧之力——生命不以长度论，而以燃烧的程度论。这首诗式的乐观，比一切养生经都更能「可得永年」。", "mood": "哲理", "famousLine": "老骥伏枥，志在千里", "poetName": "曹操"}, {"id": 27, "title": "短歌行", "subtitle": "其一", "poetId": 9, "dynasty": "魏晋", "genre": "四言乐府", "paragraphs": "对酒当歌，人生几何！\n譬如朝露，去日苦多。\n慨当以慷，忧思难忘。\n何以解忧？唯有杜康。\n青青子衿，悠悠我心。\n但为君故，沉吟至今。\n呦呦鹿鸣，食野之苹。\n我有嘉宾，鼓瑟吹笙。\n明明如月，何时可掇？\n忧从中来，不可断绝。\n越陌度阡，枉用相存。\n契阔谈讌，心念旧恩。\n月明星稀，乌鹊南飞。\n绕树三匝，何枝可依？\n山不厌高，海不厌深。\n周公吐哺，天下归心。", "annotation": "几何：多少。杜康：相传最早酿酒的人，代指酒。子衿：周代学子的服装，代指贤才。掇：拾取，此为求而得之。讌：通「宴」。三匝：三圈。吐哺：吐出口中食物，指周公一顿饭三次吐哺起身接见贤士。", "translation": "一边喝酒一边高歌，人生的岁月有多少！好比晨露转瞬即逝，逝去的时光实在太多。席上歌声激昂慷慨，忧郁长久填满心窝。靠什么来排解忧闷？唯有狂饮方可解脱。穿青色衣领的学子，你们令我朝思暮想。只是因为你们的缘故，让我沉痛吟诵至今。阳光下鹿群呦呦欢鸣，悠然自得啃食绿坡。一旦四方贤才光临舍下，我将奏瑟吹笙宴请嘉宾。当空悬挂的皓月哟，何时才可以拾取；久蓄于心的忧愤哟，突然喷涌不可断绝。远方宾客踏着田间小路，一一屈驾前来探望我。久别重逢欢宴畅谈，争着将往日的情谊诉说。明月升起，星光闪烁，一群寻巢乌鹊向南飞去。绕树飞了三周却没敛翅，哪里才有它们栖身之所？高山不辞土石才见巍峨，大海不弃涓流方显壮阔。我愿如周公一般礼贤下士，愿天下的英杰真心归顺于我。", "appreciation": "「忧」之一字，贯穿全诗：忧人生短促，更忧贤才难得。他把自己写成一个立在暮色里的招贤者，用《诗经》里恋人的口吻思慕「青青子衿」——求贤求到了深情处。末尾忽然翻出吞吐天地的气象：山不厌高，海不厌深。英雄的孤独与英雄的抱负，在四言的旧瓶里酿出了建安最醇的一坛酒。", "mood": "豪放", "famousLine": "周公吐哺，天下归心", "poetName": "曹操"}, {"id": 28, "title": "蒿里行", "subtitle": "", "poetId": 9, "dynasty": "魏晋", "genre": "四言乐府", "paragraphs": "关东有义士，兴兵讨群凶。\n初期会盟津，乃心在咸阳。\n军合力不齐，踌躇而雁行。\n势利使人争，嗣还自相戕。\n淮南弟称号，刻玺于北方。\n铠甲生虮虱，万姓以死亡。\n白骨露于野，千里无鸡鸣。\n生民百遗一，念之断人肠。", "annotation": "义士：指讨伐董卓的关东州郡首领。盟津：周武王会盟诸侯伐纣之地，代指讨董联盟。雁行：大雁成行，喻讨董诸军观望不前。嗣还：其后。淮南弟称号：袁绍之弟袁术在淮南称帝。刻玺：袁绍谋废立、刻玉玺。", "translation": "关东的仗义之士都起兵讨伐凶残的董卓。当初约在盟津会师，心向汉室咸阳。可惜军合力不齐，踌躇观望如雁阵。势力利益使人相争，随后自相残杀。袁术在淮南称帝号，袁绍谋刻玉玺于北方。战士们的铠甲上都生了虮虱，百姓因此大量死亡。白骨暴露在荒野，千里之内听不见鸡鸣。活着的百姓百不剩一，念及此处令人肝肠寸断。", "appreciation": "这是一首「诗史」：讨董联盟如何从义举堕为内战，他一路亲历。最后四句没有任何修辞——白骨、荒野、无鸡鸣——白描到底，反而重逾千钧。史称曹操「倘使当年身便死，一生真伪有谁知」，可这首诗里的悲悯是装不出来的：他对乱世的痛，先于他对乱世的收拾。", "mood": "家国", "famousLine": "白骨露于野，千里无鸡鸣", "poetName": "曹操"}, {"id": 29, "title": "春晓", "subtitle": "", "poetId": 10, "dynasty": "唐", "genre": "五言绝句", "paragraphs": "春眠不觉晓，\n处处闻啼鸟。\n夜来风雨声，\n花落知多少。", "annotation": "晓：天刚亮。闻：听见。", "translation": "春天睡醒不觉天已大亮，到处是鸟儿清脆的叫声。回想昨夜的阵阵风雨声，不知吹落了多少娇美的春花。", "appreciation": "二十个字，全是听来的春天：醒来听鸟，忆夜听雨，还想听花落。不写所见只写所闻，春天反而漫无边际地铺开了。末句「知多少」轻轻一问，惜春而不伤春——隐者对光阴的态度，原来是这么温柔。", "mood": "闲适", "famousLine": "春眠不觉晓，处处闻啼鸟", "poetName": "孟浩然"}, {"id": 30, "title": "过故人庄", "subtitle": "", "poetId": 10, "dynasty": "唐", "genre": "五言律诗", "paragraphs": "故人具鸡黍，邀我至田家。\n绿树村边合，青山郭外斜。\n开轩面场圃，把酒话桑麻。\n待到重阳日，还来就菊花。", "annotation": "具：准备，置办。鸡黍：农家待客的丰盛饭菜。合：环绕。轩：窗。场圃：打谷场和菜园。就：赴，欣赏。", "translation": "老朋友预备丰盛的饭菜，邀请我去他乡村田舍。翠绿的树林围绕着村落，苍青的山峦在城外横卧。推开窗户面对谷场菜园，手举酒杯闲谈庄稼情况。等到九九重阳节到来时，我还要来这里观赏菊花。", "appreciation": "一场最平常的田家饭，被写成了千古请柬。妙处全在不经意：不写情而情自浓——「待到重阳日，还来就菊花」，走的时候已经开始约下一顿。田园的可亲、故人的可交、盛唐农村的安稳，全在这句顺口而出的话里。", "mood": "田园", "famousLine": "待到重阳日，还来就菊花", "poetName": "孟浩然"}, {"id": 31, "title": "宿建德江", "subtitle": "", "poetId": 10, "dynasty": "唐", "genre": "五言绝句", "paragraphs": "移舟泊烟渚，\n日暮客愁新。\n野旷天低树，\n江清月近人。", "annotation": "烟渚：烟雾笼罩的小洲。客：旅人。旷：空阔。", "translation": "把船停泊在烟雾弥漫的沙洲旁，日落时分新愁又涌上了游子心头。原野空旷，远处的天空好像比树木还低；江水清澈，映照得月亮仿佛与人更亲近。", "appreciation": "「客愁新」三字是诗眼，却写得毫无愁相。野旷天低，是愁的空阔；江清月近，是愁的一点慰藉——天愈远，月愈近，孤独便有了着落。一句写尽羁旅，而不着一个苦字，这正是孟浩然「语淡味终不薄」的本色。", "mood": "思乡", "famousLine": "野旷天低树，江清月近人", "poetName": "孟浩然"}, {"id": 32, "title": "望洞庭湖赠张丞相", "subtitle": "", "poetId": 10, "dynasty": "唐", "genre": "五言律诗", "paragraphs": "八月湖水平，涵虚混太清。\n气蒸云梦泽，波撼岳阳城。\n欲济无舟楫，端居耻圣明。\n坐观垂钓者，徒有羡鱼情。", "annotation": "涵虚：水气与天空浑然一体。太清：天空。云梦泽：古代的大湖泽，涵盖今两湖之地。济：渡。端居：平居闲处。羡鱼情：用「临渊羡鱼，不如退而结网」之意。", "translation": "八月洞庭湖水暴涨几与岸平，水天一色交相辉映迷离难辨。云梦二泽水气蒸腾白白茫茫，波涛汹涌似乎把岳阳城撼动。想要渡水却没有船只，闲居不仕有愧于圣明天子。坐看垂钓之人多么悠闲，只能白白羡慕他人得鱼成功。", "appreciation": "一首干谒诗，却是千古写洞庭的第一等笔墨。「气蒸云梦泽，波撼岳阳城」十个字，把一座湖写出了宇宙的动静。后半自陈「欲济无舟楫」，求荐举而气不卑——先给你看海一样的湖，再说我的舟楫，气派先赢了。", "mood": "山水", "famousLine": "气蒸云梦泽，波撼岳阳城", "poetName": "孟浩然"}, {"id": 33, "title": "出塞", "subtitle": "其一", "poetId": 11, "dynasty": "唐", "genre": "七言绝句", "paragraphs": "秦时明月汉时关，\n万里长征人未还。\n但使龙城飞将在，\n不教胡马度阴山。", "annotation": "但使：只要。龙城飞将：合用卫青奇袭龙城、李广善战之典，指英勇善战的名将。阴山：横亘今内蒙古，古代中原北境屏障。", "translation": "依旧是秦汉时期的明月和边关，守边御敌的将士们还没有回来。倘若龙城的飞将军李广如今还在，绝不让匈奴的兵马南下越过阴山。", "appreciation": "起句以「秦」「汉」二字把时间拉开千年——明月还是那轮明月，边关还是那道边关，而人未还。这种时空的苍茫，让后两句的呼吁成了千古一问：什么样的将军，才配得上这些等不到归期的士兵？所谓压卷之作，压在「人未还」三个字上。", "mood": "家国", "famousLine": "但使龙城飞将在，不教胡马度阴山", "poetName": "王昌龄"}, {"id": 34, "title": "芙蓉楼送辛渐", "subtitle": "", "poetId": 11, "dynasty": "唐", "genre": "七言绝句", "paragraphs": "寒雨连江夜入吴，\n平明送客楚山孤。\n洛阳亲友如相问，\n一片冰心在玉壶。", "annotation": "平明：天刚亮。楚山：润州一带的山。冰心：像冰一样晶莹纯洁的心。玉壶：洁白的玉壶，喻高洁。", "translation": "冷雨连夜洒遍吴地江天，清晨送走你后，独自面对楚山离愁无限。到了洛阳，如果洛阳亲友问起我来，就请转告他们：我的心依然像玉壶里的冰那样晶莹纯洁。", "appreciation": "送别诗写到「孤」字便已动人，他偏要在孤山之外立起一件东西——玉壶冰心。被贬之人对亲友的交代，不是委屈也不是牢骚，而是一句品格的自证：你们问我近况，就说我没变。遭际愈狼狈，这一句愈清亮。", "mood": "送别", "famousLine": "洛阳亲友如相问，一片冰心在玉壶", "poetName": "王昌龄"}, {"id": 35, "title": "从军行", "subtitle": "其四", "poetId": 11, "dynasty": "唐", "genre": "七言绝句", "paragraphs": "青海长云暗雪山，\n孤城遥望玉门关。\n黄沙百战穿金甲，\n不破楼兰终不还。", "annotation": "青海：青海湖。穿：磨穿，磨破。楼兰：西域古国，此代指侵扰西北的敌人。", "translation": "青海湖上乌云密布，连绵雪山一片黯淡。边塞古城，玉门雄关，远隔千里，遥遥相望。守边将士身经百战，铠甲都被磨穿，壮志不灭，不打败进犯之敌，誓不返回家乡。", "appreciation": "前两句把边关的苦寒与辽阔推到极致——暗、孤、遥，全是消极的意象；后两句却从这灰暗里拔地而起：金甲磨穿，人不还。终不还三字不是说狠话，是把「回不去」的宿命翻转为「不回去」的意志。盛唐的气象，全在这口气里。", "mood": "壮志", "famousLine": "黄沙百战穿金甲，不破楼兰终不还", "poetName": "王昌龄"}, {"id": 36, "title": "采莲曲", "subtitle": "其二", "poetId": 11, "dynasty": "唐", "genre": "七言绝句", "paragraphs": "荷叶罗裙一色裁，\n芙蓉向脸两边开。\n乱入池中看不见，\n闻歌始觉有人来。", "annotation": "罗裙：丝罗织成的裙子。芙蓉：荷花。", "translation": "采莲少女的绿罗裙融入到田田荷叶中，仿佛一色，分不出彼此；少女的脸庞掩映在盛开的荷花间，相互照映。混入莲池中不见了踪影，听到歌声四起才觉察到有人前来。", "appreciation": "把人写没了，才见笔力。罗裙与荷叶一色，人面与荷花互映，少女整个融入了荷池——直到歌声响起，才恍然「有人」。不见时最美，一「觉」字唤醒全诗。这是唐诗里最干净的一场捉迷藏。", "mood": "闲适", "famousLine": "乱入池中看不见，闻歌始觉有人来", "poetName": "王昌龄"}, {"id": 37, "title": "锦瑟", "subtitle": "", "poetId": 12, "dynasty": "唐", "genre": "七言律诗", "paragraphs": "锦瑟无端五十弦，\n一弦一柱思华年。\n庄生晓梦迷蝴蝶，\n望帝春心托杜鹃。\n沧海月明珠有泪，\n蓝田日暖玉生烟。\n此情可待成追忆，\n只是当时已惘然。", "annotation": "无端：无缘由。五十弦：传说古瑟本五十弦。华年：美好的年华。庄生句：用庄周梦蝶典。望帝句：传说蜀王杜宇死后魂化杜鹃，啼声悲切。珠有泪：传说南海鲛人泣泪成珠。蓝田：产玉之山。", "translation": "瑟本有二十五根弦，但即使这样它的每一弦、每一音都足以表达我对那美好年华的思念。庄周其实知道自己只是向往那自由自在的蝴蝶；望帝那美好的心灵和作为可以感动杜鹃。大海里明月的影子是一颗颗眼泪化成的珍珠；蓝田山上阳光和暖，孕育美玉的烟霭依稀可见。那些美好的事和年代，只能留在回忆之中了；而当时那些人对待那些事的态度，我竟然已觉得惘然。", "appreciation": "一首人人爱却无人能解的诗。四个典故各自成谜，又如梦似幻地连成一气：梦、托、泪、烟，全是抓不住的东西。妙就妙在不必解——锦瑟三十弦也好五十弦也好，弹的就是「当时已惘然」五个字：身在福中时的迷惘，比追忆时的怅恨更无可奈何。", "mood": "怀人", "famousLine": "此情可待成追忆，只是当时已惘然", "poetName": "李商隐"}, {"id": 38, "title": "夜雨寄北", "subtitle": "", "poetId": 12, "dynasty": "唐", "genre": "七言绝句", "paragraphs": "君问归期未有期，\n巴山夜雨涨秋池。\n何当共剪西窗烛，\n却话巴山夜雨时。", "annotation": "巴山：指大巴山，此泛指巴蜀之地。涨秋池：秋雨使池水上涨。何当：何时将要。剪烛：剪去烛花使烛更亮。", "translation": "你问我什么时候回去，我还没有确定的日子。此刻巴山的夜雨淅淅沥沥，涨满了秋天的池子。什么时候我们才能一起在西窗下剪烛夜谈，再回头说起今晚巴山夜雨中的思念呢？", "appreciation": "四句诗，两个「巴山夜雨」，两度时空对折：此刻的雨是孤独，他日烛下重说的雨，却是两人相视一笑的谈资。把眼前之苦预支为未来的甜，是深情者才有的自我安慰。可惜写此诗时王氏或已病故——这首寄北的诗，再也没有回信了。", "mood": "怀人", "famousLine": "何当共剪西窗烛，却话巴山夜雨时", "poetName": "李商隐"}, {"id": 39, "title": "无题", "subtitle": "相见时难", "poetId": 12, "dynasty": "唐", "genre": "七言律诗", "paragraphs": "相见时难别亦难，\n东风无力百花残。\n春蚕到死丝方尽，\n蜡炬成灰泪始干。\n晓镜但愁云鬓改，\n夜吟应觉月光寒。\n蓬山此去无多路，\n青鸟殷勤为探看。", "annotation": "丝：与「思」谐音双关。泪：烛泪，亦双关人之泪。晓镜：早晨照镜。云鬓：如云的鬓发。蓬山：蓬莱仙山，喻所思之人居处遥远。青鸟：神话中西王母的信使。", "translation": "见面的机会真是难得，分别时更是难舍难分，况且又兼东风将收的暮春天气，百花残谢，更加使人伤感。春蚕结茧到死时丝才吐完，蜡烛要燃尽成灰时像泪一样的蜡油才能滴干。女子早晨妆扮照镜，只担忧丰盛如云的鬓发改变颜色、青春的容颜消失；男子晚上长吟不寐，必然感到冷月侵人。对方的住处就在不远的蓬莱山，却无路可通，可望而不可及。希望有青鸟一样的使者殷勤地为我去探看亲人，来往传递消息。", "appreciation": "「别亦难」的第二个「难」，是难分难舍的难——首句十四个字便把两难写尽。颔联以春蚕、蜡炬作比，把自己的思念写到以生命为燃料的程度，遂成千古情语之绝唱。尾联忽然退一步求青鸟传信：明知无路，仍存一线想望。绝望处深情不灭，是义山与旁人的分别。", "mood": "怀人", "famousLine": "春蚕到死丝方尽，蜡炬成灰泪始干", "poetName": "李商隐"}, {"id": 40, "title": "登乐游原", "subtitle": "", "poetId": 12, "dynasty": "唐", "genre": "五言绝句", "paragraphs": "向晚意不适，\n驱车登古原。\n夕阳无限好，\n只是近黄昏。", "annotation": "向晚：傍晚。意不适：心情不舒畅。古原：乐游原，汉宣帝所立，地势高敞，为长安登览胜地。", "translation": "傍晚时心情不快，驾着车登上古原。夕阳啊无限美好，只不过接近黄昏。", "appreciation": "二十个字，一声长叹。为解「意不适」而登原，得到的却是更深的怅惘——夕阳越好，越照见无力挽回。关于「只是」二字历来有两解：惋惜「怎奈」，或转折「只因」；无论何解，那个把最美与将逝并置的瞬间，成了晚唐国运与诗人晚景共同的隐喻。", "mood": "悲秋", "famousLine": "夕阳无限好，只是近黄昏", "poetName": "李商隐"}, {"id": 41, "title": "山行", "subtitle": "", "poetId": 13, "dynasty": "唐", "genre": "七言绝句", "paragraphs": "远上寒山石径斜，\n白云生处有人家。\n停车坐爱枫林晚，\n霜叶红于二月花。", "annotation": "石径：石头小路。坐：因为。霜叶：经霜的枫叶。", "translation": "沿着弯弯曲曲的小路上山，在那白云升起的地方，居然还有人家。停下车来，是因为喜爱这深秋枫林晚景。枫叶秋霜染过，艳比二月春花。", "appreciation": "深秋本该是萧瑟的题目，他却停了车。一个「爱」字翻案：经霜的枫叶红过二月春花——秋不是春的残余，是比春更烈的燃烧。杜牧的俊爽之气，连写景都带着这股昂首挺胸。", "mood": "山水", "famousLine": "停车坐爱枫林晚，霜叶红于二月花", "poetName": "杜牧"}, {"id": 42, "title": "清明", "subtitle": "", "poetId": 13, "dynasty": "唐", "genre": "七言绝句", "paragraphs": "清明时节雨纷纷，\n路上行人欲断魂。\n借问酒家何处有？\n牧童遥指杏花村。", "annotation": "欲断魂：形容伤感极深，好像灵魂要与身体分开。借问：请问。杏花村：杏花深处的村庄。", "translation": "江南清明时节细雨纷纷飘洒，路上羁旅行人个个落魄断魂。借问当地之人何处买酒消愁？牧童笑而不答，遥指杏花深处的村庄。", "appreciation": "雨纷纷、欲断魂，愁绪已经写满，末句却忽然一笔荡开——牧童一指，画面里出现了杏花。愁没有解决，但酒有了方向，诗有了远方。全诗无一字说杏花之美，而千年读者都循着那个手指望去。这也是一问一答最古老的回答艺术。", "mood": "思乡", "famousLine": "借问酒家何处有？牧童遥指杏花村", "poetName": "杜牧"}, {"id": 43, "title": "泊秦淮", "subtitle": "", "poetId": 13, "dynasty": "唐", "genre": "七言绝句", "paragraphs": "烟笼寒水月笼沙，\n夜泊秦淮近酒家。\n商女不知亡国恨，\n隔江犹唱后庭花。", "annotation": "笼：笼罩。秦淮：河名，流经金陵，两岸酒家繁华。商女：以卖唱为业的歌女。后庭花：陈后主所作《玉树后庭花》，后世视为亡国之音。", "translation": "浩渺寒江之上弥漫着迷蒙的烟雾，皓月的清辉洒在白色沙渚之上。入夜时分，我将小船停在秦淮河岸，临近酒家的地方。金陵歌女似乎不知何为亡国之恨、黍离之悲，竟依然在对岸吟唱着淫靡之曲《玉树后庭花》。", "appreciation": "两个「笼」字把烟、水、月、沙揉成一片朦胧，就在这片迷离里，歌声飘来。「不知」二字最重：商女何辜？唱的是听曲的人。晚唐的病不是歌女唱亡国之音，而是满座听客已经不会脸红。杜牧知兵而论政，四句绝句是一纸病危通知。", "mood": "家国", "famousLine": "商女不知亡国恨，隔江犹唱后庭花", "poetName": "杜牧"}, {"id": 44, "title": "赤壁", "subtitle": "", "poetId": 13, "dynasty": "唐", "genre": "七言绝句", "paragraphs": "折戟沉沙铁未销，\n自将磨洗认前朝。\n东风不与周郎便，\n铜雀春深锁二乔。", "annotation": "折戟：折断的戟。销：销蚀。将：拿起。周郎：周瑜。铜雀：铜雀台，曹操所建。二乔：大乔、小乔，分嫁孙策、周瑜。", "translation": "一支折断了的铁戟沉没在水底沙中还没有销蚀掉，经过自己又磨又洗，发现这是当年赤壁之战的遗留之物。假如东风不给周瑜以方便，结局恐怕是曹操取胜，二乔被关进铜雀台了。", "appreciation": "从沙里一支断戟起兴，把一场决定百年国运的大战，缩进「铜雀春深锁二乔」的假设里。以两位女子的命运代言江山的易主，举重若轻，是绝句中最高级的写法。他其实在说自己的怀才不遇：东风不与杜郎便。", "mood": "哲理", "famousLine": "东风不与周郎便，铜雀春深锁二乔", "poetName": "杜牧"}, {"id": 45, "title": "雨霖铃", "subtitle": "寒蝉凄切", "poetId": 14, "dynasty": "宋", "genre": "词", "paragraphs": "寒蝉凄切，对长亭晚，骤雨初歇。\n都门帐饮无绪，留恋处，兰舟催发。\n执手相看泪眼，竟无语凝噎。\n念去去，千里烟波，暮霭沉沉楚天阔。\n\n多情自古伤离别，更那堪，冷落清秋节！\n今宵酒醒何处？杨柳岸，晓风残月。\n此去经年，应是良辰好景虚设。\n便纵有千种风情，更与何人说？", "annotation": "长亭：古人送别之处。都门：京城门外。兰舟：船的美称。凝噎：喉咙哽塞说不出话。楚天：南方天空。经年：年复一年。风情：深情密意。", "translation": "秋后的知了叫得那样凄凉，面对着长亭，正是傍晚时分，一阵急雨刚停。在京都城外设帐饯别，却没有畅饮的心绪，正在依依不舍之时，船上的人已催着出发。握着手互相瞧着，满眼泪花，直到最后也无言相对，千言万语都噎在喉间说不出来。想到这回去南方，这一程又一程，千里烟波，雾霭沉沉，楚地的天空竟是一望无际的辽阔。自古以来多情的人最伤离别，更何况，又逢这冷落萧瑟的秋季！这离愁哪能经受得了！谁知我今夜酒醒时身在何处？怕是只有杨柳岸边，面对凄厉的晨风和黎明的残月了。这一去长年相别，相爱的人不在一起，我料想即使遇到好天气、好风景，也如同虚设。即使有满腹的情意，又能同谁一同诉说呢？", "appreciation": "离别词的巅峰。上片写别时之难——「执手相看泪眼」定格了千年的送别；下片忽然宕开，替未来想象：今宵酒醒，杨柳岸晓风残月。最痛的不是离别那一刻，而是想到离别之后的无数个时刻。词到柳永手中，第一次有了电影般的时空调度。", "mood": "送别", "famousLine": "今宵酒醒何处？杨柳岸，晓风残月", "poetName": "柳永"}, {"id": 46, "title": "望海潮", "subtitle": "东南形胜", "poetId": 14, "dynasty": "宋", "genre": "词", "paragraphs": "东南形胜，三吴都会，钱塘自古繁华。\n烟柳画桥，风帘翠幕，参差十万人家。\n云树绕堤沙，怒涛卷霜雪，天堑无涯。\n市列珠玑，户盈罗绮，竞豪奢。\n\n重湖叠巘清嘉，有三秋桂子，十里荷花。\n羌管弄晴，菱歌泛夜，嬉嬉钓叟莲娃。\n千骑拥高牙，乘醉听箫鼓，吟赏烟霞。\n异日图将好景，归去凤池夸。", "annotation": "形胜：地理形势重要优越之处。三吴：泛指江南吴地。天堑：天然壕沟，指钱塘江。重湖：西湖以白堤分为里湖外湖。叠巘：重叠的山峰。高牙：高扬的牙旗，指大官仪仗。凤池：凤凰池，代指中书省。", "translation": "地处东南，地理位置优越，是三吴的都会，钱塘从古以来就十分繁华。如烟的柳树、彩绘的桥梁，挡风的帘子、翠绿的帐幕，楼阁高高低低，大约有十万户人家。高耸入云的大树环绕着沙堤，汹涌的浪涛卷起如霜雪般的白浪，钱塘江是天堑一望无涯。市场上陈列着珠玉珍宝，家家户户都满是绫罗绸缎，竞相奢华。里湖、外湖与重重叠叠的山岭清秀美好，有秋天的桂子，十里的荷花。晴天欢奏羌笛，夜晚采菱唱歌，钓鱼的老翁、采莲的姑娘都嬉笑颜开。千名骑兵簇拥着长官乘醉听吹箫击鼓，观赏吟咏云霞烟景。他日把这美好的景致画出来，回京升官时向人们夸耀。", "appreciation": "一首写给杭州的「城市宣传诗」，却写出了一座城的一生：上有怒涛天堑，下有三秋桂子。据说金主完颜亮读到「三秋桂子，十里荷花」，遂起投鞭渡江之志——一篇词章引发一场战争虽属传说，却道尽这四十六字的诱惑力。市井、湖山、笙歌、千骑，北宋的盛世自信，全在柳永的慢词里。", "mood": "山水", "famousLine": "三秋桂子，十里荷花", "poetName": "柳永"}, {"id": 47, "title": "蝶恋花", "subtitle": "伫倚危楼风细细", "poetId": 14, "dynasty": "宋", "genre": "词", "paragraphs": "伫倚危楼风细细，\n望极春愁，\n黯黯生天际。\n草色烟光残照里，\n无言谁会凭阑意。\n\n拟把疏狂图一醉，\n对酒当歌，\n强乐还无味。\n衣带渐宽终不悔，\n为伊消得人憔悴。", "annotation": "伫倚：久倚。危楼：高楼。黯黯：心情沮丧。会：理解。拟把：打算。疏狂：狂放不羁。伊：她。", "translation": "久久地倚靠着高楼的栏杆，微风丝丝细细，极目远望，春愁从天边黯然升起。青青草色、迷蒙烟光在夕阳残照里，默默无言，又有谁能理解凭栏的心意？打算借放浪形骸来求得一醉，对着美酒纵情高歌，强颜欢笑终究没有滋味。衣带渐宽也始终不后悔，为了她值得我形容憔悴。", "appreciation": "词牌是蝶恋花，写的却是「无言谁会凭阑意」的孤独。结拍突然从满纸黯淡里迸出一句决绝的誓言——衣带渐宽终不悔。王国维借它喻治学成大事业、大学问的第二境界：为所爱者，瘦损何妨。一句情语能升华成人生境界，因为它写的本就不是情，是痴。", "mood": "怀人", "famousLine": "衣带渐宽终不悔，为伊消得人憔悴", "poetName": "柳永"}, {"id": 48, "title": "八声甘州", "subtitle": "对潇潇暮雨洒江天", "poetId": 14, "dynasty": "宋", "genre": "词", "paragraphs": "对潇潇暮雨洒江天，一番洗清秋。\n渐霜风凄紧，关河冷落，残照当楼。\n是处红衰翠减，苒苒物华休。\n惟有长江水，无语东流。\n\n不忍登高临远，望故乡渺邈，归思难收。\n叹年来踪迹，何事苦淹留。\n想佳人妆楼颙望，误几回、天际识归舟。\n争知我，倚阑干处，正恁凝愁！", "annotation": "潇潇：雨势急骤。关河：山河关隘。是处：到处。苒苒：渐渐。颙望：抬头凝望。争知：怎知。恁：如此。", "translation": "面对着潇潇暮雨从天上洒落江天，经过一番洗刷，秋色分外清朗。渐渐感到凄清的霜风一阵紧似一阵，山川关河一片冷落，夕阳余晖斜照楼头。到处是花残叶凋，美好的景物渐渐地衰竭。只有长江之水，无声无息地向东流淌。不忍心登高远望，故乡遥远渺茫，归乡的心思难以收拢。叹息这些年的行踪，为什么苦苦地长久滞留？想象佳人也正在妆楼上抬头远望，多少次错把远处驶来的船当作心上人的归舟。她哪知道我这里，倚着栏杆，也正是这样愁绪凝结！", "appreciation": "苏轼激赏「霜风凄紧，关河冷落，残照当楼」，说此语「不减唐人高处」。妙在结拍的双向想象：我望故乡而思佳人，佳人妆楼误识归舟——她不知道我，我也不知道她错认了几回船。两地相思隔着一道天际互相打听，词的空间从此有了纵深。", "mood": "思乡", "famousLine": "望故乡渺邈，归思难收", "poetName": "柳永"}, {"id": 49, "title": "生查子", "subtitle": "元夕", "poetId": 15, "dynasty": "宋", "genre": "词", "paragraphs": "去年元夜时，花市灯如昼。\n月上柳梢头，人约黄昏后。\n\n今年元夜时，月与灯依旧。\n不见去年人，泪湿春衫袖。", "annotation": "元夜：元宵节之夜。花市：灯市。春衫：年轻人所穿衣衫。", "translation": "去年正月十五元宵节，花市灯光亮如白昼。明月升上柳树梢头，恋人相约黄昏之后。今年正月十五元宵节，月光与灯光依旧。却见不到去年的那人，相思的泪水打湿了春衫袖子。", "appreciation": "两段几乎相同的句子，只换了八个字，就把一场爱情从巅峰写到终点。「月与灯依旧」五字最狠：景物全在，独缺一人。词的真假尚有争论（一说朱淑真作），但「月上柳梢头」这六个字，已经替所有中国人规定了元宵节的浪漫。", "mood": "怀人", "famousLine": "月上柳梢头，人约黄昏后", "poetName": "欧阳修"}, {"id": 50, "title": "采桑子", "subtitle": "轻舟短棹西湖好", "poetId": 15, "dynasty": "宋", "genre": "词", "paragraphs": "轻舟短棹西湖好，\n绿水逶迤，\n芳草长堤，\n隐隐笙歌处处随。\n\n无风水面琉璃滑，\n不觉船移，\n微动涟漪，\n惊起沙禽掠岸飞。", "annotation": "短棹：小桨。西湖：指颍州西湖。逶迤：曲折绵延。琉璃：形容水面光滑如玻璃。沙禽：沙洲上的水鸟。", "translation": "轻便的小船划着短桨，颍州西湖风光真好。碧绿的湖水蜿蜒流淌，长堤上芳草青青，隐约传来笙歌，处处相随。无风的水面光滑如琉璃，感觉不到船在移动，只见微微荡起的涟漪，惊起水鸟掠过湖岸飞去。", "appreciation": "退休老人的西湖春游，写得像少年人的初遇。全词最静也最动：「不觉船移」是静，涟漪惊禽是动——一动只为了照见静。没有一句感慨，没有一个典故，六十一岁的六一居士把词写回了天赋本身。", "mood": "闲适", "famousLine": "无风水面琉璃滑，不觉船移", "poetName": "欧阳修"}, {"id": 51, "title": "蝶恋花", "subtitle": "庭院深深深几许", "poetId": 15, "dynasty": "宋", "genre": "词", "paragraphs": "庭院深深深几许，\n杨柳堆烟，\n帘幕无重数。\n玉勒雕鞍游冶处，\n楼高不见章台路。\n\n雨横风狂三月暮，\n门掩黄昏，\n无计留春住。\n泪眼问花花不语，\n乱红飞过秋千去。", "annotation": "几许：多少。堆烟：杨柳浓密如烟雾笼罩。玉勒雕鞍：镶玉的马笼头、雕花的马鞍，代指华贵的车马。章台：汉代长安街名，代指歌楼妓馆。雨横：雨势猛烈。乱红：落花。", "translation": "庭院深深，不知道到底有多深？杨柳如烟，密密层层，帘幕不计其数。如今丈夫乘着华贵的车马到歌楼妓馆游冶去了，我登上高楼也望不见他去的章台路。暮春三月，风雨交加；掩起黄昏中的门，也无法把春天留住。含泪询问落花，落花默默无言，纷纷乱乱地飞过秋千而去。", "appreciation": "「深」字三叠，一开场就设下迷阵——深几许？问了无人答，只有帘幕无重数。到结拍才见真章：泪眼问花，花不语，反而乱红飞过秋千去。问花本是痴，花的沉默与飞走是双倍的残忍。李清照酷爱此词，「爱其语新意深」，把它化进了自己的「庭院深深」式审美。", "mood": "怀人", "famousLine": "泪眼问花花不语，乱红飞过秋千去", "poetName": "欧阳修"}, {"id": 52, "title": "戏答元珍", "subtitle": "", "poetId": 15, "dynasty": "宋", "genre": "七言律诗", "paragraphs": "春风疑不到天涯，\n二月山城未见花。\n残雪压枝犹有橘，\n冻雷惊笋欲抽芽。\n夜闻归雁生乡思，\n病入新年感物华。\n曾是洛阳花下客，\n野芳虽晚不须嗟。", "annotation": "元珍：丁宝臣，字元珍，时任峡州判官。天涯：极远之地，指夷陵。山城：指夷陵。冻雷：早春的雷。物华：美好的景物。嗟：叹息。", "translation": "我怀疑春风吹不到这边远的山城，已是二月，居然还看不到一朵花。残雪压着枝条，树杈上尚留着去年的橘子；早春的雷声惊动竹笋，想要抽出新芽。夜晚听到归雁的啼声，思念起遥远的家乡；带着病进入新年，面对眼前景物感慨万千。我曾在洛阳的名花丛中做客，这山野的花虽然开得晚，也不必叹息。", "appreciation": "贬谪诗最容易写成苦情戏，他偏在颔联埋下生趣：残雪之下犹有橘，冻雷声中笋欲芽——被压着的东西都在准备生长。尾联以「洛阳花下客」自傲：见过牡丹盛世的人，等得起野花晚开。欧阳修的旷达不是天性，是从这首诗开始练出来的。", "mood": "悲秋", "famousLine": "曾是洛阳花下客，野芳虽晚不须嗟", "poetName": "欧阳修"}, {"id": 53, "title": "泊船瓜洲", "subtitle": "", "poetId": 16, "dynasty": "宋", "genre": "七言绝句", "paragraphs": "京口瓜洲一水间，\n钟山只隔数重山。\n春风又绿江南岸，\n明月何时照我还。", "annotation": "京口：今江苏镇江，与瓜洲隔江相望。一水：指长江。钟山：今南京紫金山。", "translation": "京口和瓜洲之间只隔着一条长江，钟山就隐没在几座山峦的后面。和煦的春风又吹绿了大江南岸，明月什么时候才能照着我回到钟山下的家里？", "appreciation": "「绿」字是炼字史上最著名的公案：洪迈《容斋随笔》记他先后用过「到」「过」「入」「满」，改了十几次才定为「绿」——形容词作动词，春风便有了手。第三句写尽盼归之意，第四句却在问句里悬着：变法中人，归期由不得自己。", "mood": "思乡", "famousLine": "春风又绿江南岸，明月何时照我还", "poetName": "王安石"}, {"id": 54, "title": "梅花", "subtitle": "", "poetId": 16, "dynasty": "宋", "genre": "五言绝句", "paragraphs": "墙角数枝梅，\n凌寒独自开。\n遥知不是雪，\n为有暗香来。", "annotation": "凌寒：冒着严寒。遥：远远地。为：因为。暗香：幽幽的香气。", "translation": "墙角有几枝梅花，正冒着严寒独自盛开。远远地就知道洁白的梅花不是雪，因为有一阵阵幽香隐隐飘来。", "appreciation": "写在变法失败、两度罢相之后，二十个字全是自况：墙角是冷落的处境，凌寒是逆境，独自开是不改其志。末二句最妙——远远望去像雪，正因不是雪（有暗香），才值得辨认真假。世上有的是雪一样白的从众，只有香气证明你是梅。", "mood": "哲理", "famousLine": "遥知不是雪，为有暗香来", "poetName": "王安石"}, {"id": 55, "title": "登飞来峰", "subtitle": "", "poetId": 16, "dynasty": "宋", "genre": "七言绝句", "paragraphs": "飞来山上千寻塔，\n闻说鸡鸣见日升。\n不畏浮云遮望眼，\n自缘身在最高层。", "annotation": "飞来峰：在越州（今绍兴）宝林山。千寻：极言其高，八尺为寻。闻说：听说。浮云：浮云蔽日喻奸邪障蔽贤良。自缘：自然因为。", "translation": "登上飞来峰顶高耸入云的塔，听说鸡鸣时分就可以看到旭日东升。不怕浮云会遮住我的视线，只因为如今我身在最高层。", "appreciation": "三十岁的王安石途经越州写下此诗，正涉世未深，却已有了俯视浮云的气概。与王之涣「更上一层楼」、苏轼「不识庐山真面目」并读最有趣：三人都在解同一道题——位置决定眼界。他的答案是进取型的：只要站得够高，浮云算什么。", "mood": "哲理", "famousLine": "不畏浮云遮望眼，自缘身在最高层", "poetName": "王安石"}, {"id": 56, "title": "元日", "subtitle": "", "poetId": 16, "dynasty": "宋", "genre": "七言绝句", "paragraphs": "爆竹声中一岁除，\n春风送暖入屠苏。\n千门万户曈曈日，\n总把新桃换旧符。", "annotation": "屠苏：屠苏酒，元日习俗饮之以避瘟。曈曈：日出光亮的样子。桃符：画有神荼郁垒二神的桃木板，新年悬于门旁以辟邪。", "translation": "阵阵轰鸣的爆竹声中，旧的一年过去了；和暖的春风吹来了新年，人们欢乐地畅饮着屠苏酒。初升的太阳照耀着千家万户，他们都忙着取下旧桃符，换上新桃符。", "appreciation": "写于拜相推行新法的熙宁二年正月——这哪里是写过年，是写他自己迎来的时代。「新桃换旧符」五字，把一场大变法缩进了最寻常的年俗里：除旧布新，本是人间常理。喜庆底下藏着雷霆，是此诗千年后被反复引用的原因。", "mood": "闲适", "famousLine": "千门万户曈曈日，总把新桃换旧符", "poetName": "王安石"}, {"id": 57, "title": "游山西村", "subtitle": "", "poetId": 17, "dynasty": "宋", "genre": "七言律诗", "paragraphs": "莫笑农家腊酒浑，\n丰年留客足鸡豚。\n山重水复疑无路，\n柳暗花明又一村。\n箫鼓追随春社近，\n衣冠简朴古风存。\n从今若许闲乘月，\n拄杖无时夜叩门。", "annotation": "腊酒：腊月酿的酒。豚：小猪，代指猪肉。春社：立春后第五个戊日祭祀土地神以祈丰年。闲乘月：趁着月色闲游。无时：随时。", "translation": "不要笑话农家腊月酿的酒浑浊，丰收之年他们待客的菜肴极为丰盛。山峦重叠水流曲折，正担心无路可走时，柳绿花艳眼前豁然又出现一个山村。吹箫击鼓的队伍渐渐临近，春社祭祀的日子快到了；村民衣冠简朴，古代风气仍然保存。今后如果还能趁大好月色出外闲游，我一定拄着拐杖随时来敲你的家门。", "appreciation": "罢官归乡的第一年，他在农家饭桌上写下了人生最著名的一句哲学：「山重水复疑无路，柳暗花明又一村」。本是山道实景，却从此成为中国人对付绝境的通用解药。尾联的拄杖夜叩门与首句的莫笑相呼应——这顿饭，他打算一直吃下去。", "mood": "田园", "famousLine": "山重水复疑无路，柳暗花明又一村", "poetName": "陆游"}, {"id": 58, "title": "示儿", "subtitle": "", "poetId": 17, "dynasty": "宋", "genre": "七言绝句", "paragraphs": "死去元知万事空，\n但悲不见九州同。\n王师北定中原日，\n家祭无忘告乃翁。", "annotation": "元：本来。九州同：全国统一。王师：朝廷的军队。乃翁：你们的父亲。", "translation": "本来就知道人死去了就什么也没有了，只是为没有亲眼看到祖国的统一而感到悲伤。朝廷的军队收复中原领土的那一天，在家中祭祀祖先的时候，千万不要忘记把这件事情告诉你们的父亲。", "appreciation": "一首绝笔诗，也是一份遗嘱，更是一个八十五岁老人一生的总结案陈词。明知死去万事空，偏偏放不下一件与己无关的事。七百年后王师仍未北定时，后人读此诗无不鼻酸——诗里的等待，成了民族记忆里最长的一次等待。", "mood": "家国", "famousLine": "王师北定中原日，家祭无忘告乃翁", "poetName": "陆游"}, {"id": 59, "title": "十一月四日风雨大作", "subtitle": "其二", "poetId": 17, "dynasty": "宋", "genre": "七言绝句", "paragraphs": "僵卧孤村不自哀，\n尚思为国戍轮台。\n夜阑卧听风吹雨，\n铁马冰河入梦来。", "annotation": "僵卧：直挺挺躺着，形容老病。戍：守卫。轮台：在今新疆，汉代边防重地，代指边关。夜阑：夜深。", "translation": "我直挺挺躺在孤寂荒凉的乡村里，没有为自己的处境而感到悲哀，心中还想着替国家戍守边疆。夜深了，我躺在床上听到那风雨的声音，迷迷糊糊地梦见自己骑着披甲的战马跨过冰封的河流出征北方疆场。", "appreciation": "六十八岁，罢官家居，一场大雨夜。前两句是白描的老病，后两句忽然天马行空——风雨声进了梦，梦成了铁马冰河。现实愈局促，梦境愈辽阔，这一梦替他守住了壮志的最后一寸疆土。孤村与轮台之间，隔的不是山川，是二十年的不被任用。", "mood": "壮志", "famousLine": "夜阑卧听风吹雨，铁马冰河入梦来", "poetName": "陆游"}, {"id": 60, "title": "钗头凤", "subtitle": "红酥手", "poetId": 17, "dynasty": "宋", "genre": "词", "paragraphs": "红酥手，黄縢酒，满城春色宫墙柳。\n东风恶，欢情薄。\n一怀愁绪，几年离索。\n错、错、错。\n\n春如旧，人空瘦，泪痕红浥鲛绡透。\n桃花落，闲池阁。\n山盟虽在，锦书难托。\n莫、莫、莫！", "annotation": "黄縢酒：官酒以黄纸封口。离索：离群索居。浥：湿润。鲛绡：传说鲛人所织薄纱，代指手帕。锦书：书信。", "translation": "你红润酥腻的手里，捧着盛上黄縢酒的杯子。满城荡漾着春天的景色，你却早已像宫墙中的绿柳那般遥不可及。春风多么可恶，把浓郁的欢情吹得那样稀薄。满杯酒像一杯忧愁的情绪，离别这几年的生活十分萧索。遥想当初，错、错、错！美丽的春景依然如旧，只是人却白白相思地消瘦。泪水洗尽脸上的胭脂，又把薄绸的手帕全都湿透。满春的桃花凋落在寂静空旷的池塘楼阁上。永远相爱的誓言还在，可是锦文书信再也难以交付。遥想当初，莫、莫、莫！", "appreciation": "绍兴二十五年春，三十一岁的陆游游沈园，遇已为他人妻的前妻唐琬，题此词于壁。三个「错」字与三个「莫」字，上下阕各六字，是词史上最沉重的十二个字。相传唐琬和词一阕「人成各，今非昨」，不久郁郁而终；陆游此后一生重游沈园，七十五岁犹写「伤心桥下春波绿，曾是惊鸿照影来」。一阕词，用了他一生来注脚。", "mood": "怀人", "famousLine": "山盟虽在，锦书难托", "poetName": "陆游"}, {"id": 61, "title": "关雎", "subtitle": "", "poetId": 18, "dynasty": "先秦", "genre": "四言古诗", "paragraphs": "关关雎鸠，在河之洲。\n窈窕淑女，君子好逑。\n参差荇菜，左右流之。\n窈窕淑女，寤寐求之。\n求之不得，寤寐思服。\n悠哉悠哉，辗转反侧。\n参差荇菜，左右采之。\n窈窕淑女，琴瑟友之。\n参差荇菜，左右芼之。\n窈窕淑女，钟鼓乐之。", "annotation": "关关：水鸟和鸣声。雎鸠：一种水鸟。窈窕：文静美好。好逑：好的配偶。荇菜：水草，可食。流：求取。寤寐：醒着睡着。芼：采摘。", "translation": "关关和鸣的雎鸠，相伴在河中小洲。美丽贤淑的女子，是君子的好配偶。参差不齐的荇菜，在船两边求取。美丽贤淑的女子，日夜都想追求。追求不得，醒着睡着都在思念。绵绵思念啊，让人翻来覆去睡不着。参差不齐的荇菜，左右两边采摘。美丽贤淑的女子，弹琴鼓瑟亲近她。参差不齐的荇菜，左右两边拔取。美丽贤淑的女子，敲钟击鼓让她快乐。", "appreciation": "中国诗歌的第一页，写的是一场失眠。求之不得，辗转反侧——相思的苦写得诚实；而苦到极处，想到的仍是「琴瑟友之」「钟鼓乐之」，以礼相待，以乐相悦。乐而不淫，哀而不伤，孔子的评语说尽了这首诗的温柔敦厚：爱一个人的最好方式，是想让自己配得上她。", "mood": "怀人", "famousLine": "窈窕淑女，君子好逑", "poetName": "诗经"}, {"id": 62, "title": "蒹葭", "subtitle": "", "poetId": 18, "dynasty": "先秦", "genre": "四言古诗", "paragraphs": "蒹葭苍苍，白露为霜。\n所谓伊人，在水一方。\n溯洄从之，道阻且长。\n溯游从之，宛在水中央。\n蒹葭萋萋，白露未晞。\n所谓伊人，在水之湄。\n溯洄从之，道阻且跻。\n溯游从之，宛在水中坻。\n蒹葭采采，白露未已。\n所谓伊人，在水之涘。\n溯洄从之，道阻且右。\n溯游从之，宛在水中沚。", "annotation": "蒹葭：芦苇。苍苍：茂盛的样子。伊人：那个人。溯洄：逆流而上。溯游：顺流而下。湄：水边。跻：升高。坻、沚：水中小洲。", "translation": "河边芦苇苍苍茫茫，清晨的露水凝结成霜。我思念的那个人，就在河水的那一方。逆流而上去追寻，道路险阻而漫长。顺流而下去追寻，她仿佛又在水的中央。芦苇茂密繁盛，露水尚未晒干。我思念的那个人，就在河水的岸边。逆流而上去追寻，道路陡峭难攀。顺流而下去追寻，她仿佛又在水中高地上。", "appreciation": "她永远在水的那一方——逆流、顺流、长路、水中央，追了一整个秋天，只追到雾气里一个模糊的影子。这首诗之美不在人，在「隔」：追求而不可即，怅惘而不绝望。两千年后每个人心里那个「伊人」，都可以在这里找到倒影。", "mood": "怀人", "famousLine": "所谓伊人，在水一方", "poetName": "诗经"}, {"id": 63, "title": "采薇", "subtitle": "", "poetId": 18, "dynasty": "先秦", "genre": "四言古诗", "paragraphs": "采薇采薇，薇亦作止。\n曰归曰归，岁亦莫止。\n靡室靡家，猃狁之故。\n不遑启居，猃狁之故。\n采薇采薇，薇亦柔止。\n曰归曰归，心亦忧止。\n忧心烈烈，载饥载渴。\n我戍未定，靡使归聘。\n采薇采薇，薇亦刚止。\n曰归曰归，岁亦阳止。\n王事靡盬，不遑启处。\n忧心孔疚，我行不来。\n彼尔维何？维常之华。\n彼路斯何？君子之车。\n戎车既驾，四牡业业。\n岂敢定居？一月三捷。\n驾彼四牡，四牡骙骙。\n君子所依，小人所腓。\n四牡翼翼，象弭鱼服。\n岂不日戒？猃狁孔棘。\n昔我往矣，杨柳依依。\n今我来思，雨雪霏霏。\n行道迟迟，载渴载饥。\n我心伤悲，莫知我哀！", "annotation": "薇：野豌豆苗。作：初生。止：语气词。莫：通「暮」。猃狁：北方少数民族。盬：休止。孔疚：非常痛苦。骙骙：马强壮貌。腓：庇护。象弭：象牙装饰的弓梢。雨雪：下雪。「雨」作动词。", "translation": "采薇菜啊采薇菜，薇菜刚刚冒出芽。说回家啊说回家，一年又快过完了。没有妻室没有家，都是因为猃狁的缘故。没有空闲安定住下，都是因为猃狁的缘故。薇菜长得柔嫩，归家的心思愈发忧切。心中忧闷像火烧，又饿又渴实在难熬。驻地一直变动，没法托人捎信回家。薇菜已经长硬，又到了十月小阳春。王室的差事没有尽头，没有片刻可以歇息。心中忧愁积成病，出征的人无人来慰问。那盛开的是什么花？是棠棣之花。那驶过的是什么车？是将帅的战车。战车驾起，四匹雄马强壮威武。哪敢安然驻扎？一个月要打三次仗。驾起四匹公马，将帅乘车、士卒倚车掩蔽。四马训练有素，象牙弓梢、鱼皮箭袋从不离身。哪能不天天戒备？猃狁实在太猖狂。当初离家出征，杨柳依依随风吹。如今归来途中，大雪纷纷漫天飞。道路泥泞缓缓行，又渴又饥真劳累。满心伤感满腔悲，却没有人知道我的哀痛！", "appreciation": "全诗六章，写尽戍卒的一年又一年：薇菜从发芽吃到长老，回家的承诺年年落空。最惊艳的是末章——「昔我往矣，杨柳依依；今我来思，雨雪霏霏」：出征时的春天与归来的大雪对叠，把一生的时光压进十六个字。谢玄称此四句为诗经中最好的句子，此后「杨柳依依」成了汉语里离别的底色。", "mood": "思乡", "famousLine": "昔我往矣，杨柳依依", "poetName": "诗经"}, {"id": 64, "title": "国殇", "subtitle": "", "poetId": 19, "dynasty": "先秦", "genre": "骚体", "paragraphs": "操吴戈兮被犀甲，\n车错毂兮短兵接。\n旌蔽日兮敌若云，\n矢交坠兮士争先。\n凌余阵兮躐余行，\n左骖殪兮右刃伤。\n霾两轮兮絷四马，\n援玉桴兮击鸣鼓。\n天时怼兮威灵怒，\n严杀尽兮弃原野。\n出不入兮往不反，\n平原忽兮路超远。\n带长剑兮挟秦弓，\n首身离兮心不惩。\n诚既勇兮又以武，\n终刚强兮不可凌。\n身既死兮神以灵，\n子魂魄兮为鬼雄！", "annotation": "殇：指死于国事者。吴戈：吴国铸造的戈，最锋利。被：通「披」。犀甲：犀牛皮铠甲。毂：车轮轴心。躐：践踏。殪：死。霾：通「埋」。絷：拴住。怼：怨。惩：悔改。鬼雄：鬼中的英雄。", "translation": "手拿吴戈身披犀甲，战车轮毂交错短兵相接。旌旗遮蔽日月，敌人多如乌云，飞箭交坠，将士们奋勇争先。敌军侵犯我们的阵线，践踏我们的队伍，左边的骖马倒地死去，右边的马被兵刃所伤。车轮埋进土里四马被绊住，帅旗之下，仍挥动玉槌击响战鼓。苍天怨愤，神灵震怒，将士们全部战死，尸骸抛弃在原野。出征时就抱定不归的决心，平原渺茫，离家路途遥远。身佩长剑手挽秦弓，身首分离也不悔恨。确实勇敢又有武艺，始终刚强不可侵犯。身躯虽死，精神不灭，你们的魂魄在鬼中也是英雄！", "appreciation": "这是中国最早的阵亡将士颂歌。别的祭歌唱给神，这一篇唱给「人」：从短兵相接写到战马伏地，从埋轮击鼓写到身首分离——每一句都是战场的实况，没有一点虚饰。末两句陡然升调：身既死兮神以灵，魂魄也为鬼中英雄。屈原以此祭楚国亡卒，千年后我们以此祭所有「捐躯赴国难」的人。", "mood": "家国", "famousLine": "身既死兮神以灵，子魂魄兮为鬼雄", "poetName": "屈原"}, {"id": 65, "title": "大风歌", "subtitle": "", "poetId": 20, "dynasty": "两汉", "genre": "乐府", "paragraphs": "大风起兮云飞扬，\n威加海内兮归故乡，\n安得猛士兮守四方！", "annotation": "海内：四海之内，指天下。安得：怎样才能得到。猛士：勇猛的将士。", "translation": "大风劲吹啊浮云飞扬，我统一了天下啊衣锦还乡，怎样才能得到勇士啊为国家镇守四方！", "appreciation": "只有三句，却是帝王诗里的第一名。第一句是大形势，第二句是大功业，第三句是大忧虑——打了半辈子仗的人，最怕的不是打不赢，而是守不住。刘邦即兴击筑而起舞，泣数行下：胜利者的眼泪里，是创业者的清醒。", "mood": "豪放", "famousLine": "安得猛士兮守四方", "poetName": "刘邦"}, {"id": 66, "title": "垓下歌", "subtitle": "", "poetId": 21, "dynasty": "秦末", "genre": "乐府", "paragraphs": "力拔山兮气盖世，\n时不利兮骓不逝。\n骓不逝兮可奈何，\n虞兮虞兮奈若何！", "annotation": "骓：毛色青白相间的马，项羽的坐骑。不逝：不能前进。奈若何：把你怎么办。", "translation": "力量可以拔起大山，豪气世上无人能比。可时局对我不利啊，乌骓马也跑不起来了。乌骓马跑不起来，我能怎么办？虞姬啊虞姬，我又该把你怎么办！", "appreciation": "四面楚歌之夜，西楚霸王开口的第一句仍是「力拔山兮气盖世」——至死不肯示弱；可紧接着的，却是对着美人和马匹的无可奈何。英雄的绝命词，不是悲愤，是不舍。这四句与刘邦的《大风歌》并读：一个得天下仍在忧，一个失天下仍在爱。", "mood": "悲秋", "famousLine": "力拔山兮气盖世", "poetName": "项羽"}, {"id": 67, "title": "江南", "subtitle": "", "poetId": 22, "dynasty": "两汉", "genre": "乐府", "paragraphs": "江南可采莲，\n莲叶何田田。\n鱼戏莲叶间。\n鱼戏莲叶东，\n鱼戏莲叶西，\n鱼戏莲叶南，\n鱼戏莲叶北。", "annotation": "田田：莲叶茂盛相连的样子。", "translation": "江南又到了适宜采莲的季节，莲叶浮出水面，挨挨挤挤，重重叠叠。鱼儿在莲叶间嬉戏：一会儿在莲叶的东边嬉戏，一会儿在莲叶的西边嬉戏，一会儿在莲叶的南边嬉戏，一会儿在莲叶的北边嬉戏。", "appreciation": "七个字反复换方位，看似笨拙，实则是一首劳作时的合唱：采莲人东一行西一行，鱼在莲叶间东游西游——劳动与游戏的快乐就藏在这回环往复里。没有一句写情，而丰收的欢快扑面而来。汉乐府的天真，是后世文人再也学不来的。", "mood": "田园", "famousLine": "莲叶何田田", "poetName": "汉乐府"}, {"id": 68, "title": "长歌行", "subtitle": "", "poetId": 22, "dynasty": "两汉", "genre": "乐府", "paragraphs": "青青园中葵，\n朝露待日晞。\n阳春布德泽，\n万物生光辉。\n常恐秋节至，\n焜黄华叶衰。\n百川东到海，\n何时复西归？\n少壮不努力，\n老大徒伤悲。", "annotation": "晞：晒干。布：施予。德泽：恩泽。焜黄：草木枯黄的样子。徒：白白地。", "translation": "园中的葵菜郁郁葱葱，清晨的露珠等待阳光晒干。春天的太阳布下恩泽，万物都焕发光彩。常常担心秋天的到来，花叶枯黄凋零衰败。百条江河奔腾东流入海，什么时候才能向西返回？年轻力壮时不发奋努力，到老来只能是白白地悔恨悲伤。", "appreciation": "从一畦菜写起，写到春天，写到秋天的恐惧，再借百川东流逼出那一句终极追问——然后水到渠成地砸出全诗最后十个字。这首汉代民歌唱了两年年后，每个中国孩子都会背：它讲的是最朴素的物理，时间只往一个方向流。", "mood": "哲理", "famousLine": "少壮不努力，老大徒伤悲", "poetName": "汉乐府"}, {"id": 69, "title": "上邪", "subtitle": "", "poetId": 22, "dynasty": "两汉", "genre": "乐府", "paragraphs": "上邪！\n我欲与君相知，\n长命无绝衰。\n山无陵，\n江水为竭，\n冬雷震震，\n夏雨雪，\n天地合，\n乃敢与君绝！", "annotation": "上邪：天啊！上，指天；邪，语气词。相知：相亲相爱。命：使。陵：山峰。震震：雷声。雨雪：下雪。「雨」作动词。", "translation": "天啊！我要和你相爱，让感情永不衰减。除非高山变平地，江水枯竭，冬天打雷，夏天下雪，天地合为一体，我才敢与你断绝！", "appreciation": "一个女子对天发出的爱情誓言，开口就是「上邪」——先喊天作证。然后一口气排出五件不可能的事当条件：山平、水竭、冬雷、夏雪、天地合。逻辑上是“绝不可能”，情感上是“绝不可能分手”。汉乐府的炽烈，比后世所有含蓄的情诗都烫。", "mood": "怀人", "famousLine": "山无陵，江水为竭，冬雷震震，夏雨雪，天地合，乃敢与君绝", "poetName": "汉乐府"}, {"id": 70, "title": "迢迢牵牛星", "subtitle": "", "poetId": 23, "dynasty": "两汉", "genre": "五言古诗", "paragraphs": "迢迢牵牛星，\n皎皎河汉女。\n纤纤擢素手，\n札札弄机杼。\n终日不成章，\n泣涕零如雨。\n河汉清且浅，\n相去复几许。\n盈盈一水间，\n脉脉不得语。", "annotation": "迢迢：遥远。皎皎：明亮。河汉女：织女星。擢：伸出。札札：织机声。章：布匹的纹理。零：落下。盈盈：水清澈的样子。脉脉：含情相视。", "translation": "遥远的牵牛星，明亮的织女星。织女伸出纤细白皙的手，札札地织着布。一整天也织不出整幅布，眼泪如雨般落下。银河又清又浅，相隔又有多远呢。只隔一条清浅的银河，含情脉脉却不能说话。", "appreciation": "写牛郎织女，通篇却只写织女一个人：她的手、她的机杼、她织不成布的眼泪。「盈盈一水间，脉脉不得语」——银河清浅到可见对面的人，却连一句话也过不去。世上最远的距离，原来古诗十九首里早就写下了。六个叠词连用，如泪珠连串，声情摇曳。", "mood": "怀人", "famousLine": "盈盈一水间，脉脉不得语", "poetName": "古诗十九首"}, {"id": 71, "title": "涉江采芙蓉", "subtitle": "", "poetId": 23, "dynasty": "两汉", "genre": "五言古诗", "paragraphs": "涉江采芙蓉，\n兰泽多芳草。\n采之欲遗谁？\n所思在远道。\n还顾望旧乡，\n长路漫浩浩。\n同心而离居，\n忧伤以终老。", "annotation": "芙蓉：荷花。兰泽：长着兰草的水泽。遗：赠送。还顾：回头看。漫浩浩：路途遥远无边。", "translation": "踏过江水去采荷花，兰草生长的水泽里满是芳草。采了荷花要送给谁呢？心爱的人在遥远的他乡。回头看故乡，长路漫漫无边无际。两心相同却分隔两地，忧伤将伴随终身。", "appreciation": "采一朵荷花送给心上人，多美的动作——下一句却是「所思在远道」，礼物无处安放。全诗的动人处在这一转身的动作里：还顾望旧乡，长路漫浩浩。同心而离居，是世上最普通的痛苦，也是最古老的诗意。", "mood": "怀人", "famousLine": "同心而离居，忧伤以终老", "poetName": "古诗十九首"}, {"id": 72, "title": "七步诗", "subtitle": "", "poetId": 24, "dynasty": "魏晋", "genre": "五言绝句", "paragraphs": "煮豆燃豆萁，\n豆在釜中泣。\n本自同根生，\n相煎何太急？", "annotation": "萁：豆秸。釜：锅。泣：小声哭。煎：煎熬，暗指迫害。", "translation": "锅里煮着豆子，豆秸在锅下燃烧，豆子在锅里哭泣。豆子和豆秸本来是同一条根上生长出来的，豆秸怎能这样急迫地煎熬豆子呢？", "appreciation": "七步之内，把兄弟相残写成了一锅豆子：萁在釜下烧，豆在釜中泣——受害者无告的样子，加害者竟是同一根所生。「相煎何太急」以问收束，不做控诉，而控诉力千钧。传说曹丕听后面有惭色：诗歌的功能里，最锋利的就是这种四两拨千斤。", "mood": "哲理", "famousLine": "本是同根生，相煎何太急", "poetName": "曹植"}, {"id": 73, "title": "木兰诗", "subtitle": "", "poetId": 25, "dynasty": "南北朝", "genre": "乐府", "paragraphs": "唧唧复唧唧，木兰当户织。\n不闻机杼声，唯闻女叹息。\n问女何所思，问女何所忆。\n女亦无所思，女亦无所忆。\n昨夜见军帖，可汗大点兵，\n军书十二卷，卷卷有爷名。\n阿爷无大儿，木兰无长兄，\n愿为市鞍马，从此替爷征。\n\n东市买骏马，西市买鞍鞯，\n南市买辔头，北市买长鞭。\n旦辞爷娘去，暮宿黄河边，\n不闻爷娘唤女声，\n但闻黄河流水鸣溅溅。\n旦辞黄河去，暮至黑山头，\n不闻爷娘唤女声，\n但闻燕山胡骑鸣啾啾。\n\n万里赴戎机，关山度若飞。\n朔气传金柝，寒光照铁衣。\n将军百战死，壮士十年归。\n\n归来见天子，天子坐明堂。\n策勋十二转，赏赐百千强。\n可汗问所欲，木兰不用尚书郎，\n愿驰千里足，送儿还故乡。\n\n爷娘闻女来，出郭相扶将；\n阿姊闻妹来，当户理红妆；\n小弟闻姊来，磨刀霍霍向猪羊。\n开我东阁门，坐我西阁床，\n脱我战时袍，著我旧时裳。\n当窗理云鬓，对镜帖花黄。\n出门看火伴，火伴皆惊忙：\n同行十二年，不知木兰是女郎。\n\n雄兔脚扑朔，雌兔眼迷离；\n双兔傍地走，安能辨我是雄雌？", "annotation": "唧唧：叹息声。军帖：征兵文书。市：买。溅溅：水流声。啾啾：马叫声。戎机：战事。金柝：打更用的器具。策勋：记功。著：穿。帖花黄：贴花黄，当时女子面饰。扑朔：乱蹬。迷离：眯眼。", "translation": "叹息声一声接着一声，木兰对着门在织布。听不到织机的声音，只听到姑娘的叹息。问姑娘你在思念什么，你在回想什么。姑娘我也没有思念什么，昨夜看见征兵文书，可汗大规模征兵，征兵的名册有很多卷，每一卷都有父亲的名字。父亲没有成年的儿子，木兰没有兄长，愿意为此去买来鞍马，从此替父亲出征。到东边集市买来骏马，西边集市买来鞍鞯，南边集市买来辔头，北边集市买来长鞭。早晨告别父母离开，晚上宿营在黄河边，听不到父母呼唤女儿的声音，只能听到黄河水奔流溅溅。早晨离开黄河上路，晚上到达黑山头，听不到父母呼唤女儿的声音，只能听到燕山胡人的战马啾啾嘶鸣。不远万里奔赴战场，翻越重重山峰像飞一样。北方的寒气传送着打更的声音，清冷的月光映照着将士的铠甲。将军和士兵身经百战，有的战死沙场，有的凯旋归来。胜利归来朝见天子，天子坐在殿堂上论功行赏。记很大的功，赏赐很多财物。天子问木兰想要什么，木兰说不愿做尚书郎，希望骑上千里马，送我回到故乡。父母听说女儿回来，互相搀扶着到城外迎接；姐姐听说妹妹回来，对着门户梳妆打扮；弟弟听说姐姐回来，忙着霍霍地磨刀杀猪宰羊。打开闺房东面的门，坐在我西边床榻上，脱下作战的战袍，穿上以前的衣裳，对着窗户梳理云一样的鬓发，照着镜子贴上花黄。出门去看同伍的士兵，伙伴们都很吃惊：同行这么多年，竟然不知道木兰是女子。雄兔两只前脚爬搔，雌兔两只眼睛时常眯着，两只兔子贴着地面跑，怎能分辨出哪只是雄兔哪只是雌兔？", "appreciation": "北朝民歌的巅峰，中国叙事诗的双璧之一。它最有魅力的是节奏：买鞍马用排比铺张，行军用黄河水声写离愁，十年征战只用六句带过——详略之间全是深情。归来那一段最动人：家人的迎接、换回女装的欢喜，「火伴皆惊忙」的喜剧感。结尾以双兔作比，狡黠一笑收束全部传奇。木兰不是被塑造的女英雄，她是民间自己长出来的想象力。", "mood": "家国", "famousLine": "万里赴戎机，关山度若飞", "poetName": "北朝民歌"}, {"id": 74, "title": "登鹳雀楼", "subtitle": "", "poetId": 26, "dynasty": "唐", "genre": "五言绝句", "paragraphs": "白日依山尽，\n黄河入海流。\n欲穷千里目，\n更上一层楼。", "annotation": "鹳雀楼：在今山西永济，三层，前瞻中条山，下临黄河。依：依傍。穷：尽。", "translation": "夕阳依傍着山峦渐渐沉落，黄河朝着大海滔滔奔流。想要看到千里之外的风光，就要再登上更高的一层楼。", "appreciation": "二十个字，前十个是天地，后十个是人心。有人说前两句对仗天成，后两句翻出理趣——「更上一层楼」把写景诗写成了一条人生公式：眼界取决于高度。盛唐气象不在于写多大的景，而在于相信总可以再上一层。", "mood": "哲理", "famousLine": "欲穷千里目，更上一层楼", "poetName": "王之涣"}, {"id": 75, "title": "凉州词", "subtitle": "", "poetId": 26, "dynasty": "唐", "genre": "七言绝句", "paragraphs": "黄河远上白云间，\n一片孤城万仞山。\n羌笛何须怨杨柳，\n春风不度玉门关。", "annotation": "万仞：形容极高。仞，古代七尺或八尺为一仞。羌笛：羌族的笛子。杨柳：指《折杨柳》曲，其音哀怨。玉门关：在今甘肃敦煌西，是通往西域的要道。", "translation": "黄河好像从白云间奔流而来，玉门关孤独地耸峙在高山中。何必用羌笛吹起哀怨的《折杨柳》呢，春风本来就不会吹过玉门关。", "appreciation": "起句把黄河竖着写——「远上白云间」，视角陡然拔高；孤城一座、万仞群山，人在这天地间小成一粒沙。后两句最妙：羌笛何必怨杨柳？不是安慰，是「春风不度玉门关」的苍凉实话。悲而能壮，怨而不怒，故能压卷。", "mood": "豪放", "famousLine": "羌笛何须怨杨柳，春风不度玉门关", "poetName": "王之涣"}, {"id": 76, "title": "咏柳", "subtitle": "", "poetId": 27, "dynasty": "唐", "genre": "七言绝句", "paragraphs": "碧玉妆成一树高，\n万条垂下绿丝绦。\n不知细叶谁裁出，\n二月春风似剪刀。", "annotation": "碧玉：绿色玉片，又暗用「碧玉小家女」典，指年轻女子。绦：丝带。裁：剪裁。", "translation": "高高的柳树长满了翠绿的新叶，轻柔的柳枝垂下来，就像万条轻轻飘动的绿色丝带。这细细的嫩叶是谁的巧手裁剪出来的呢？原来是那二月里温暖的春风，它就像一把灵巧的剪刀。", "appreciation": "把一棵柳树写成一位新妆少女，已是巧思；更妙的是末句——春风原来是剪刀。从「谁裁出」的设问到「似剪刀」的自答，把无形的春风变成了有形的手艺。咏物诗写到这个份上：物有了人形，季节有了动作。", "mood": "山水", "famousLine": "二月春风似剪刀", "poetName": "贺知章"}, {"id": 77, "title": "回乡偶书", "subtitle": "", "poetId": 27, "dynasty": "唐", "genre": "七言绝句", "paragraphs": "少小离家老大回，\n乡音无改鬓毛衰。\n儿童相见不相识，\n笑问客从何处来。", "annotation": "衰：疏落，鬓发稀疏。客：客人。", "translation": "我年少时离开家乡，到迟暮之年才回来。我的乡音虽未改变，鬓角的毛发却已疏落。家乡的儿童们看见我，没有一个认识我。他们笑着询问我：这客人是从哪里来的呀？", "appreciation": "八十六岁的老诗人回乡，被一群孩子当成客人笑着发问——这一问，问出了人生最深的怅惘。前两句是自嘲，后两句是自伤，却都用「笑」字托着：不写悲而悲意漫出纸面。回乡是喜事，做客是漂泊，一个人竟同时占着这两种身份。", "mood": "思乡", "famousLine": "儿童相见不相识，笑问客从何处来", "poetName": "贺知章"}, {"id": 78, "title": "望月怀远", "subtitle": "", "poetId": 28, "dynasty": "唐", "genre": "五言律诗", "paragraphs": "海上生明月，\n天涯共此时。\n情人怨遥夜，\n竟夕起相思。\n灭烛怜光满，\n披衣觉露滋。\n不堪盈手赠，\n还寝梦佳期。", "annotation": "怀远：怀念远方的亲人。情人：有情之人。遥夜：长夜。竟夕：整夜。怜：爱惜。滋：沾湿。盈手：满手。佳期：相会的日子。", "translation": "茫茫的海上升起一轮明月，此时你我都在天涯共相望。有情之人都怨恨月夜漫长，整夜里不眠而把亲人怀想。熄灭蜡烛怜爱这满屋月光，披衣走出门徘徊露水沾湿衣裳。不能把这美好月色捧送给你，还是回去睡觉期望在梦里相见。", "appreciation": "首联十个字，把中国人所有「望月怀人」的想象一网打尽：海上生明月，天涯共此时。之后五联全是细节——吹灭蜡烛、披衣出门、露水沾衣、捧不满手的月光——相思写得越具体，越显辽阔。结尾回到梦里相会，温柔收束，宰相的深情也这般雍容。", "mood": "月夜", "famousLine": "海上生明月，天涯共此时", "poetName": "张九龄"}, {"id": 79, "title": "枫桥夜泊", "subtitle": "", "poetId": 29, "dynasty": "唐", "genre": "七言绝句", "paragraphs": "月落乌啼霜满天，\n江枫渔火对愁眠。\n姑苏城外寒山寺，\n夜半钟声到客船。", "annotation": "霜满天：霜气布满天空，形容夜寒。江枫：江边的枫树。渔火：渔船上的灯火。姑苏：苏州的别称。", "translation": "月亮渐渐落下，乌鸦啼叫，寒霜布满天空。江边枫树与船上渔火，难眠的我与它们相对而愁。姑苏城外的寒山寺，半夜的钟声传到了客船上。", "appreciation": "一个流离乱世的书生泊船城外，把失眠写成了千古名篇。前两句十四个名词性意象密集排开：月落、乌啼、霜、江枫、渔火、愁眠——人在中间，万物皆愁。后两句忽然让钟声进来：夜半的钟声穿水而来，敲在客船上，也敲在一千二百年的读者心上。", "mood": "月夜", "famousLine": "姑苏城外寒山寺，夜半钟声到客船", "poetName": "张继"}, {"id": 80, "title": "渔歌子", "subtitle": "", "poetId": 30, "dynasty": "唐", "genre": "词", "paragraphs": "西塞山前白鹭飞，\n桃花流水鳜鱼肥。\n青箬笠，绿蓑衣，\n斜风细雨不须归。", "annotation": "西塞山：在今浙江湖州。白鹭：水鸟。鳜鱼：淡水鱼，肉味鲜美。箬笠：竹叶编的斗笠。蓑衣：草或棕编的雨衣。不须归：不必回家。", "translation": "西塞山前白鹭在自由地翱翔，桃花盛开，江水猛涨，水中鳜鱼正肥。渔翁头戴青色斗笠，身披绿色蓑衣，冒着斜风细雨，悠然自得地垂钓，用不着回家。", "appreciation": "一首词画出了一幅永远不褪色的江南烟雨图：白鹭、桃花、流水、肥鱼，然后一个青笠绿蓑的钓叟坐进画里。「不须归」三字是词眼——不是雨小，是心里不想归。儒家讲进取，他偏说：斜风细雨里坐着，就是人生最好的位置。这首词东传日本，嵯峨天皇都有仿作。", "mood": "闲适", "famousLine": "桃花流水鳜鱼肥", "poetName": "张志和"}, {"id": 81, "title": "别董大", "subtitle": "其一", "poetId": 31, "dynasty": "唐", "genre": "七言绝句", "paragraphs": "千里黄云白日曛，\n北风吹雁雪纷纷。\n莫愁前路无知己，\n天下谁人不识君。", "annotation": "董大：琴师董庭兰，排行第一。曛：昏暗。知己：了解自己的人。君：指董大。", "translation": "千里黄云遮天蔽日，天气阴沉，北风吹送着大雁，大雪纷飞。不要担心前路茫茫没有知己，天下还有谁不认识你呢？", "appreciation": "送别诗的前半写得越荒凉，后半的安慰就越有力：黄云、白日、吹雁、飞雪——天地间一片寒苦，然后「莫愁前路无知己」横空劈出。更动人的是写信的人自己正落魄潦倒，却把最慷慨的底气给了朋友。盛唐的友情，是有豪气的。", "mood": "送别", "famousLine": "莫愁前路无知己，天下谁人不识君", "poetName": "高适"}, {"id": 82, "title": "白雪歌送武判官归京", "subtitle": "", "poetId": 32, "dynasty": "唐", "genre": "乐府", "paragraphs": "北风卷地白草折，\n胡天八月即飞雪。\n忽如一夜春风来，\n千树万树梨花开。\n散入珠帘湿罗幕，\n狐裘不暖锦衾薄。\n将军角弓不得控，\n都护铁衣冷难着。\n瀚海阑干百丈冰，\n愁云惨淡万里凝。\n中军置酒饮归客，\n胡琴琵琶与羌笛。\n纷纷暮雪下辕门，\n风掣红旗冻不翻。\n轮台东门送君去，\n去时雪满天山路。\n山回路转不见君，\n雪上空留马行处。", "annotation": "白草：西域的一种牧草，秋干变白。胡天：西域的天气。锦衾：锦缎被子。控：拉开。都护：镇守边镇的长官。瀚海：大沙漠。阑干：纵横。中军：主帅营帐。掣：拉动。轮台：地名，在今新疆。", "translation": "北风席卷大地把白草吹折，胡地八月就纷扬落雪。忽然好像一夜春风来，千树万树梨花开。雪花散入珠帘打湿罗幕，狐裘穿不暖，锦被也嫌单薄。将军的角弓冻得拉不开，都护的铁甲冷得难以穿上。沙漠结满百丈坚冰，愁云惨淡在万里长空凝聚。主帅帐中摆酒为归客饯行，胡琴琵琶与羌笛合奏。傍晚辕门前大雪落个不停，红旗冻僵了风也牵引不动。在轮台东门送你离去，那时大雪铺满天山路。山路曲折已看不见你的身影，雪上只留下一行马蹄印。", "appreciation": "咏雪第一名句「忽如一夜春风来，千树万树梨花开」：把苦寒写成花开，只有真正热爱边疆生活的人才会这样看。全诗在奇寒与热情之间来回——铁衣冷难着，帐中酒正热；红旗冻不翻，笛声正悠扬。结尾不入楼而入雪：雪上空留马行处，送别的目光在雪地里追了一程又一程。", "mood": "送别", "famousLine": "忽如一夜春风来，千树万树梨花开", "poetName": "岑参"}, {"id": 83, "title": "游子吟", "subtitle": "", "poetId": 33, "dynasty": "唐", "genre": "五言古诗", "paragraphs": "慈母手中线，\n游子身上衣。\n临行密密缝，\n意恐迟迟归。\n谁言寸草心，\n报得三春晖。", "annotation": "游子：离家远行的人。密密缝：把衣服缝得严实。意恐：担心。寸草：小草，喻子女。三春晖：春天阳光，喻母爱。", "translation": "慈母用手中的针线，为远行的儿子赶制身上的衣衫。临行前一针针密密地缝缀，怕的是儿子回来得太晚。谁说儿女像小草那样微小的孝心，能够报答得了像春晖普泽的慈母恩情呢？", "appreciation": "题注写着「迎母溧上作」——五十岁的孟郊把母亲接来同住，才终于有闲回想那些灯下缝衣的夜晚。全诗只写一针一线，结句忽然升为天问：寸草心如何报得三春晖？答案是不必报，也报不了。母爱之诗千千万，这一首成为天下共同的碑文。", "mood": "思乡", "famousLine": "谁言寸草心，报得三春晖", "poetName": "孟郊"}, {"id": 84, "title": "早春呈水部张十八员外", "subtitle": "", "poetId": 34, "dynasty": "唐", "genre": "七言绝句", "paragraphs": "天街小雨润如酥，\n草色遥看近却无。\n最是一年春好处，\n绝胜烟柳满皇都。", "annotation": "呈：恭敬地送上。天街：京城街道。润如酥：细腻如酥油。处：时。绝胜：远远胜过。皇都：长安。", "translation": "京城街道上空的雨润滑如酥油，远望草色依稀连成一片，近看却显得稀疏零星。这是一年中最美的季节，远胜过绿柳满城的晚春。", "appreciation": "「草色遥看近却无」九个字，只有真正蹲下来找过春天的人才写得出来——那是若有若无的一层新绿，走近了反而消失。韩愈一生写硬文章，这一首却软得像酥：原来铁骨文宗眼里，一年春好处，就藏在将绿未绿的毫厘之间。", "mood": "山水", "famousLine": "草色遥看近却无", "poetName": "韩愈"}, {"id": 85, "title": "寻隐者不遇", "subtitle": "", "poetId": 35, "dynasty": "唐", "genre": "五言绝句", "paragraphs": "松下问童子，\n言师采药去。\n只在此山中，\n云深不知处。", "annotation": "童子：隐者的徒弟。言：说。处：地方。", "translation": "苍松下，我询问了年少的学童；他说，师傅已经采药去了山中。他还对我说，就在这座大山里，山中云雾缭绕，不知道他的行踪。", "appreciation": "一问三答，问答之间全是留白：师傅不在，去采药了，就在这座山——但云深不知处。寻人不遇本该怅然，诗却越读越开阔：隐者虽未见，松、山、云俱在，他早已化进这片云雾里。不遇之遇，恰是隐者的出场方式。", "mood": "闲适", "famousLine": "只在此山中，云深不知处", "poetName": "贾岛"}, {"id": 86, "title": "滁州西涧", "subtitle": "", "poetId": 36, "dynasty": "唐", "genre": "七言绝句", "paragraphs": "独怜幽草涧边生，\n上有黄鹂深树鸣。\n春潮带雨晚来急，\n野渡无人舟自横。", "annotation": "独怜：唯独喜爱。幽草：幽谷里的小草。深树：枝叶茂密的树。野渡：荒郊野外无人管理的渡口。", "translation": "最是喜爱涧边生长的幽幽野草，还有那树丛深处婉转啼唱的黄鹂。春潮不断上涨，还夹带着密密细雨。荒野渡口无人，只有一只小船悠闲地横在水面。", "appreciation": "一个傍晚渡口的即景：幽草、黄鹂、急雨、空船。「舟自横」三字最妙——无人渡口，船自己横着，任凭春潮拍打。做过玄宗侍卫的豪横少年，如今写出了中国诗里最安闲的「闲」：不是无人问津的冷落，是自得其所的从容。", "mood": "山水", "famousLine": "春潮带雨晚来急，野渡无人舟自横", "poetName": "韦应物"}, {"id": 87, "title": "秋词", "subtitle": "", "poetId": 37, "dynasty": "唐", "genre": "七言绝句", "paragraphs": "自古逢秋悲寂寥，\n我言秋日胜春朝。\n晴空一鹤排云上，\n便引诗情到碧霄。", "annotation": "悲寂寥：悲叹萧条空寂。春朝：春天的早晨。排：推开。碧霄：青天。", "translation": "自古以来每逢秋天都会感到悲叹冷清，我却认为秋天要远胜春天。万里晴空中一只仙鹤推开云层扶摇直上，便引发我的诗情飞到了青天之上。", "appreciation": "被贬朗州的第一年，他偏要为秋天翻案。中国文学自宋玉以来「悲秋」成传统，他一句「我言秋日胜春朝」直接掀桌——理由不是辩论，是一只鹤：晴空排云，直上碧霄。把一只鸟的起飞写成了自己精神姿态的宣言。这就是诗豪：命运往下按，他向上飞。", "mood": "悲秋", "famousLine": "晴空一鹤排云上，便引诗情到碧霄", "poetName": "刘禹锡"}, {"id": 88, "title": "望洞庭", "subtitle": "", "poetId": 37, "dynasty": "唐", "genre": "七言绝句", "paragraphs": "湖光秋月两相和，\n潭面无风镜未磨。\n遥望洞庭山水翠，\n白银盘里一青螺。", "annotation": "和：和谐。潭面：湖面。镜未磨：古铜镜未经打磨则暗淡无光，此形容湖面朦胧。白银盘：形容湖面。青螺：形容君山。", "translation": "洞庭湖的水光与秋月交相融合，水面风平浪静，就好像铜镜没有打磨。遥望洞庭湖，山青水绿，那湖中的君山，就像白银盘里放着一只小小的青螺。", "appreciation": "秋夜望湖，他给出的比喻是器物系的：未磨之镜、白银之盘、一粒青螺——把八百里洞庭缩进了一间案头。小中见大，是诗豪独有的举重若轻。刘禹锡一生两度流放、八次搬迁，笔下的山水却始终这样干净从容。", "mood": "山水", "famousLine": "遥望洞庭山水翠，白银盘里一青螺", "poetName": "刘禹锡"}, {"id": 89, "title": "乌衣巷", "subtitle": "", "poetId": 37, "dynasty": "唐", "genre": "七言绝句", "paragraphs": "朱雀桥边野草花，\n乌衣巷口夕阳斜。\n旧时王谢堂前燕，\n飞入寻常百姓家。", "annotation": "朱雀桥：秦淮河上的浮桥，正对朱雀门。乌衣巷：金陵城内街名，东晋王导、谢安两大望族居此。王谢：王导、谢安家族。", "translation": "朱雀桥边冷落荒凉长满野草野花，乌衣巷口断壁残垣正是夕阳西斜。当年王导、谢安檐下的燕子，如今已飞进寻常百姓家中。", "appreciation": "金陵怀古第一名篇。野草、夕阳，铺垫足矣，真正的杀招是一只燕子：它曾是王谢堂前的座上客，如今飞进了百姓家。荣华易主、世事翻覆，全让一只鸟轻飘飘带出——不着一字议论，而沧海桑田俱在其中。白居易读罢「掉头苦吟，叹赏良久」。", "mood": "怀人", "famousLine": "旧时王谢堂前燕，飞入寻常百姓家", "poetName": "刘禹锡"}, {"id": 90, "title": "酬乐天扬州初逢席上见赠", "subtitle": "", "poetId": 37, "dynasty": "唐", "genre": "七言律诗", "paragraphs": "巴山楚水凄凉地，\n二十三年弃置身。\n怀旧空吟闻笛赋，\n到乡翻似烂柯人。\n沉舟侧畔千帆过，\n病树前头万木春。\n今日听君歌一曲，\n暂凭杯酒长精神。", "annotation": "酬：答谢。乐天：白居易的字。闻笛赋：向秀《思旧赋》，怀念被杀故友。烂柯人：传说晋人王质观棋，斧柄烂尽，回乡已过百年。长：振作。", "translation": "在巴山楚水这些凄凉的地方，度过了二十三年沦落的时光。怀念故友只能空吟《思旧赋》，回到家乡恍如隔世的烂柯人。沉船的旁边正有千帆竞发，病树的前头却是万木争春。今天听了你为我吟诵的诗篇，暂且借这一杯美酒振奋精神。", "appreciation": "被贬二十三年，白居易席上一句同情令他百感交集。但他给出的不是诉苦，是「沉舟侧畔千帆过，病树前头万木春」——把自己放进沉舟病树的位置，却以豁达看见万物更新。腹诽命运而面朝春光，这十四字成为中国人自我宽解的通用药方。", "mood": "哲理", "famousLine": "沉舟侧畔千帆过，病树前头万木春", "poetName": "刘禹锡"}, {"id": 91, "title": "离思", "subtitle": "其四", "poetId": 38, "dynasty": "唐", "genre": "七言绝句", "paragraphs": "曾经沧海难为水，\n除却巫山不是云。\n取次花丛懒回顾，\n半缘修道半缘君。", "annotation": "曾经：曾经历过。沧海：大海。巫山：巫山之云为神女所化，最美。取次：随便，任意。缘：因为。", "translation": "经历过沧海的波澜壮阔，别处的水就难以称为水；见识过巫山的云霞变幻，别处的云便算不上云。即使从繁花丛中穿行而过，也懒得回头顾盼，一半是因为修道清心，一半是因为你。", "appreciation": "悼亡诗写到极致，是把人比作唯一的水文和气象：见过沧海，别的的水都将就；见过巫山云，别的云都不算。第三句「懒回顾」妙在不是不看得见花丛，而是看过最好的之后，连回头看都觉得多余。末句半缘修道是虚，半缘君是实——全是君。", "mood": "怀人", "famousLine": "曾经沧海难为水，除却巫山不是云", "poetName": "元稹"}, {"id": 92, "title": "题都城南庄", "subtitle": "", "poetId": 39, "dynasty": "唐", "genre": "七言绝句", "paragraphs": "去年今日此门中，\n人面桃花相映红。\n人面不知何处去，\n桃花依旧笑春风。", "annotation": "人面：姑娘的脸。笑：形容桃花盛开的的样子。", "translation": "去年今天，就在这扇门里，姑娘的脸庞和鲜艳的桃花互相映衬。今日再来此地，姑娘不知去向何处，只有桃花依旧，含笑着怒放春风之中。", "appreciation": "两段结构一模一样，只换了几个字，把一次艳遇写成了永恒的怅惘。「相映红」与「笑春风」，桃花没变，变的是人面。中国文学里所有「错过」的母题，都能追溯到这二十八个字——后来那出「人面桃花」的戏曲，全是这首诗的续集。", "mood": "怀人", "famousLine": "人面不知何处去，桃花依旧笑春风", "poetName": "崔护"}, {"id": 93, "title": "悯农", "subtitle": "其二", "poetId": 40, "dynasty": "唐", "genre": "五言绝句", "paragraphs": "锄禾日当午，\n汗滴禾下土。\n谁知盘中餐，\n粒粒皆辛苦。", "annotation": "禾：谷类植物的统称。餐：饭食。", "translation": "农民在正午烈日的暴晒下锄禾，汗水从身上滴落在禾苗下的土地里。又有谁知道盘中的饭食，每颗每粒都是农民用辛勤的劳动换来的呢？", "appreciation": "前两句是农事的写实：日当午、汗滴土，没有一个抽象的词。后两句忽然转到「盘中餐」——从田头直插饭桌，让每个吃饭的人都无处躲藏。这两首《悯农》让李绅名垂诗史；讽刺的是，写「粒粒皆辛苦」的人晚年宴席极奢——诗比人可靠，这就是证明。", "mood": "家国", "famousLine": "谁知盘中餐，粒粒皆辛苦", "poetName": "李绅"}, {"id": 94, "title": "凉州词", "subtitle": "", "poetId": 41, "dynasty": "唐", "genre": "七言绝句", "paragraphs": "葡萄美酒夜光杯，\n欲饮琵琶马上催。\n醉卧沙场君莫笑，\n古来征战几人回？", "annotation": "夜光杯：用美玉制成的酒杯，可夜间发光。催：催人出征，亦指琵琶声急促助兴。沙场：战场。", "translation": "酒筵上甘醇的葡萄美酒盛满夜光杯，正要畅饮时，马上琵琶声声响起，仿佛催人出征。即使醉倒沙场，也请诸君不要笑话，古来出外打仗的，有几人能平安归来？", "appreciation": "盛唐边塞诗里最矛盾的一首：美酒、琵琶、豪宴，按说该尽兴——下一句突然是「古来征战几人回」。把必死的结局提前摆上酒桌，于是这一醉成了狂欢，也是诀别。施补华评「作悲伤语读便浅，作谐谑语读便妙」——明知回不去，还要笑着干杯，这才是盛唐的胆气。", "mood": "豪放", "famousLine": "葡萄美酒夜光杯，欲饮琵琶马上催", "poetName": "王翰"}, {"id": 95, "title": "虞美人", "subtitle": "春花秋月", "poetId": 42, "dynasty": "五代", "genre": "词", "paragraphs": "春花秋月何时了？\n往事知多少。\n小楼昨夜又东风，\n故国不堪回首月明中。\n\n雕栏玉砌应犹在，\n只是朱颜改。\n问君能有几多愁？\n恰似一江春水向东流。", "annotation": "了：了结，终结。雕栏玉砌：雕花的栏杆、玉石的台阶，指南唐宫殿。朱颜：红润的容颜。几多：多少。", "translation": "春花秋月的美好时光什么时候才能了结？往事又有多少可以追忆！昨夜小楼上又吹来了春风，在这皓月当空的夜晚，怎能忍受回忆起故国的伤痛。精雕细刻的栏杆、玉石砌成的台阶应该都还在，只是所怀念的人已衰老。要问我心中有多少哀愁，就像这不尽的滔滔春水滚滚东流。", "appreciation": "亡国之君的绝命词。宇宙循环不息（春花秋月、东风、月明），人生却一去不返（往事、朱颜）——对比之下，愁有了体积：一江春水。传说宋太宗读到「故国不堪回首」大怒，赐牵机药。这首词写于978年七夕他的生日，四十二岁——词成之日，即殒命之时。以血书者，此为绝唱。", "mood": "家国", "famousLine": "问君能有几多愁？恰似一江春水向东流", "poetName": "李煜"}, {"id": 96, "title": "相见欢", "subtitle": "无言独上西楼", "poetId": 42, "dynasty": "五代", "genre": "词", "paragraphs": "无言独上西楼，\n月如钩。\n寂寞梧桐深院锁清秋。\n\n剪不断，\n理还乱，\n是离愁。\n别是一般滋味在心头。", "annotation": "锁：笼罩。离愁：离别的愁绪。一般：一种。", "translation": "默默无言，独自一人缓缓登上西楼。抬头望天，只有一弯如钩的冷月相伴。低矮的梧桐树笼罩着深深的院落，锁住了这清冷的秋天。那剪也剪不断，理也理不清，让人心乱如麻的，正是离别之苦。那悠悠愁思缠绕心头，却又是另一种无可名状的痛苦。", "appreciation": "囚徒的月夜：月如钩，庭院如锁——一个「锁」字，锁的是清秋，更是他自己。下片把离愁写成可以剪、可以理的实物，结果是剪不断理还乱，最后干脆放弃言说：「别是一般滋味」——说不出的愁，才是最深的愁。词到李煜，才真正从歌筵工具变成心灵的独白。", "mood": "悲秋", "famousLine": "剪不断，理还乱，是离愁", "poetName": "李煜"}, {"id": 97, "title": "浪淘沙令", "subtitle": "帘外雨潺潺", "poetId": 42, "dynasty": "五代", "genre": "词", "paragraphs": "帘外雨潺潺，\n春意阑珊。\n罗衾不耐五更寒。\n梦里不知身是客，\n一晌贪欢。\n\n独自莫凭栏，\n无限江山。\n别时容易见时难。\n流水落花春去也，\n天上人间。", "annotation": "潺潺：雨声。阑珊：衰残。罗衾：绸被子。不耐：受不了。一晌：一会儿。凭栏：靠着栏杆。", "translation": "门帘外传来雨声潺潺，浓郁的春意又要凋残。罗织的锦被受不住五更时的冷寒。只有迷梦中忘掉自身是羁旅之客，才能享受片时的欢愉。独自一人在夕阳下凭栏远望，看到的是无限江山，想起别时容易见时难。流失的时光如落花随流水般逝去，过去和现在的境况对比，恍如天上人间。", "appreciation": "囚徒的春夜，五更寒里做了一个梦。梦的可怕不在醒来，而在梦里「不知身是客」——那一刻的贪欢，衬得醒来加倍残忍。「流水落花春去也，天上人间」八个字写尽了两个世界的距离。据说此词成后不久，太宗赐牵机药。王国维说他「变伶工之词而为士大夫之词」，泣血之作，可当此评。", "mood": "悲秋", "famousLine": "流水落花春去也，天上人间", "poetName": "李煜"}, {"id": 98, "title": "渔家傲", "subtitle": "秋思", "poetId": 43, "dynasty": "宋", "genre": "词", "paragraphs": "塞下秋来风景异，\n衡阳雁去无留意。\n四面边声连角起，\n千嶂里，\n长烟落日孤城闭。\n\n浊酒一杯家万里，\n燕然未勒归无计。\n羌管悠悠霜满地，\n人不寐，\n将军白发征夫泪。", "annotation": "塞下：边界要塞。衡阳雁去：大雁向衡阳飞去，传说衡阳有回雁峰。边声：边塞特有的声音，如风号、马嘶。千嶂：千山。燕然未勒：用东汉窦宪破匈奴、刻石燕然山记功之典，指战事未平。", "translation": "秋天到了，西北边塞的风光和江南不同。大雁又飞回衡阳了，一点也没有停留之意。黄昏时分，军中号角吹起，四面传来战马嘶鸣的声音。像千里屏障一样并列的山峰里，烟霭浓重，夕阳西下，孤零零的城门紧闭。饮一杯浊酒，不由想起万里之外的亲人。战事未平，功业未成，还乡的打算无从谈起。羌人的笛声悠扬，寒霜洒满大地。将士们不能安睡，将军头发已经斑白，士兵们流下眼泪。", "appreciation": "五十三岁的范仲淹戍守西北，把边塞的实景第一次大规模写进词里。风景「异」在苦寒，孤城「闭」在敌情，浊酒一杯与家万里对举，责任与乡愁撕扯着每一个戍边人。全词悲而不颓：白发与泪，是在「燕然未勒」的前提下流的。这首词下开了苏辛豪放一派的先声。", "mood": "家国", "famousLine": "浊酒一杯家万里，燕然未勒归无计", "poetName": "范仲淹"}, {"id": 99, "title": "苏幕遮", "subtitle": "怀旧", "poetId": 43, "dynasty": "宋", "genre": "词", "paragraphs": "碧云天，\n黄叶地，\n秋色连波，\n波上寒烟翠。\n山映斜阳天接水，\n芳草无情，\n更在斜阳外。\n\n黯乡魂，\n追旅思，\n夜夜除非，\n好梦留人睡。\n明月楼高休独倚，\n酒入愁肠，\n化作相思泪。", "annotation": "黯乡魂：因思念家乡而心情黯然。追旅思：羁旅的愁思纠缠不休。", "translation": "碧云悠悠，黄叶满地，秋色连向远方的水波，波上弥漫着苍翠的寒烟。群山映着斜阳，天空连接着江水，不解人意的芳草无边无际，延伸到斜阳之外的天边。思念故乡黯然销魂，羁旅的愁思纠缠不休，除非夜夜都做好梦，才能得到片刻安睡。明月高照的夜晚，不要独自登上高楼，借酒浇愁，酒入愁肠，都化作相思的眼泪。", "appreciation": "上片写景阔大清丽，「碧云天，黄叶地」六字后来被《西厢记》整句化用；「芳草更在斜阳外」把空间推向无穷——故乡就在芳草的尽头之外。下片「酒入愁肠，化作相思泪」是全词最沉的一句：连酒都拦不住的乡愁。铁腕宰相的柔情，全在这一滴泪里。", "mood": "思乡", "famousLine": "酒入愁肠，化作相思泪", "poetName": "范仲淹"}, {"id": 100, "title": "浣溪沙", "subtitle": "一曲新词酒一杯", "poetId": 44, "dynasty": "宋", "genre": "词", "paragraphs": "一曲新词酒一杯，\n去年天气旧亭台。\n夕阳西下几时回？\n\n无可奈何花落去，\n似曾相识燕归来。\n小园香径独徘徊。", "annotation": "香径：落花飘香的小路。", "translation": "听一曲新词，饮一杯酒，天气和去年一样，亭台也还是旧亭台。西下的夕阳几时才能回来？无可奈何中百花凋落，似曾相识的春燕又归来了。我独自在满是落花香气的小路上徘徊。", "appreciation": "太平宰相的词，最动人的却是这层淡淡的惆怅：年年一样的亭台天气，回不来的夕阳，留不住的花。妙在下一句立刻接住——花落了，燕子回来了，「似曾相识」四个字把消逝与重临写成了时间的双面。没有答案，只剩「独徘徊」：在循环的时间里，人就是这样一边失去一边生活。", "mood": "哲理", "famousLine": "无可奈何花落去，似曾相识燕归来", "poetName": "晏殊"}, {"id": 101, "title": "临江仙", "subtitle": "梦后楼台高锁", "poetId": 45, "dynasty": "宋", "genre": "词", "paragraphs": "梦后楼台高锁，\n酒醒帘幕低垂。\n去年春恨却来时。\n落花人独立，\n微雨燕双飞。\n\n记得小蘋初见，\n两重心字罗衣。\n琵琶弦上说相思。\n当时明月在，\n曾照彩云归。", "annotation": "小蘋：歌女的名字。心字罗衣：绣有心字图案的罗衣。彩云：喻小蘋。", "translation": "梦醒后高楼锁着，酒醒时帘幕低垂。去年的春愁涌上心头。人在落花中独自站着，微雨里燕子双双飞。记得初次见到小蘋，她穿着绣有两重心字的罗衣。琵琶弹奏着相思。当时的明月还在，曾照着她如彩云般归去。", "appreciation": "「落花人独立，微雨燕双飞」——谭献称为「千古不能有二」的名句：花落、人独、雨微、燕双，四组意象互相映照，孤独有了具体的形状。结尾「当时明月在，曾照彩云归」更狠：月亮还是那轮，彩云已散。晏几道一生不攀附权贵，只把真心留给回忆里的歌女——古之伤心人，当之无愧。", "mood": "怀人", "famousLine": "落花人独立，微雨燕双飞", "poetName": "晏几道"}, {"id": 102, "title": "鹊桥仙", "subtitle": "纤云弄巧", "poetId": 46, "dynasty": "宋", "genre": "词", "paragraphs": "纤云弄巧，\n飞星传恨，\n银汉迢迢暗度。\n金风玉露一相逢，\n便胜却人间无数。\n\n柔情似水，\n佳期如梦，\n忍顾鹊桥归路。\n两情若是久长时，\n又岂在朝朝暮暮。", "annotation": "纤云：轻盈的云彩。飞星：流星。银汉：银河。金风玉露：秋风白露，点明七夕。忍顾：怎忍回头看。朝朝暮暮：日日夜夜相守。", "translation": "轻盈的云彩在天空中变幻出许多优美巧妙的图案，流星传递着相思的怨愁，牛郎和织女正渡过遥远无垠的银河。在秋风白露的七夕相会，就胜过尘世间那些长相厮守却貌合神离的夫妻。缱绻的柔情像流水般绵绵不断，重逢的约会如梦影般缥缈虚幻，分别之时不忍去看那鹊桥路。若是两情相悦，天长地久，又何必贪求卿卿我我的朝欢暮乐。", "appreciation": "写七夕的词千千万，唯有秦观翻出了新意：牛郎织女一年一会，不是悲剧的极限，而是爱情的极致——「金风玉露一相逢，便胜却人间无数」。结句「两情若是久长时，又岂在朝朝暮暮」更把相思升华为信念：爱的高度不由长度丈量。写尽离愁的伤心人，给天下分离者递上了一碗最亮的解药。", "mood": "怀人", "famousLine": "两情若是久长时，又岂在朝朝暮暮", "poetName": "秦观"}, {"id": 103, "title": "卜算子", "subtitle": "我住长江头", "poetId": 47, "dynasty": "宋", "genre": "词", "paragraphs": "我住长江头，\n君住长江尾。\n日日思君不见君，\n共饮长江水。\n\n此水几时休，\n此恨何时已。\n只愿君心似我心，\n定不负相思意。", "annotation": "已：停止。定：一定。", "translation": "我居住在长江上游，你居住在长江下游。天天想念你却见不到你，共同喝着长江的水。长江之水，悠悠东流，什么时候才能休止？我的相思离别之情，什么时候才能停止？只希望你的心思像我的心意一样，就一定不会辜负这互相思念的心意。", "appreciation": "一条长江，被她写成了一条情的脐带：住在头与尾的两个人，靠「共饮一江水」维系着联系。语言像民歌一样干净，情感却层层推进：思念—共饮—问水—问恨—许愿。与汉乐府《上邪》对读最有趣：誓言换成祈祷，毒誓化作「只愿君心似我心」——更软，也更狠。", "mood": "怀人", "famousLine": "日日思君不见君，共饮长江水", "poetName": "李之仪"}, {"id": 104, "title": "观书有感", "subtitle": "其一", "poetId": 48, "dynasty": "宋", "genre": "七言绝句", "paragraphs": "半亩方塘一鉴开，\n天光云影共徘徊。\n问渠那得清如许？\n为有源头活水来。", "annotation": "鉴：镜子。开：像镜子被打开。渠：它，指方塘。那得：怎么会。如许：如此。为：因为。", "translation": "半亩方塘像一面打开的镜子，天光和云影一同在水中徘徊。要问这方塘为何这样清澈？因为源头总有活水不断流来。", "appreciation": "一首「读书诗」，却半字不提书：方塘是心，天光云影是书中的世界，「问渠那得清如许」问的是——心怎么才能如此澄明？答案是源头活水，不断有新的思想注入。理学家写诗，最怕干巴巴讲道理；朱熹这一首把哲理泡进了水光里，成了宋诗理趣的教科书。", "mood": "哲理", "famousLine": "问渠那得清如许？为有源头活水来", "poetName": "朱熹"}, {"id": 105, "title": "小池", "subtitle": "", "poetId": 49, "dynasty": "宋", "genre": "七言绝句", "paragraphs": "泉眼无声惜细流，\n树阴照水爱晴柔。\n小荷才露尖尖角，\n早有蜻蜓立上头。", "annotation": "泉眼：泉水的出口。惜：爱惜。晴柔：晴天里柔和的风光。尖尖角：荷叶初生的尖端。", "translation": "泉眼悄然无声，是因舍不得细细的水流；树阴倒映水面，是喜爱晴天和风的轻柔。娇嫩的小荷叶刚从水面露出尖尖的角，早就有一只蜻蜓立在上面了。", "appreciation": "一个「惜」、一个「爱」，泉眼与树阴都有了感情——这是诚斋体的看家本领：万物有灵，诗人只是替它们代言。后两句是抢拍的镜头：荷角才露，蜻蜓先至。自然界的细微瞬间被杨万里拍下，此后「小荷才露尖尖角」成了形容新生事物初露头角的成语。", "mood": "闲适", "famousLine": "小荷才露尖尖角，早有蜻蜓立上头", "poetName": "杨万里"}, {"id": 106, "title": "晓出净慈寺送林子方", "subtitle": "", "poetId": 49, "dynasty": "宋", "genre": "七言绝句", "paragraphs": "毕竟西湖六月中，\n风光不与四时同。\n接天莲叶无穷碧，\n映日荷花别样红。", "annotation": "毕竟：到底。四时：四季。别样：格外。", "translation": "六月里的西湖风光到底和其他时节不同：莲叶接天，无边无际的青翠；荷花映着太阳，红得格外好看。", "appreciation": "送别诗不写别情，通篇写景——但「接天莲叶无穷碧，映日荷花别样红」这壮阔，本身就是祝福：他把最美的西湖夏景留在朋友心里。这首诗在诗歌史上等于给西湖定了宣传语；写它的人一生清廉，「囊金只有一钱余」，笔下却富可敌国。", "mood": "山水", "famousLine": "接天莲叶无穷碧，映日荷花别样红", "poetName": "杨万里"}, {"id": 107, "title": "游园不值", "subtitle": "", "poetId": 50, "dynasty": "宋", "genre": "七言绝句", "paragraphs": "应怜屐齿印苍苔，\n小扣柴扉久不开。\n春色满园关不住，\n一枝红杏出墙来。", "annotation": "不值：没有遇到人。屐齿：木屐的齿。小扣：轻轻敲。柴扉：柴门。", "translation": "也许是园主担心我的木屐踩坏他那爱惜的青苔，我轻轻地敲打柴门，久久地没有人来开。可是这满园的春色毕竟是关不住的，一枝开得正艳的红杏已经伸出墙外来了。", "appreciation": "访友不遇，本是败兴事，诗人却在柴门外站住了：门虽然关着，春色关不住——一枝红杏替整座园子递出了请柬。「关不住」「出墙来」，两个动作把春天写成了活物。人生很多“不值”的时刻，换个角度看，都是被另一种惊喜接待了。", "mood": "闲适", "famousLine": "春色满园关不住，一枝红杏出墙来", "poetName": "叶绍翁"}, {"id": 108, "title": "约客", "subtitle": "", "poetId": 51, "dynasty": "宋", "genre": "七言绝句", "paragraphs": "黄梅时节家家雨，\n青草池塘处处蛙。\n有约不来过夜半，\n闲敲棋子落灯花。", "annotation": "约客：邀请客人。黄梅时节：江南梅子黄熟的雨季。灯花：灯芯燃烧结的花状物。", "translation": "梅子黄熟的季节，家家都被笼罩在雨中，长满青草的池塘边传来蛙声阵阵。时间已过午夜，约好的客人还没有来，我无聊地轻轻敲着棋子，震落了灯芯上的灯花。", "appreciation": "约人下棋，客人半夜没来——全诗就写这个「等」。前两句是听觉的雨与蛙，越热闹越衬得屋内安静；「闲敲棋子落灯花」是全诗的画眼：一个动作，把漫长的无聊写出了优雅。等待本身成了风景，这是宋人特有的克制与风雅。", "mood": "闲适", "famousLine": "有约不来过夜半，闲敲棋子落灯花", "poetName": "赵师秀"}, {"id": 109, "title": "题临安邸", "subtitle": "", "poetId": 52, "dynasty": "宋", "genre": "七言绝句", "paragraphs": "山外青山楼外楼，\n西湖歌舞几时休？\n暖风熏得游人醉，\n直把杭州作汴州。", "annotation": "邸：旅舍。休：停止。熏：吹。直：简直。汴州：北宋都城汴京，已被金占领。", "translation": "青山之外还有青山，高楼之外还有高楼，湖中的歌舞何时才能停止？暖风把游人熏得陶醉，简直把杭州当成了故都汴州。", "appreciation": "写在旅舍墙壁上的诗，成了南宋最锋利的一根刺。前两句极写临安的繁华——山外有山，楼外有楼，歌舞不休；后两句图穷匕见：醉生梦死的「游人」们，早忘了汴州陷落。全诗不着一个愤字，而愤懑透纸。题壁无名，却是南宋诗里流传最广的一首。", "mood": "家国", "famousLine": "暖风熏得游人醉，直把杭州作汴州", "poetName": "林升"}, {"id": 110, "title": "满江红", "subtitle": "怒发冲冠", "poetId": 53, "dynasty": "宋", "genre": "词", "paragraphs": "怒发冲冠，\n凭栏处、潇潇雨歇。\n抬望眼，\n仰天长啸，\n壮怀激烈。\n三十功名尘与土，\n八千里路云和月。\n莫等闲、\n白了少年头，\n空悲切。\n\n靖康耻，\n犹未雪。\n臣子恨，\n何时灭。\n驾长车，\n踏破贺兰山缺。\n壮志饥餐胡虏肉，\n笑谈渴饮匈奴血。\n待从头、\n收拾旧山河，\n朝天阙。", "annotation": "怒发冲冠：愤怒得头发竖起顶起帽子。潇潇：雨势急骤。长啸：大声呼啸。三十功名：岳飞三十余岁而立此功名。靖康：宋钦宗年号，1127年金陷汴京掳徽钦二帝。朝天阙：朝见皇帝。", "translation": "愤怒得头发竖起，帽子都被顶起，独自登楼凭栏远眺，急骤的风雨刚刚停歇。抬头仰望天空，禁不住仰天长啸，满腔报国之心充满激烈。三十多年来的功名如同尘土，转战南北八千里经过多少风云人生。不要虚度光阴，等少年的头发变白，独自悔恨悲悲切切。靖康年的奇耻大辱，至今也没有洗雪。作为国家臣子的愤恨，何时才能泯灭！我要驾着战车向贺兰山进攻，连贺兰山也要踏为平地。我满怀壮志，打仗饿了就吃敌人的肉，谈笑间渴了就喝敌人的鲜血。待我重新收复旧日山河，再带着捷报向国家报告胜利的消息！", "appreciation": "气吞山河的还我河山宣言。上片自叙：三十功名不过尘土，八千里路唯有云月——功名看得轻，时光看得重，「莫等闲」三字是对自己的鞭策，也敲打着后来每一个虚度的日子。下片国仇雪恨，字字金石声。此词是否岳飞手笔虽有争论，但它早已与这个人物、这段历史融为一体：读「待从头、收拾旧山河」，没有人不热血。", "mood": "家国", "famousLine": "莫等闲、白了少年头，空悲切", "poetName": "岳飞"}, {"id": 111, "title": "过零丁洋", "subtitle": "", "poetId": 54, "dynasty": "宋", "genre": "七言律诗", "paragraphs": "辛苦遭逢起一经，\n干戈寥落四周星。\n山河破碎风飘絮，\n身世浮沉雨打萍。\n惶恐滩头说惶恐，\n零丁洋里叹零丁。\n人生自古谁无死？\n留取丹心照汗青。", "annotation": "遭逢：遭遇朝廷选拔。起一经：因精通经书而做官。四周星：四年。风飘絮：如风中柳絮。汗青：史册。", "translation": "回想我早年由科举入仕历尽辛苦，如今战火消歇已熬过了四个年头。国家危在旦夕恰如狂风中的柳絮，个人又哪堪说似骤雨里的浮萍。惶恐滩的惨败让我至今依然惶恐，零丁洋身陷元虏可叹我孤苦零丁。人生自古以来有谁能够长生不死？我要留一片爱国的丹心映照史册。", "appreciation": "前六句把国破与身世对仗成双：山河是风中柳絮，自己是雨里浮萍，地名惶恐与零丁又恰好嵌进心事——天意般的巧对。到第七句忽然跳出对仗的迷宫，直接发问：人生自古谁无死？然后是那个光照千古的回答。被俘的宰相以十四字定调了自己的结局，也定调了中国人的生死观。", "mood": "家国", "famousLine": "人生自古谁无死？留取丹心照汗青", "poetName": "文天祥"}, {"id": 112, "title": "天净沙", "subtitle": "秋思", "poetId": 55, "dynasty": "元", "genre": "曲", "paragraphs": "枯藤老树昏鸦，\n小桥流水人家，\n古道西风瘦马。\n夕阳西下，\n断肠人在天涯。", "annotation": "天净沙：曲牌名。昏鸦：黄昏归巢的乌鸦。断肠人：极度悲伤的人。天涯：天边，指远离家乡的地方。", "translation": "天色黄昏，一群乌鸦落在枯藤缠绕的老树上，发出凄厉的哀鸣。小桥下流水哗哗作响，小桥边庄户人家炊烟袅袅。古城道上，一匹瘦马驮着游子顶着西风前行。夕阳渐渐失去了光泽，从西边落下。凄寒的夜色里，只有孤独的旅人漂泊在遥远的地方。", "appreciation": "二十八个字，九个名词，无一动词作主干，却押出一幅完整的深秋羁旅图：前三句各是一个镜头——枯藤老树是萧瑟，小桥流水是温暖，瘦马古道是漂泊；暖的一句恰是反衬，他人有家，而我独在天涯。周德清评为「秋思之祖」，王国维称其「纯是天籁」：曲到马致远，散曲才第一次有了诗的重量。", "mood": "悲秋", "famousLine": "夕阳西下，断肠人在天涯", "poetName": "马致远"}, {"id": 113, "title": "墨梅", "subtitle": "", "poetId": 56, "dynasty": "元", "genre": "七言绝句", "paragraphs": "吾家洗砚池头树，\n个个花开淡墨痕。\n不要人夸好颜色，\n只留清气满乾坤。", "annotation": "洗砚池：传说王羲之临池学书，池水尽黑，此处借用自指。淡墨痕：以淡墨点画的花痕。清气：清香的气味，亦指清高的气节。", "translation": "我家洗砚池边有一棵梅树，朵朵梅花都像是淡淡的墨痕。它并不需要别人夸奖颜色多么好看，只是要将清香之气充满天地之间。", "appreciation": "一个画家的题画诗：画中墨梅没有颜色，他索性把「不设色」写成了品格宣言——不要人夸好颜色，只留清气满乾坤。王冕一生拒绝出仕，种豆种梅自食其力；这两句是他给画的自白，也是给自己一生盖章：删掉所有铅华，只留一身清香。", "mood": "哲理", "famousLine": "不要人夸好颜色，只留清气满乾坤", "poetName": "王冕"}, {"id": 114, "title": "石灰吟", "subtitle": "", "poetId": 57, "dynasty": "明", "genre": "七言绝句", "paragraphs": "千锤万凿出深山，\n烈火焚烧若等闲。\n粉骨碎身浑不怕，\n要留清白在人间。", "annotation": "千锤万凿：无数次锤击开凿。若等闲：好像很平常。浑不怕：全然不怕。清白：石灰白色，喻人格清白。", "translation": "只有经过千万次锤打才能从深山里开采出来，它把烈火的焚烧看作很平常的一件事。即使粉身碎骨也毫不惧怕，只要把高尚的节操留在人世间。", "appreciation": "十二岁于谦写下这首咏物言志诗，像是提前写好了自己的一生：石灰的四道工序——开采、煅烧、粉碎、留下洁白——对应着读书人锤炼、历难、赴死、留名的全部过程。北京保卫战后他遭冤杀，抄家时「家无余财」。他真的做到了：粉骨碎身，清白在人间。", "mood": "家国", "famousLine": "粉骨碎身浑不怕，要留清白在人间", "poetName": "于谦"}, {"id": 115, "title": "桃花庵歌", "subtitle": "", "poetId": 58, "dynasty": "明", "genre": "七言古诗", "paragraphs": "桃花坞里桃花庵，\n桃花庵下桃花仙。\n桃花仙人种桃树，\n又摘桃花换酒钱。\n酒醒只在花前坐，\n酒醉还来花下眠。\n半醉半醒日复日，\n花落花开年复年。\n但愿老死花酒间，\n不愿鞠躬车马前。\n车尘马足富者趣，\n酒盏花枝贫者缘。\n若将富贵比贫贱，\n一在平地一在天。\n若将贫贱比车马，\n他得驱驰我得闲。\n别人笑我太疯癫，\n我笑他人看不穿。\n不见五陵豪杰墓，\n无花无酒锄作田。", "annotation": "桃花坞：苏州地名，唐寅在此筑桃花庵。车马：代指权贵。五陵：汉代五个皇帝陵墓，附近多豪门聚居，代指富贵者。", "translation": "桃花坞里有座桃花庵，桃花庵下住着桃花仙。桃花仙人种了桃树，又摘桃花换酒钱。酒醒时只在花前坐下，酒醉了就来花下睡眠。半醉半醒之间一天天过去，花开花落一年又一年。只希望在赏花饮酒中老去，不愿意在权贵的车马前躬身行礼。车尘马足是富人的乐趣，酒盏花枝是穷人的缘分。如果将富贵和贫贱相比，一个在天上一个在地下。如果将贫贱和车马相比，他们得到的是奔驰之劳，我得到的是闲适之乐。别人笑我太疯癫，我却笑别人看不穿世事。不见那五陵豪杰的墓冢吗，没有花没有酒，如今都被锄成了种田的田地。", "appreciation": "科场案把唐寅从解元变成了贱籍小吏，他用这首长歌完成人生的重新表态：桃花、酒、闲——与「车尘马足」的世界划清界限。全诗二十个「花」「酒」字回环往复，近乎民谣，却句句都是唱给体制的反调。结尾更狠：你们追求的富贵，最后不过是无花无酒的坟头田。狂，是天才被辜负后的自救方式。", "mood": "闲适", "famousLine": "别人笑我太疯癫，我笑他人看不穿", "poetName": "唐寅"}, {"id": 116, "title": "木兰词", "subtitle": "拟古决绝词柬友", "poetId": 59, "dynasty": "清", "genre": "词", "paragraphs": "人生若只如初见，\n何事秋风悲画扇。\n等闲变却故人心，\n却道故人心易变。\n骊山语罢清宵半，\n泪雨霖铃终不怨。\n何如薄幸锦衣郎，\n比翼连枝当日愿。", "annotation": "柬：给……的信。画扇：秋扇见捐喻被弃。骊山句：用唐玄宗与杨贵妃七夕骊山盟誓之典。泪雨霖铃：玄宗蜀道闻铃作《雨霖铃》悼贵妃。何如：怎比。薄幸：薄情。", "translation": "与意中人相处，如果后来产生了怨恨、埋怨，没有了刚刚相识的美好、淡然，那么一切还是停留在初次见面的时候为好。如今轻易地变了心，你却反倒说情人间本来就容易变心。想当初唐皇与贵妃在骊山盟誓，虽有泪雨霖铃的诀别，却终究没有怨言。而你又怎么比得上当年的唐明皇呢，他总还是与杨贵妃有过比翼鸟、连理枝的誓愿。", "appreciation": "词题是「拟古决绝词」，写给朋友的，却是天下所有被辜负者的共同心声。首句「人生若只如初见」七字，把爱情中最易逝的那个瞬间定格成永恒的祈愿——此后成了汉语中被引用最多的词句之一。中段用唐玄宗杨贵妃的典故反问：连帝妃尚有生死之盟，你这薄幸人连当日之愿都不肯认。伤心的极致，是不肯骂出口。", "mood": "怀人", "famousLine": "人生若只如初见，何事秋风悲画扇", "poetName": "纳兰性德"}, {"id": 117, "title": "长相思", "subtitle": "山一程", "poetId": 59, "dynasty": "清", "genre": "词", "paragraphs": "山一程，\n水一程，\n身向榆关那畔行，\n夜深千帐灯。\n\n风一更，\n雪一更，\n聒碎乡心梦不成，\n故园无此声。", "annotation": "程：里程。榆关：山海关。那畔：那边。千帐灯：皇帝出征时随行的上千顶帐篷的灯火。更：旧时一夜分五更。聒：声音嘈杂。", "translation": "将士们跋山涉水，向山海关那边进发。夜已深，营帐中千万顶帐篷里都点起了灯。帐篷外风声一阵接着一阵，雪花伴着风声落下，嘈杂的声音打碎了思乡的梦，在家里可没有这样的声音。", "appreciation": "随康熙出关东巡的一夜，他写出了清词里最辽阔的思乡。「夜深千帐灯」是豪景，「聒碎乡心梦不成」是柔肠——外面千帐灯的壮阔与心里故园的静好对叠，身在锦绣丛中，心在灯火阑珊处。王国维赞「明月照积雪」式的壮美，此词兼得。", "mood": "思乡", "famousLine": "夜深千帐灯", "poetName": "纳兰性德"}, {"id": 118, "title": "己亥杂诗", "subtitle": "其五", "poetId": 60, "dynasty": "清", "genre": "七言绝句", "paragraphs": "浩荡离愁白日斜，\n吟鞭东指即天涯。\n落红不是无情物，\n化作春泥更护花。", "annotation": "浩荡：无边无际。吟鞭：诗人的马鞭。天涯：指作者家乡杭州。", "translation": "离别京都的愁思浩如水波，也像夕阳西下之时，挥动马鞭向东一指，从此远行天涯。从枝头上掉下来的落花不是无情之物，化作春天的泥土，还能培育出更美丽的花。", "appreciation": "辞官南归的离愁写在斜阳里，本是一路伤感；后两句却让这场告别升华：落红不是无情物，化作春泥更护花。离开官场，仍要滋养后来的花开——四十年后戊戌变法的志士，几乎人人读他的书。「落花」意象自龚自珍始，从悼惜变成了奉献。", "mood": "家国", "famousLine": "落红不是无情物，化作春泥更护花", "poetName": "龚自珍"}, {"id": 119, "title": "己亥杂诗", "subtitle": "其一百二十五", "poetId": 60, "dynasty": "清", "genre": "七言绝句", "paragraphs": "九州生气恃风雷，\n万马齐喑究可哀。\n我劝天公重抖擞，\n不拘一格降人才。", "annotation": "九州：中国。生气：生机勃勃的局面。恃：依靠。喑：哑。究：终究。抖擞：振作。降：降生。", "translation": "只有狂雷炸响般的巨大力量才能使中国大地发出勃勃生机，然而社会政局毫无生气终究是一种悲哀。我奉劝上天要重新振作精神，不要拘泥一定规格，以降下更多的人才。", "appreciation": "诗前有小序：过镇江时见赛玉皇及风神雷神，道士乞撰青词，遂「祭神」写就此篇——名为祭天，实为谏国。「万马齐喑」四字写尽思想禁锢的死寂，「不拘一格降人才」则是对整个选才制度的呐喊。这四句后来成了变革者共同的战歌。", "mood": "家国", "famousLine": "我劝天公重抖擞，不拘一格降人才", "poetName": "龚自珍"}, {"id": 120, "title": "苔", "subtitle": "", "poetId": 61, "dynasty": "清", "genre": "五言绝句", "paragraphs": "白日不到处，\n青春恰自来。\n苔花如米小，\n也学牡丹开。", "annotation": "白日：阳光。青春：指苔的绿意，也指生机。亦：也。", "translation": "春天明媚的阳光照不到的地方，青苔的绿意依然自己到来。苔花虽然像米粒一样微小，却依然像那高贵的牡丹一样热烈绽放。", "appreciation": "写给一切不被光照见的生命：阳光照不到，青春照样自己来。米粒大的苔花，「也学牡丹开」——一个「学」字，有卑微者的认真，也有小生命的骄傲。袁枚主张性灵，诗写小人物、小动物、小角落；两百年后这首小诗被谱成歌传唱，因为每个普通人都在里面看见了自己。", "mood": "哲理", "famousLine": "苔花如米小，也学牡丹开", "poetName": "袁枚"}, {"id": 121, "title": "竹石", "subtitle": "", "poetId": 62, "dynasty": "清", "genre": "七言绝句", "paragraphs": "咬定青山不放松，\n立根原在破岩中。\n千磨万击还坚劲，\n任尔东西南北风。", "annotation": "咬定：比喻竹根扎得结实。立根：扎根。破岩：破裂的岩石缝隙。坚劲：坚韧刚劲。任尔：随你。", "translation": "竹子抓住青山一点也不放松，它的根牢牢地扎在破裂的岩石中。经历千万次磨难和打击，它还是那样坚韧挺拔，不管是东风西风，还是南风北风，都不能把它吹倒。", "appreciation": "题画诗：画的是竹，立的是人。「咬定」二字起笔奇崛，竹子的根须仿佛有了牙齿；长在破岩里，经千磨万击，任四面来风——每一句都是郑板桥的仕途写照：五十岁才中进士，做县令为民请赈丢了官帽。罢官之后他卖画为生，价格表都写得意气扬扬——根扎得深的人，风往哪吹都无所谓。", "mood": "壮志", "famousLine": "千磨万击还坚劲，任尔东西南北风", "poetName": "郑燮"}];
